INSERT INTO public.biblioteca_vectores (id,coleccion,materia,contenido,num_articulo,fuente,metadata,embedding,jurisdiccion,fuente_tipo,es_norma_vigente,revision_pendiente,instrumento_id,num_articulo_norm,hash_contenido,ingest_batch,ingested_at) VALUES
('A03_CODIGO_NINEZ_01:CODIGO_NINEZ:146','mayalex_normativos','10_LEYES_REGLAMENTOS','A los(as) responsables de incumplimiento de lo establecido en los artículos 143, 144 y 145 precedentes se les sancionará con multa de cinco (5) a quince (15) salarios mínimos en su valor más alto, la que impondrá el titular de la institución a quien corresponda. La indicada multa se aplicará sin perjuicio de la responsabilidad civil y penal a que hubiere lugar en Derecho.

Para la deducción de estas responsabilidades, se informará y al Ministerio Público sobre los hechos de que se trate, cuando éstos sean constitutivos de delito.','146','Código de la Niñez y de la Adolescencia (Decreto 73-96), texto canónico v2 con las reformas del Decreto 35-2013 (La Gaceta 33,222)','{"texto_origen":"CANONICO_D3_FUENTES_MIXTAS","transcripcion_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","text_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","cotejado_por":"Abg. y Not. Fredy Omar Pinel Flores, propietario_despacho (CLO / Director Maya Lex), firma D3 del 2026-11-18 sobre la v2 de HN:CODIGO_NINEZ (ADJUDICACION_CLO_CODIGO_NINEZ.md §3)","manifiesto_sha256":"bd4d067d1ff2980db99a7527d21f9f381d996bb0a2d63933e30f7bcaecb2d372","pliego":"docs/corpus/staging/2026-11-04-hn-001-tranche-a-drive/canonico-v2/ADJUDICACION_CLO_CODIGO_NINEZ.md","procedencia":"Fuentes mixtas acreditadas por el pliego D1–D8 firmado (ver estado_canonico de cada fila); sin V4/V5 hasta el SQL de visibilidad","norm_id":"HN:CODIGO_NINEZ","instrumento_id":"CODIGO_NINEZ","ingest_batch":"A03_CODIGO_NINEZ_01","ordinal":151,"article_sha256":"56b0b93a3778e5813419386863ba1600eb3d525a9f4f9aaebfd7474a09ec91d2","vigencia":"UNKNOWN","revision_pendiente":true,"marcas":[],"estado_canonico":"TEXTO_V8_D3","fuente_canonica":"V8_LA_GACETA_33222"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_NINEZ','146','38d605b8de24d8b62769076a0f8cebc91d3aa6fd8a49c4cd86b6c0562245c8c4','A03_CODIGO_NINEZ_01',now()),
('A03_CODIGO_NINEZ_01:CODIGO_NINEZ:147','mayalex_normativos','10_LEYES_REGLAMENTOS','Corresponde al Instituto Hondureño de la Niñez y la Familia (IHNFA), conocer, investigar y determinar la existencia de causales de las situaciones de abandono y de incumplimiento de derechos de la niñez en sede administrativa. El Instituto Hondureño de la Niñez y la Familia (IHNFA) actuará de oficio o a petición de cualquier persona, debiendo emitir auto motivado con las pruebas y argumentos presentados, en el que declarará admitida o desestimada la solicitud o archivadas las diligencias, según sea el caso.

Si admite la solicitud o actúa de oficio, adoptará las medidas de protección que sean necesarias y citará a una audiencia con la participación del padre, madre o representante legal, si se conociera su paradero, en su defecto citará a cualquier persona bajo cuyo cuidado haya estado el niño o niña de que se trate. Tal audiencia se realizará en el término de cinco (5) días contados a partir de la fecha del auto en que se dio inicio el procedimiento. Si se desconoce el paradero de los padres o representantes legales el término será de ocho (8) días, ordenándose en el auto con que se dio inicio el proceso que se realicen tres (3) publicaciones en dos (2) diarios escritos, hablados o televisivos de circulación nacional, incluyendo la fotografía del niño o niña o señas particulares, según el caso.

La denuncia de abandono podrá ser presentada verbalmente o por escrito, por cualquier persona natural o jurídica, debiendo contenerlo siguiente:

1) Nombre del niño o niña si se supiere y en su defecto señas particulares del(a) mismo(a); 2) Nombre de los padres o representantes legales o de la persona a cuyo cargo estaba o está el niño o niña, si se supiere y en su defecto señas particulares del mismo; 3) Lugar en que se encontró o se encuentra el niño o niña; y, 4) Otro dato que sea de interés para la protección del niño o niña.','147','Código de la Niñez y de la Adolescencia (Decreto 73-96), texto canónico v2 con las reformas del Decreto 35-2013 (La Gaceta 33,222)','{"texto_origen":"CANONICO_D3_FUENTES_MIXTAS","transcripcion_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","text_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","cotejado_por":"Abg. y Not. Fredy Omar Pinel Flores, propietario_despacho (CLO / Director Maya Lex), firma D3 del 2026-11-18 sobre la v2 de HN:CODIGO_NINEZ (ADJUDICACION_CLO_CODIGO_NINEZ.md §3)","manifiesto_sha256":"bd4d067d1ff2980db99a7527d21f9f381d996bb0a2d63933e30f7bcaecb2d372","pliego":"docs/corpus/staging/2026-11-04-hn-001-tranche-a-drive/canonico-v2/ADJUDICACION_CLO_CODIGO_NINEZ.md","procedencia":"Fuentes mixtas acreditadas por el pliego D1–D8 firmado (ver estado_canonico de cada fila); sin V4/V5 hasta el SQL de visibilidad","norm_id":"HN:CODIGO_NINEZ","instrumento_id":"CODIGO_NINEZ","ingest_batch":"A03_CODIGO_NINEZ_01","ordinal":152,"article_sha256":"928bd0cd95fbe17889b916028c3b530d0e45be1341482f15fbe11be4de63fcba","vigencia":"UNKNOWN","revision_pendiente":true,"marcas":[],"estado_canonico":"TEXTO_V8_D3","fuente_canonica":"V8_LA_GACETA_33222"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_NINEZ','147','af8e4f1f1607d1164ac1031588515f801b78450174e8167cd2c959e5c5b8d880','A03_CODIGO_NINEZ_01',now()),
('A03_CODIGO_NINEZ_01:CODIGO_NINEZ:147-A','mayalex_normativos','10_LEYES_REGLAMENTOS','En la audiencia, el Instituto Hondureño de la Niñez y la Familia (IHNFA) conocerá los informes técnicos correspondientes, así como el parecer de las personas que haya citado, asimismo recibirá las pruebas que se aporten y dictará resolución en la que declare el abandono en sede administrativa o desestime el mismo.

La Resolución que declare la situación de abandono y de incumplimiento de derechos de un niño o niña será notificada al(la) representante legal de éste y a quienes hayan comparecido atendiendo la citación, en ésta se incluirá una relación de, al menos, los aspectos siguientes:

1) Nombre completo del niño o niña si se supiere y en su defecto señas particulares del mismo, en este último caso ordenará que de inmediato se tomen las medidas necesarias para garantizarle el derecho al nombre; 2) Nombre del padre, madre o representantes legales o de la persona a cuyo cargo estaba o está el niño o niña; 3) Lugar en que se encontró el niño o niña; 4) Estudios técnicos realizados; 5) Medidas adoptadas; y, 6) Lugar, día, nombre completo y título de la autoridad que emite la Resolución.

La resolución, acompañada de la documentación de respaldo correspondiente será elevada al conocimiento del(la) Juez de Letras de la Niñez o quien haga sus veces, en el término de tres (3) días contados a partir de que la misma quede firme.

Supletoriamente se aplicará a este procedimiento lo establecido en la Ley de Procedimiento Administrativo.','147-A','Código de la Niñez y de la Adolescencia (Decreto 73-96), texto canónico v2 con las reformas del Decreto 35-2013 (La Gaceta 33,222)','{"texto_origen":"CANONICO_D3_FUENTES_MIXTAS","transcripcion_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","text_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","cotejado_por":"Abg. y Not. Fredy Omar Pinel Flores, propietario_despacho (CLO / Director Maya Lex), firma D3 del 2026-11-18 sobre la v2 de HN:CODIGO_NINEZ (ADJUDICACION_CLO_CODIGO_NINEZ.md §3)","manifiesto_sha256":"bd4d067d1ff2980db99a7527d21f9f381d996bb0a2d63933e30f7bcaecb2d372","pliego":"docs/corpus/staging/2026-11-04-hn-001-tranche-a-drive/canonico-v2/ADJUDICACION_CLO_CODIGO_NINEZ.md","procedencia":"Fuentes mixtas acreditadas por el pliego D1–D8 firmado (ver estado_canonico de cada fila); sin V4/V5 hasta el SQL de visibilidad","norm_id":"HN:CODIGO_NINEZ","instrumento_id":"CODIGO_NINEZ","ingest_batch":"A03_CODIGO_NINEZ_01","ordinal":153,"article_sha256":"10c55104f4466124f3ff471a113fd3531cd70c938683c16d52747a51238c784d","vigencia":"UNKNOWN","revision_pendiente":true,"marcas":[],"estado_canonico":"TEXTO_V8_D3_ADICIONADO","fuente_canonica":"V8_LA_GACETA_33222"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_NINEZ','147-A','5eb9fdf83d9f96cafe1ea6504f5265e1190e28f9484d10daa11e6fb5cfc6f636','A03_CODIGO_NINEZ_01',now()),
('A03_CODIGO_NINEZ_01:CODIGO_NINEZ:147-B','mayalex_normativos','10_LEYES_REGLAMENTOS','El (la) Juez(a) de Letras de la Niñez citará al padre, madre o representantes legales del niño o niña declarado en abandono en sede administrativa y al Instituto Hondureño de la Niñez y la Familia (IHNFA), así como a cualquier otra persona que estime procedente, para una audiencia que se celebrará en el término de tres (3) días contados a partir de la fecha en que se reciba en el Juzgado la declaratoria administrativa. Con las argumentaciones y pruebas que se le presenten y evacúen en la audiencia dictará sentencia, la que al menos contendrá:

1) Nombre completo del niño o niña; 2) Nombre de los padres o representantes legales; 3) Una breve relación de las consideraciones técnicas argumentadas por el Instituto Hondureño de la Niñez y la Familia (IHNFA) para declarar el abandono en sede administrativa, así como de quienes se opongan en su caso; 4) Medidas adoptadas, con expresión de las que se mantengan, levanten o impongan; 5) Declaración de abandono o desestimación del mismo y, 6) Lugar, día, nombre completo y título de la autoridad que emite la Resolución.','147-B','Código de la Niñez y de la Adolescencia (Decreto 73-96), texto canónico v2 con las reformas del Decreto 35-2013 (La Gaceta 33,222)','{"texto_origen":"CANONICO_D3_FUENTES_MIXTAS","transcripcion_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","text_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","cotejado_por":"Abg. y Not. Fredy Omar Pinel Flores, propietario_despacho (CLO / Director Maya Lex), firma D3 del 2026-11-18 sobre la v2 de HN:CODIGO_NINEZ (ADJUDICACION_CLO_CODIGO_NINEZ.md §3)","manifiesto_sha256":"bd4d067d1ff2980db99a7527d21f9f381d996bb0a2d63933e30f7bcaecb2d372","pliego":"docs/corpus/staging/2026-11-04-hn-001-tranche-a-drive/canonico-v2/ADJUDICACION_CLO_CODIGO_NINEZ.md","procedencia":"Fuentes mixtas acreditadas por el pliego D1–D8 firmado (ver estado_canonico de cada fila); sin V4/V5 hasta el SQL de visibilidad","norm_id":"HN:CODIGO_NINEZ","instrumento_id":"CODIGO_NINEZ","ingest_batch":"A03_CODIGO_NINEZ_01","ordinal":154,"article_sha256":"6e24a66ec2b83984e1ef3ebf55d838d59ef08771f020e71a626297d66c0042df","vigencia":"UNKNOWN","revision_pendiente":true,"marcas":[],"estado_canonico":"TEXTO_V8_D3_ADICIONADO","fuente_canonica":"V8_LA_GACETA_33222"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_NINEZ','147-B','f3e81a0fd4d82f6fc1607bdd05011c461810a11a38c132f73132662a84055b14','A03_CODIGO_NINEZ_01',now()),
('A03_CODIGO_NINEZ_01:CODIGO_NINEZ:147-C','mayalex_normativos','10_LEYES_REGLAMENTOS','En todos los procedimientos aquí indicados se garantizará al niño o niña todos los derechos establecidos en el presente Código, en particular su derecho a ser oído(a) y que su opinión sea tenida en cuenta durante todo el proceso considerando su edad y grado de madurez así como a ser asistido por un(a) abogado(a). En todo caso, se procurará la permanencia del niño o niña en su medio familiar y en su centro de vida.

Durante todo el procedimiento se garantizará el cumplimiento del derecho de confidencialidad.','147-C','Código de la Niñez y de la Adolescencia (Decreto 73-96), texto canónico v2 con las reformas del Decreto 35-2013 (La Gaceta 33,222)','{"texto_origen":"CANONICO_D3_FUENTES_MIXTAS","transcripcion_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","text_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","cotejado_por":"Abg. y Not. Fredy Omar Pinel Flores, propietario_despacho (CLO / Director Maya Lex), firma D3 del 2026-11-18 sobre la v2 de HN:CODIGO_NINEZ (ADJUDICACION_CLO_CODIGO_NINEZ.md §3)","manifiesto_sha256":"bd4d067d1ff2980db99a7527d21f9f381d996bb0a2d63933e30f7bcaecb2d372","pliego":"docs/corpus/staging/2026-11-04-hn-001-tranche-a-drive/canonico-v2/ADJUDICACION_CLO_CODIGO_NINEZ.md","procedencia":"Fuentes mixtas acreditadas por el pliego D1–D8 firmado (ver estado_canonico de cada fila); sin V4/V5 hasta el SQL de visibilidad","norm_id":"HN:CODIGO_NINEZ","instrumento_id":"CODIGO_NINEZ","ingest_batch":"A03_CODIGO_NINEZ_01","ordinal":155,"article_sha256":"545fd887a66e1020d818e9c6cba36425e5ce8aa21ff26b0c69294ff042170380","vigencia":"UNKNOWN","revision_pendiente":true,"marcas":[],"estado_canonico":"TEXTO_V8_D3_ADICIONADO","fuente_canonica":"V8_LA_GACETA_33222"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_NINEZ','147-C','4c181d07ff4d5a258654661e4a11b9227fa3190c2c9610258dc6a11eb4614a3d','A03_CODIGO_NINEZ_01',now()),
('A03_CODIGO_NINEZ_01:CODIGO_NINEZ:147-D','mayalex_normativos','10_LEYES_REGLAMENTOS','Toda persona con interés legítimo podrá oponerse a la declaratoria de abandono o incumplimiento de derechos de un niño o niña, ya sea en vía administrativa o judicial, para lo que deberá presentar escrito en el que fundamente su oposición y acompañe o proponga los medios de prueba pertinentes. El(la) Juez(a) o la autoridad administrativa correspondiente, resolverá de plano en el acto o en el término de cuarenta y ocho (48) horas a partir de la presentación de la oposición.

Si encontrare méritos en la oposición, incorporará al(la) oponente en el procedimiento; de haberse realizado la audiencia y lo estime necesario, podrá citar a nueva audiencia en la que dilucidará el asunto, siempre y cuando no esté firme la resolución o sentencia correspondiente.','147-D','Código de la Niñez y de la Adolescencia (Decreto 73-96), texto canónico v2 con las reformas del Decreto 35-2013 (La Gaceta 33,222)','{"texto_origen":"CANONICO_D3_FUENTES_MIXTAS","transcripcion_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","text_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","cotejado_por":"Abg. y Not. Fredy Omar Pinel Flores, propietario_despacho (CLO / Director Maya Lex), firma D3 del 2026-11-18 sobre la v2 de HN:CODIGO_NINEZ (ADJUDICACION_CLO_CODIGO_NINEZ.md §3)","manifiesto_sha256":"bd4d067d1ff2980db99a7527d21f9f381d996bb0a2d63933e30f7bcaecb2d372","pliego":"docs/corpus/staging/2026-11-04-hn-001-tranche-a-drive/canonico-v2/ADJUDICACION_CLO_CODIGO_NINEZ.md","procedencia":"Fuentes mixtas acreditadas por el pliego D1–D8 firmado (ver estado_canonico de cada fila); sin V4/V5 hasta el SQL de visibilidad","norm_id":"HN:CODIGO_NINEZ","instrumento_id":"CODIGO_NINEZ","ingest_batch":"A03_CODIGO_NINEZ_01","ordinal":156,"article_sha256":"2b9c07cc80f8cfbc1c880a16d93bf6480ea0e7e0a79b67f441d45fd8991d60c9","vigencia":"UNKNOWN","revision_pendiente":true,"marcas":[],"estado_canonico":"TEXTO_V8_D3_ADICIONADO","fuente_canonica":"V8_LA_GACETA_33222"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_NINEZ','147-D','ee8a1e2ce1855e1f64255cff39d54cc98ad82b02220fb6fab6e936e2f5775849','A03_CODIGO_NINEZ_01',now()),
('A03_CODIGO_NINEZ_01:CODIGO_NINEZ:147-E','mayalex_normativos','10_LEYES_REGLAMENTOS','Si como resultado de la investigación se establece que el niño o niña ha sido víctima de un delito, el Instituto Hondureño de la Niñez y la Familia (IHNFA) testimoniará las actuaciones y las remitirá al Ministerio Público, a efecto de promoverse las diligencias necesarias para sancionar al(a) responsable.','147-E','Código de la Niñez y de la Adolescencia (Decreto 73-96), texto canónico v2 con las reformas del Decreto 35-2013 (La Gaceta 33,222)','{"texto_origen":"CANONICO_D3_FUENTES_MIXTAS","transcripcion_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","text_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","cotejado_por":"Abg. y Not. Fredy Omar Pinel Flores, propietario_despacho (CLO / Director Maya Lex), firma D3 del 2026-11-18 sobre la v2 de HN:CODIGO_NINEZ (ADJUDICACION_CLO_CODIGO_NINEZ.md §3)","manifiesto_sha256":"bd4d067d1ff2980db99a7527d21f9f381d996bb0a2d63933e30f7bcaecb2d372","pliego":"docs/corpus/staging/2026-11-04-hn-001-tranche-a-drive/canonico-v2/ADJUDICACION_CLO_CODIGO_NINEZ.md","procedencia":"Fuentes mixtas acreditadas por el pliego D1–D8 firmado (ver estado_canonico de cada fila); sin V4/V5 hasta el SQL de visibilidad","norm_id":"HN:CODIGO_NINEZ","instrumento_id":"CODIGO_NINEZ","ingest_batch":"A03_CODIGO_NINEZ_01","ordinal":157,"article_sha256":"fe6aa540ee90bcbd5fe340b4c2f33ecd2228157d86d83f823f0f318a05fadb10","vigencia":"UNKNOWN","revision_pendiente":true,"marcas":[],"estado_canonico":"TEXTO_V8_D3_ADICIONADO","fuente_canonica":"V8_LA_GACETA_33222"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_NINEZ','147-E','dfcb916aca33d99a8165e07e2dc0f2f34ebb07cff19f0bddfd4adc6ce1a98e79','A03_CODIGO_NINEZ_01',now()),
('A03_CODIGO_NINEZ_01:CODIGO_NINEZ:148','mayalex_normativos','10_LEYES_REGLAMENTOS','En los asuntos a que se refiere esta Sección el Instituto Hondureño de la Niñez y la Familia (IHNFA) procederá de conformidad con la Ley de Procedimiento Administrativo. La correspondiente resolución que emita siempre será motivada y contra ella cabrán los recursos de reposición y apelación subsidiaria ante el órgano superior jerárquico.','148','Código de la Niñez y de la Adolescencia (Decreto 73-96), texto canónico v2 con las reformas del Decreto 35-2013 (La Gaceta 33,222)','{"texto_origen":"CANONICO_D3_FUENTES_MIXTAS","transcripcion_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","text_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","cotejado_por":"Abg. y Not. Fredy Omar Pinel Flores, propietario_despacho (CLO / Director Maya Lex), firma D3 del 2026-11-18 sobre la v2 de HN:CODIGO_NINEZ (ADJUDICACION_CLO_CODIGO_NINEZ.md §3)","manifiesto_sha256":"bd4d067d1ff2980db99a7527d21f9f381d996bb0a2d63933e30f7bcaecb2d372","pliego":"docs/corpus/staging/2026-11-04-hn-001-tranche-a-drive/canonico-v2/ADJUDICACION_CLO_CODIGO_NINEZ.md","procedencia":"Fuentes mixtas acreditadas por el pliego D1–D8 firmado (ver estado_canonico de cada fila); sin V4/V5 hasta el SQL de visibilidad","norm_id":"HN:CODIGO_NINEZ","instrumento_id":"CODIGO_NINEZ","ingest_batch":"A03_CODIGO_NINEZ_01","ordinal":158,"article_sha256":"7476d2a36319f4c23e8677c2e49894394c59764689a2eb055266a193c16e64d1","vigencia":"UNKNOWN","revision_pendiente":true,"marcas":[],"estado_canonico":"TEXTO_V8_D3","fuente_canonica":"V8_LA_GACETA_33222"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_NINEZ','148','8a2f770876bbf108c52dc54b80d018edd78db9838695a201f4f4796e9274c5cd','A03_CODIGO_NINEZ_01',now()),
('A03_CODIGO_NINEZ_01:CODIGO_NINEZ:149','mayalex_normativos','10_LEYES_REGLAMENTOS','La declaratoria de que un(a) niño(a) se encuentra en situación de abandono o de vulnerabilidad de sus derechos obliga al Instituto Hondureño de la Niñez y la Familia (IHNFA) a proceder de inmediato a brindarle la protección que necesite. Cuando las circunstancias lo exijan, el Juzgado de Letras de la Niñez competente, o el que haga sus veces, a petición del IHNFA, ordenará el allanamiento del sitio donde el niño o niña se encuentre.

Durante todo el tiempo en que se mantenga vigente la declaración del niño(a) en situación de vulneración de derechos, el Poder Ejecutivo, por intermedio de Instituto Hondureño de la Niñez y la Familia (IHNFA), dispondrá un programa de seguimiento, incluyendo atención médica, psicológica o psiquiátrica del niño o niña, o de su padre, madres, responsable o representantes legales.','149','Código de la Niñez y de la Adolescencia (Decreto 73-96), texto canónico v2 con las reformas del Decreto 35-2013 (La Gaceta 33,222)','{"texto_origen":"CANONICO_D3_FUENTES_MIXTAS","transcripcion_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","text_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","cotejado_por":"Abg. y Not. Fredy Omar Pinel Flores, propietario_despacho (CLO / Director Maya Lex), firma D3 del 2026-11-18 sobre la v2 de HN:CODIGO_NINEZ (ADJUDICACION_CLO_CODIGO_NINEZ.md §3)","manifiesto_sha256":"bd4d067d1ff2980db99a7527d21f9f381d996bb0a2d63933e30f7bcaecb2d372","pliego":"docs/corpus/staging/2026-11-04-hn-001-tranche-a-drive/canonico-v2/ADJUDICACION_CLO_CODIGO_NINEZ.md","procedencia":"Fuentes mixtas acreditadas por el pliego D1–D8 firmado (ver estado_canonico de cada fila); sin V4/V5 hasta el SQL de visibilidad","norm_id":"HN:CODIGO_NINEZ","instrumento_id":"CODIGO_NINEZ","ingest_batch":"A03_CODIGO_NINEZ_01","ordinal":159,"article_sha256":"63398b9920c455b2064517dcaa27fd16d952707c5b5242e3c72d5087ef8268c4","vigencia":"UNKNOWN","revision_pendiente":true,"marcas":[],"estado_canonico":"TEXTO_V8_D3","fuente_canonica":"V8_LA_GACETA_33222"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_NINEZ','149','7f875a84c1b3b797ee633b11784ff2c8c6dc7622c754f51be27360dc50b6045b','A03_CODIGO_NINEZ_01',now()),
('A03_CODIGO_NINEZ_01:CODIGO_NINEZ:150','mayalex_normativos','10_LEYES_REGLAMENTOS','Los niños y niñas declarados(as) en situación de abandono o vulnerados en sus derechos, serán protegidos con las medidas siguientes:

a) Prevención o amonestación a los padres, madres o representantes legales; b) Atribución de su custodia o cuidado personal al pariente por consanguinidad más próximo que se encuentre en condiciones de ejercerlos o en su defecto por afinidad; c) Ingreso en familia sustituta o solidaria; d) Como última alternativa, su ingreso en un centro de protección, ya sea este del (IHNFA) o privado debidamente autorizado por éste; y, e) Cualquier otra medida, cuya finalidad sea la de asegurar el cuidado personal del niño o niña, atender sus necesidades básicas o poner fin a los peligros que amenacen su salud, su dignidad o su formación moral.

En los casos de los literales b), c), d); y, e), las medidas serán siempre excepcionales y provisionales, debiéndose tomar en cuenta el Interés Superior del Niño o Niña.

Si los padres, o representantes legales del niño o niña cuentan con los medios necesarios, el Instituto Hondureño de la Niñez y la Familia (IHNFA) podrá fijarles una cuota mensual para que contribuyan a su sostenimiento mientras se encuentre bajo una medida de protección.','150','Código de la Niñez y de la Adolescencia (Decreto 73-96), texto canónico v2 con las reformas del Decreto 35-2013 (La Gaceta 33,222)','{"texto_origen":"CANONICO_D3_FUENTES_MIXTAS","transcripcion_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","text_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","cotejado_por":"Abg. y Not. Fredy Omar Pinel Flores, propietario_despacho (CLO / Director Maya Lex), firma D3 del 2026-11-18 sobre la v2 de HN:CODIGO_NINEZ (ADJUDICACION_CLO_CODIGO_NINEZ.md §3)","manifiesto_sha256":"bd4d067d1ff2980db99a7527d21f9f381d996bb0a2d63933e30f7bcaecb2d372","pliego":"docs/corpus/staging/2026-11-04-hn-001-tranche-a-drive/canonico-v2/ADJUDICACION_CLO_CODIGO_NINEZ.md","procedencia":"Fuentes mixtas acreditadas por el pliego D1–D8 firmado (ver estado_canonico de cada fila); sin V4/V5 hasta el SQL de visibilidad","norm_id":"HN:CODIGO_NINEZ","instrumento_id":"CODIGO_NINEZ","ingest_batch":"A03_CODIGO_NINEZ_01","ordinal":160,"article_sha256":"315369d631db59e9ce3c4e7aa50c0e5d3895e7bfe280f3170dc3dd65be11fb79","vigencia":"UNKNOWN","revision_pendiente":true,"marcas":[],"estado_canonico":"TEXTO_V8_D3","fuente_canonica":"V8_LA_GACETA_33222"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_NINEZ','150','d396a8f5047f17cb5b95e6b50903f1ce31022ce27e4cf5e33b4e68dc50081b72','A03_CODIGO_NINEZ_01',now()),
('A03_CODIGO_NINEZ_01:CODIGO_NINEZ:151','mayalex_normativos','10_LEYES_REGLAMENTOS','El Instituto hondureño de la Niñez y la Familia, con el objeto de asegurar la adecuada atención al niño en el seno de su familia, podrá disponer, si lo cree conveniente, que los padres o el representante legal a cuyo cuidado se encuentre, cumplan alguna de las actividades siguientes:

a) Asistir a programas oficiales o comunitarios de orientación o tratamiento familiar.

b) Asistir a programas de asesoría, orientación o tratamiento de alcohólicos o adictos a sustancias que produzcan dependencias, cuando sea el caso.

c) Asistir a programas de tratamientos sicológico o siquiátrico; o, ch) Participar en cualquier otra actividad que contribuya a garantizar un ambiente adecuado para el desarrollo del niño.','151','Código de la Niñez y de la Adolescencia (Decreto 73-96), texto canónico v2 con las reformas del Decreto 35-2013 (La Gaceta 33,222)','{"texto_origen":"CANONICO_D3_FUENTES_MIXTAS","transcripcion_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","text_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","cotejado_por":"Abg. y Not. Fredy Omar Pinel Flores, propietario_despacho (CLO / Director Maya Lex), firma D3 del 2026-11-18 sobre la v2 de HN:CODIGO_NINEZ (ADJUDICACION_CLO_CODIGO_NINEZ.md §3)","manifiesto_sha256":"bd4d067d1ff2980db99a7527d21f9f381d996bb0a2d63933e30f7bcaecb2d372","pliego":"docs/corpus/staging/2026-11-04-hn-001-tranche-a-drive/canonico-v2/ADJUDICACION_CLO_CODIGO_NINEZ.md","procedencia":"Fuentes mixtas acreditadas por el pliego D1–D8 firmado (ver estado_canonico de cada fila); sin V4/V5 hasta el SQL de visibilidad","norm_id":"HN:CODIGO_NINEZ","instrumento_id":"CODIGO_NINEZ","ingest_batch":"A03_CODIGO_NINEZ_01","ordinal":161,"article_sha256":"7d6d91c8bb5283f6847e74f43e08d3aa62b89902db3b935a2316639872e25d70","vigencia":"UNKNOWN","revision_pendiente":true,"marcas":[],"estado_canonico":"TEXTO_A03_DICTAMINADO_CLO","fuente_canonica":"A03_CONSOLIDADO_DICTAMINADO"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_NINEZ','151','2f837d2b1c9b9f3d1b0690a7df3f158adbc23a067c2025511b8aad91f3b3fcbc','A03_CODIGO_NINEZ_01',now()),
('A03_CODIGO_NINEZ_01:CODIGO_NINEZ:152','mayalex_normativos','10_LEYES_REGLAMENTOS','Quien ejerza la Patria Potestad sobre el niño o niña, o su representante legal, podrá solicitar la terminación de los efectos de la declaración de abandono, cuando se demuestre que se han superado las circunstancias que le dieron lugar y que hay razonables motivos para esperar que no volverán a producirse.

Lo dispuesto en este Artículo no será aplicable cuando el niño o niña haya sido dado(a) en adopción o cuando quien ejerza la Patria Potestad sea reincidente.

El Juzgado de Letras de la Niñez accederá a lo pedido si, después de efectuadas las investigaciones pertinentes, considera probado lo argumentado por los(las) peticionarios.','152','Código de la Niñez y de la Adolescencia (Decreto 73-96), texto canónico v2 con las reformas del Decreto 35-2013 (La Gaceta 33,222)','{"texto_origen":"CANONICO_D3_FUENTES_MIXTAS","transcripcion_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","text_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","cotejado_por":"Abg. y Not. Fredy Omar Pinel Flores, propietario_despacho (CLO / Director Maya Lex), firma D3 del 2026-11-18 sobre la v2 de HN:CODIGO_NINEZ (ADJUDICACION_CLO_CODIGO_NINEZ.md §3)","manifiesto_sha256":"bd4d067d1ff2980db99a7527d21f9f381d996bb0a2d63933e30f7bcaecb2d372","pliego":"docs/corpus/staging/2026-11-04-hn-001-tranche-a-drive/canonico-v2/ADJUDICACION_CLO_CODIGO_NINEZ.md","procedencia":"Fuentes mixtas acreditadas por el pliego D1–D8 firmado (ver estado_canonico de cada fila); sin V4/V5 hasta el SQL de visibilidad","norm_id":"HN:CODIGO_NINEZ","instrumento_id":"CODIGO_NINEZ","ingest_batch":"A03_CODIGO_NINEZ_01","ordinal":162,"article_sha256":"2dd38daefb3bc9bcce0f2fd207888689ddc6d427330f69e27eee4b132c46a014","vigencia":"UNKNOWN","revision_pendiente":true,"marcas":[],"estado_canonico":"TEXTO_V8_D3","fuente_canonica":"V8_LA_GACETA_33222"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_NINEZ','152','07adfbb9386940db831f1352ad637d9d6e5bb4faab90efb6b6d8f25ec0b51ae7','A03_CODIGO_NINEZ_01',now()),
('A03_CODIGO_NINEZ_01:CODIGO_NINEZ:153','mayalex_normativos','10_LEYES_REGLAMENTOS','El Poder Ejecutivo, por medio de la Secretaría de Estado en los Despachos de Interior y Población, reglamentará a iniciativa del Instituto Hondureño de la Niñez y la Familia, todo lo relacionado con las medidas de protección a que se refiere en la presente Sección.','153','Código de la Niñez y de la Adolescencia (Decreto 73-96), texto canónico v2 con las reformas del Decreto 35-2013 (La Gaceta 33,222)','{"texto_origen":"CANONICO_D3_FUENTES_MIXTAS","transcripcion_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","text_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","cotejado_por":"Abg. y Not. Fredy Omar Pinel Flores, propietario_despacho (CLO / Director Maya Lex), firma D3 del 2026-11-18 sobre la v2 de HN:CODIGO_NINEZ (ADJUDICACION_CLO_CODIGO_NINEZ.md §3)","manifiesto_sha256":"bd4d067d1ff2980db99a7527d21f9f381d996bb0a2d63933e30f7bcaecb2d372","pliego":"docs/corpus/staging/2026-11-04-hn-001-tranche-a-drive/canonico-v2/ADJUDICACION_CLO_CODIGO_NINEZ.md","procedencia":"Fuentes mixtas acreditadas por el pliego D1–D8 firmado (ver estado_canonico de cada fila); sin V4/V5 hasta el SQL de visibilidad","norm_id":"HN:CODIGO_NINEZ","instrumento_id":"CODIGO_NINEZ","ingest_batch":"A03_CODIGO_NINEZ_01","ordinal":163,"article_sha256":"7a5fb68e917419375f7c89aac70d06f8dd1e6bed95f5f46b50981cc77254f766","vigencia":"UNKNOWN","revision_pendiente":true,"marcas":[],"estado_canonico":"TEXTO_A03_DICTAMINADO_CLO","fuente_canonica":"A03_CONSOLIDADO_DICTAMINADO"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_NINEZ','153','34808dc1700175e9861b09de1f1bd3375608396db032bb70396f5c0f49da0213','A03_CODIGO_NINEZ_01',now()),
('A03_CODIGO_NINEZ_01:CODIGO_NINEZ:154','mayalex_normativos','10_LEYES_REGLAMENTOS','Se entenderá que un niño o niña carece de la atención suficiente para la satisfacción de sus necesidades básicas, cuando carece de medios para atender su subsistencia, o cuando las personas encargadas de su cuidado se niegan a suministrárselo o lo hagan de manera insuficiente.','154','Código de la Niñez y de la Adolescencia (Decreto 73-96), texto canónico v2 con las reformas del Decreto 35-2013 (La Gaceta 33,222)','{"texto_origen":"CANONICO_D3_FUENTES_MIXTAS","transcripcion_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","text_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","cotejado_por":"Abg. y Not. Fredy Omar Pinel Flores, propietario_despacho (CLO / Director Maya Lex), firma D3 del 2026-11-18 sobre la v2 de HN:CODIGO_NINEZ (ADJUDICACION_CLO_CODIGO_NINEZ.md §3)","manifiesto_sha256":"bd4d067d1ff2980db99a7527d21f9f381d996bb0a2d63933e30f7bcaecb2d372","pliego":"docs/corpus/staging/2026-11-04-hn-001-tranche-a-drive/canonico-v2/ADJUDICACION_CLO_CODIGO_NINEZ.md","procedencia":"Fuentes mixtas acreditadas por el pliego D1–D8 firmado (ver estado_canonico de cada fila); sin V4/V5 hasta el SQL de visibilidad","norm_id":"HN:CODIGO_NINEZ","instrumento_id":"CODIGO_NINEZ","ingest_batch":"A03_CODIGO_NINEZ_01","ordinal":164,"article_sha256":"6025d52760d42343a5f7dc6748a3ca807aa1f2f6b0be12ca92bb056502799184","vigencia":"UNKNOWN","revision_pendiente":true,"marcas":[],"estado_canonico":"TEXTO_V8_D3","fuente_canonica":"V8_LA_GACETA_33222"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_NINEZ','154','c3a4084fd922eb4d52a9afe9d530cbc44e5c8ee942667f168f723f2930b9853e','A03_CODIGO_NINEZ_01',now()),
('A03_CODIGO_NINEZ_01:CODIGO_NINEZ:155','mayalex_normativos','10_LEYES_REGLAMENTOS','El Estado le prestará al niño que se encuentre en la situación prevista en el artículo anterior el concurso necesario para imponer a los responsables de la obligación alimentaria el cumplimiento de la misma.

Si dichas personas carecen de medios suficientes para atender ese deber, la atención será dispensada por el Instituto Hondureño de la Niñez y la Familia con el concurso de aquéllas y de la comunidad.','155','Código de la Niñez y de la Adolescencia (Decreto 73-96), texto canónico v2 con las reformas del Decreto 35-2013 (La Gaceta 33,222)','{"texto_origen":"CANONICO_D3_FUENTES_MIXTAS","transcripcion_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","text_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","cotejado_por":"Abg. y Not. Fredy Omar Pinel Flores, propietario_despacho (CLO / Director Maya Lex), firma D3 del 2026-11-18 sobre la v2 de HN:CODIGO_NINEZ (ADJUDICACION_CLO_CODIGO_NINEZ.md §3)","manifiesto_sha256":"bd4d067d1ff2980db99a7527d21f9f381d996bb0a2d63933e30f7bcaecb2d372","pliego":"docs/corpus/staging/2026-11-04-hn-001-tranche-a-drive/canonico-v2/ADJUDICACION_CLO_CODIGO_NINEZ.md","procedencia":"Fuentes mixtas acreditadas por el pliego D1–D8 firmado (ver estado_canonico de cada fila); sin V4/V5 hasta el SQL de visibilidad","norm_id":"HN:CODIGO_NINEZ","instrumento_id":"CODIGO_NINEZ","ingest_batch":"A03_CODIGO_NINEZ_01","ordinal":165,"article_sha256":"f1a9996df380048faef79d2f0d9e45839aee1171638b626516766e65c660a859","vigencia":"UNKNOWN","revision_pendiente":true,"marcas":[],"estado_canonico":"TEXTO_A03_DICTAMINADO_CLO","fuente_canonica":"A03_CONSOLIDADO_DICTAMINADO"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_NINEZ','155','8ef72c928e51c9610245328834c7a1f1571ae00e50143c41b785dd3550eb532e','A03_CODIGO_NINEZ_01',now()),
('A03_CODIGO_NINEZ_01:CODIGO_NINEZ:156','mayalex_normativos','10_LEYES_REGLAMENTOS','Las medidas de protección al niño que se encuentre en la situación prevista en esta sección serán adoptadas a solicitud de sus padres o representante legal, o de oficio.

Las medidas procurarán apoyar a los solicitantes, en su caso, y no separar al niño de su medio familiar.

En el cumplimiento de sus cometidos al Instituto Hondureño de la Niñez y la Familia podrá:

a) Asesorar al respectivo padre, madre o representante legal para que pueda obtener alimentos de las personas llamadas por este Código y el Código de Familia a cumplir dicha obligación; o, b) Vincularlo a los programas que en beneficio de los niños desarrolle ella misma u otros organismos públicos o privados.','156','Código de la Niñez y de la Adolescencia (Decreto 73-96), texto canónico v2 con las reformas del Decreto 35-2013 (La Gaceta 33,222)','{"texto_origen":"CANONICO_D3_FUENTES_MIXTAS","transcripcion_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","text_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","cotejado_por":"Abg. y Not. Fredy Omar Pinel Flores, propietario_despacho (CLO / Director Maya Lex), firma D3 del 2026-11-18 sobre la v2 de HN:CODIGO_NINEZ (ADJUDICACION_CLO_CODIGO_NINEZ.md §3)","manifiesto_sha256":"bd4d067d1ff2980db99a7527d21f9f381d996bb0a2d63933e30f7bcaecb2d372","pliego":"docs/corpus/staging/2026-11-04-hn-001-tranche-a-drive/canonico-v2/ADJUDICACION_CLO_CODIGO_NINEZ.md","procedencia":"Fuentes mixtas acreditadas por el pliego D1–D8 firmado (ver estado_canonico de cada fila); sin V4/V5 hasta el SQL de visibilidad","norm_id":"HN:CODIGO_NINEZ","instrumento_id":"CODIGO_NINEZ","ingest_batch":"A03_CODIGO_NINEZ_01","ordinal":166,"article_sha256":"cb65c0dc5a10034053f41862ab62d82f142a7c8c63f793a178d59e3e3600d745","vigencia":"UNKNOWN","revision_pendiente":true,"marcas":[],"estado_canonico":"TEXTO_A03_DICTAMINADO_CLO","fuente_canonica":"A03_CONSOLIDADO_DICTAMINADO"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_NINEZ','156','a1e1afae837bb63680b5146264423a608f29cd32970ec04b5876233ddb11e775','A03_CODIGO_NINEZ_01',now()),
('A03_CODIGO_NINEZ_01:CODIGO_NINEZ:157','mayalex_normativos','10_LEYES_REGLAMENTOS','Siempre que quien tenga la administración de los bienes de un niño en su condición de padre, madre o tutor ponga en peligro intereses económicos, el Instituto Hondureño de la Niñez y la Familia o el Ministerio Público promoverán ante el juzgado competente el proceso necesario para privarlo de la administración de sus bienes o para remover al guardador, en su caso, y los encaminados a obtener la reparación del perjuicio que hubieran causado.','157','Código de la Niñez y de la Adolescencia (Decreto 73-96), texto canónico v2 con las reformas del Decreto 35-2013 (La Gaceta 33,222)','{"texto_origen":"CANONICO_D3_FUENTES_MIXTAS","transcripcion_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","text_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","cotejado_por":"Abg. y Not. Fredy Omar Pinel Flores, propietario_despacho (CLO / Director Maya Lex), firma D3 del 2026-11-18 sobre la v2 de HN:CODIGO_NINEZ (ADJUDICACION_CLO_CODIGO_NINEZ.md §3)","manifiesto_sha256":"bd4d067d1ff2980db99a7527d21f9f381d996bb0a2d63933e30f7bcaecb2d372","pliego":"docs/corpus/staging/2026-11-04-hn-001-tranche-a-drive/canonico-v2/ADJUDICACION_CLO_CODIGO_NINEZ.md","procedencia":"Fuentes mixtas acreditadas por el pliego D1–D8 firmado (ver estado_canonico de cada fila); sin V4/V5 hasta el SQL de visibilidad","norm_id":"HN:CODIGO_NINEZ","instrumento_id":"CODIGO_NINEZ","ingest_batch":"A03_CODIGO_NINEZ_01","ordinal":167,"article_sha256":"79af127a5cbc70f79f1ff5284b7652a7724028a0c057e8d2555d9289c9e044f2","vigencia":"UNKNOWN","revision_pendiente":true,"marcas":[],"estado_canonico":"TEXTO_A03_DICTAMINADO_CLO","fuente_canonica":"A03_CONSOLIDADO_DICTAMINADO"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_NINEZ','157','dc63c6729d6cf9726229dc0e2f06ff61398f1f1aaa817c47cd53202c8944b9be','A03_CODIGO_NINEZ_01',now()),
('A03_CODIGO_NINEZ_01:CODIGO_NINEZ:158','mayalex_normativos','10_LEYES_REGLAMENTOS','El Instituto Hondureño de la Niñez y la Familia y el Ministerio Público, en su caso, en los eventos contemplados en el artículo anterior, podrá solicitar al juez competente, mientras dura el proceso, la suspensión provisional de las facultades de disposición y de administración de los bienes del niño y el nombramiento de un administrador de los mismos con sujeción a los requisitos legales.

El juez también podrá decretar la suspensión de oficio en los mismos casos.','158','Código de la Niñez y de la Adolescencia (Decreto 73-96), texto canónico v2 con las reformas del Decreto 35-2013 (La Gaceta 33,222)','{"texto_origen":"CANONICO_D3_FUENTES_MIXTAS","transcripcion_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","text_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","cotejado_por":"Abg. y Not. Fredy Omar Pinel Flores, propietario_despacho (CLO / Director Maya Lex), firma D3 del 2026-11-18 sobre la v2 de HN:CODIGO_NINEZ (ADJUDICACION_CLO_CODIGO_NINEZ.md §3)","manifiesto_sha256":"bd4d067d1ff2980db99a7527d21f9f381d996bb0a2d63933e30f7bcaecb2d372","pliego":"docs/corpus/staging/2026-11-04-hn-001-tranche-a-drive/canonico-v2/ADJUDICACION_CLO_CODIGO_NINEZ.md","procedencia":"Fuentes mixtas acreditadas por el pliego D1–D8 firmado (ver estado_canonico de cada fila); sin V4/V5 hasta el SQL de visibilidad","norm_id":"HN:CODIGO_NINEZ","instrumento_id":"CODIGO_NINEZ","ingest_batch":"A03_CODIGO_NINEZ_01","ordinal":168,"article_sha256":"64e109647fd055f2fd013fa254d415c45ae212825c6741549f6e2937afc53433","vigencia":"UNKNOWN","revision_pendiente":true,"marcas":[],"estado_canonico":"TEXTO_A03_DICTAMINADO_CLO","fuente_canonica":"A03_CONSOLIDADO_DICTAMINADO"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_NINEZ','158','5750d99ff598b9df6a814b0eee13d772f9a376ab11d02fd0dacb0248b9467eae','A03_CODIGO_NINEZ_01',now()),
('A03_CODIGO_NINEZ_01:CODIGO_NINEZ:159','mayalex_normativos','10_LEYES_REGLAMENTOS','Cuando el peligro para los intereses económicos del niño provenga del desacuerdo de los padres acerca de los actos de administración de sus bienes, el Instituto Hondureño de la Niñez y la Familia o el Ministerio Público ejercitarán las acciones necesarias para que se actúe conforme lo dispuesto en el artículo 59, precedente.','159','Código de la Niñez y de la Adolescencia (Decreto 73-96), texto canónico v2 con las reformas del Decreto 35-2013 (La Gaceta 33,222)','{"texto_origen":"CANONICO_D3_FUENTES_MIXTAS","transcripcion_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","text_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","cotejado_por":"Abg. y Not. Fredy Omar Pinel Flores, propietario_despacho (CLO / Director Maya Lex), firma D3 del 2026-11-18 sobre la v2 de HN:CODIGO_NINEZ (ADJUDICACION_CLO_CODIGO_NINEZ.md §3)","manifiesto_sha256":"bd4d067d1ff2980db99a7527d21f9f381d996bb0a2d63933e30f7bcaecb2d372","pliego":"docs/corpus/staging/2026-11-04-hn-001-tranche-a-drive/canonico-v2/ADJUDICACION_CLO_CODIGO_NINEZ.md","procedencia":"Fuentes mixtas acreditadas por el pliego D1–D8 firmado (ver estado_canonico de cada fila); sin V4/V5 hasta el SQL de visibilidad","norm_id":"HN:CODIGO_NINEZ","instrumento_id":"CODIGO_NINEZ","ingest_batch":"A03_CODIGO_NINEZ_01","ordinal":169,"article_sha256":"1a8dbfefa5afcb83406add727e48918c93992a92e1763b539489542c008d1977","vigencia":"UNKNOWN","revision_pendiente":true,"marcas":[],"estado_canonico":"TEXTO_A03_DICTAMINADO_CLO","fuente_canonica":"A03_CONSOLIDADO_DICTAMINADO"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_NINEZ','159','3fcfa6a790c9a53f3971e69e9a1c55557c259f1e1d3a67b09f467f2b51cfb356','A03_CODIGO_NINEZ_01',now()),
('A03_CODIGO_NINEZ_01:CODIGO_NINEZ:160','mayalex_normativos','10_LEYES_REGLAMENTOS','Corresponde a los parientes del niño que carezcan de representante legal, el Instituto Hondureño de la Niñez y la Familia y al Ministerio Público ejercitar las acciones necesarias para que el juzgado competente lo someta a tutela.','160','Código de la Niñez y de la Adolescencia (Decreto 73-96), texto canónico v2 con las reformas del Decreto 35-2013 (La Gaceta 33,222)','{"texto_origen":"CANONICO_D3_FUENTES_MIXTAS","transcripcion_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","text_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","cotejado_por":"Abg. y Not. Fredy Omar Pinel Flores, propietario_despacho (CLO / Director Maya Lex), firma D3 del 2026-11-18 sobre la v2 de HN:CODIGO_NINEZ (ADJUDICACION_CLO_CODIGO_NINEZ.md §3)","manifiesto_sha256":"bd4d067d1ff2980db99a7527d21f9f381d996bb0a2d63933e30f7bcaecb2d372","pliego":"docs/corpus/staging/2026-11-04-hn-001-tranche-a-drive/canonico-v2/ADJUDICACION_CLO_CODIGO_NINEZ.md","procedencia":"Fuentes mixtas acreditadas por el pliego D1–D8 firmado (ver estado_canonico de cada fila); sin V4/V5 hasta el SQL de visibilidad","norm_id":"HN:CODIGO_NINEZ","instrumento_id":"CODIGO_NINEZ","ingest_batch":"A03_CODIGO_NINEZ_01","ordinal":170,"article_sha256":"93a13087ce4584c5758845da6227b3b4d0c446b61cd0580bb04abadc0c9db092","vigencia":"UNKNOWN","revision_pendiente":true,"marcas":[],"estado_canonico":"TEXTO_A03_DICTAMINADO_CLO","fuente_canonica":"A03_CONSOLIDADO_DICTAMINADO"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_NINEZ','160','a609eacb4c96d56a0a167246608e22e8ececc4c5a597839293ceb3862953af37','A03_CODIGO_NINEZ_01',now()),
('A03_CODIGO_NINEZ_01:CODIGO_NINEZ:161','mayalex_normativos','10_LEYES_REGLAMENTOS','Mientras se discierne el cargo, el Instituto Hondureño de la Niñez y la Familia actuará como representante legal del niño que carece del mismo.','161','Código de la Niñez y de la Adolescencia (Decreto 73-96), texto canónico v2 con las reformas del Decreto 35-2013 (La Gaceta 33,222)','{"texto_origen":"CANONICO_D3_FUENTES_MIXTAS","transcripcion_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","text_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","cotejado_por":"Abg. y Not. Fredy Omar Pinel Flores, propietario_despacho (CLO / Director Maya Lex), firma D3 del 2026-11-18 sobre la v2 de HN:CODIGO_NINEZ (ADJUDICACION_CLO_CODIGO_NINEZ.md §3)","manifiesto_sha256":"bd4d067d1ff2980db99a7527d21f9f381d996bb0a2d63933e30f7bcaecb2d372","pliego":"docs/corpus/staging/2026-11-04-hn-001-tranche-a-drive/canonico-v2/ADJUDICACION_CLO_CODIGO_NINEZ.md","procedencia":"Fuentes mixtas acreditadas por el pliego D1–D8 firmado (ver estado_canonico de cada fila); sin V4/V5 hasta el SQL de visibilidad","norm_id":"HN:CODIGO_NINEZ","instrumento_id":"CODIGO_NINEZ","ingest_batch":"A03_CODIGO_NINEZ_01","ordinal":171,"article_sha256":"92da48e30a443caaeafe6b41fd65a4d8938a51b640e6c8df6b271b94940bda61","vigencia":"UNKNOWN","revision_pendiente":true,"marcas":[],"estado_canonico":"TEXTO_A03_DICTAMINADO_CLO","fuente_canonica":"A03_CONSOLIDADO_DICTAMINADO"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_NINEZ','161','42435d69b89b0311736c0eba80fe4f854aa5bd221d444a1ecc540bb11bd7bf54','A03_CODIGO_NINEZ_01',now()),
('A03_CODIGO_NINEZ_01:CODIGO_NINEZ:162','mayalex_normativos','10_LEYES_REGLAMENTOS','Se prohíbe el maltrato de niños o niñas, considerándose maltrato toda acción u omisión que violente los derechos y el bienestar de éstos, afectando su salud física, mental o emocional.

Se consideran víctimas de maltrato, los niños y niñas que han sufrido daños o perjuicios en su salud física, mental o emocional o de su bienestar personal, por acciones u omisiones de su padre, madre, representante legal, maestros(as) u otras personas con las que guarde relación.

El maltrato puede ser por:

1) Omisión; 2) Supresión; y, 3) Por Trasgresión".','162','Código de la Niñez y de la Adolescencia (Decreto 73-96), texto canónico v2 con las reformas del Decreto 35-2013 (La Gaceta 33,222)','{"texto_origen":"CANONICO_D3_FUENTES_MIXTAS","transcripcion_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","text_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","cotejado_por":"Abg. y Not. Fredy Omar Pinel Flores, propietario_despacho (CLO / Director Maya Lex), firma D3 del 2026-11-18 sobre la v2 de HN:CODIGO_NINEZ (ADJUDICACION_CLO_CODIGO_NINEZ.md §3)","manifiesto_sha256":"bd4d067d1ff2980db99a7527d21f9f381d996bb0a2d63933e30f7bcaecb2d372","pliego":"docs/corpus/staging/2026-11-04-hn-001-tranche-a-drive/canonico-v2/ADJUDICACION_CLO_CODIGO_NINEZ.md","procedencia":"Fuentes mixtas acreditadas por el pliego D1–D8 firmado (ver estado_canonico de cada fila); sin V4/V5 hasta el SQL de visibilidad","norm_id":"HN:CODIGO_NINEZ","instrumento_id":"CODIGO_NINEZ","ingest_batch":"A03_CODIGO_NINEZ_01","ordinal":172,"article_sha256":"d7c6b2650686cf833fb61a0c0840509c59a6805158fe6912a56902532120b41c","vigencia":"UNKNOWN","revision_pendiente":true,"marcas":[],"estado_canonico":"TEXTO_V8_D3","fuente_canonica":"V8_LA_GACETA_33222"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_NINEZ','162','bc8ed385062aa5ef3ac691b9fdb77005de7b30614c0ceaa41748402973c9c7a0','A03_CODIGO_NINEZ_01',now()),
('A03_CODIGO_NINEZ_01:CODIGO_NINEZ:163','mayalex_normativos','10_LEYES_REGLAMENTOS','El maltrato por Omisión es aquel que se da por el incumplimiento de los deberes de los padres, representantes legales o cualquier otra persona que esté a cargo del niño o niña, éste puede ser físico, intelectual o emocional.

El maltrato Físico por Omisión, comprende aquellos casos en que el niño o niña es dejado solo o sola en imposibilidad de acceder con un mínimo grado de seguridad a un techo, vestimenta, alimentación o cuidados físicos y médicos necesarios u otros análogos.

El maltrato Intelectual por Omisión, comprende aquellos casos en que no se le presta la atención debida al niño o niña, en los procesos educativos, formativos y recreativos.

El maltrato Emocional por Omisión, comprende aquellos casos en que se deja de proveer al niño o niña, el afecto y cariño que necesita para su sano desarrollo.

Las acciones de violencia en el núcleo familiar, aunque no afecten directamente al niño o niña, serán consideradas como maltrato por omisión.','163','Código de la Niñez y de la Adolescencia (Decreto 73-96), texto canónico v2 con las reformas del Decreto 35-2013 (La Gaceta 33,222)','{"texto_origen":"CANONICO_D3_FUENTES_MIXTAS","transcripcion_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","text_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","cotejado_por":"Abg. y Not. Fredy Omar Pinel Flores, propietario_despacho (CLO / Director Maya Lex), firma D3 del 2026-11-18 sobre la v2 de HN:CODIGO_NINEZ (ADJUDICACION_CLO_CODIGO_NINEZ.md §3)","manifiesto_sha256":"bd4d067d1ff2980db99a7527d21f9f381d996bb0a2d63933e30f7bcaecb2d372","pliego":"docs/corpus/staging/2026-11-04-hn-001-tranche-a-drive/canonico-v2/ADJUDICACION_CLO_CODIGO_NINEZ.md","procedencia":"Fuentes mixtas acreditadas por el pliego D1–D8 firmado (ver estado_canonico de cada fila); sin V4/V5 hasta el SQL de visibilidad","norm_id":"HN:CODIGO_NINEZ","instrumento_id":"CODIGO_NINEZ","ingest_batch":"A03_CODIGO_NINEZ_01","ordinal":173,"article_sha256":"f3e0c3dce8a0ff8c9a990e3b371c76c9df4c08bee50cd600a45372b6a9e4361c","vigencia":"UNKNOWN","revision_pendiente":true,"marcas":[],"estado_canonico":"TEXTO_V8_D3","fuente_canonica":"V8_LA_GACETA_33222"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_NINEZ','163','70807ce7692905d7e47bb09477f6a6046a74fb7e4341c6fd2642ce648dbf5e2c','A03_CODIGO_NINEZ_01',now()),
('A03_CODIGO_NINEZ_01:CODIGO_NINEZ:164','mayalex_normativos','10_LEYES_REGLAMENTOS','El maltrato por Supresión implica todo aquel trato, disimulado o no, como medidas disciplinarias o correctivas, que tiendan a negar al niño o niña el goce de sus derechos.

Este maltrato comprende toda supresión o discriminación que conlleve perjuicio al niño o niña, incluida la exclusión del hogar y la negación del goce y ejercicio de sus libertades; el derecho a la asistencia familiar, a la atención médica y a los medicamentos que requiera, el acceso a un ambiente infantil y a actividades y áreas recreativas o a recibir visitas de otros niños o niñas respecto de los cuales no hay causa justa para considerarlas perjudiciales.','164','Código de la Niñez y de la Adolescencia (Decreto 73-96), texto canónico v2 con las reformas del Decreto 35-2013 (La Gaceta 33,222)','{"texto_origen":"CANONICO_D3_FUENTES_MIXTAS","transcripcion_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","text_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","cotejado_por":"Abg. y Not. Fredy Omar Pinel Flores, propietario_despacho (CLO / Director Maya Lex), firma D3 del 2026-11-18 sobre la v2 de HN:CODIGO_NINEZ (ADJUDICACION_CLO_CODIGO_NINEZ.md §3)","manifiesto_sha256":"bd4d067d1ff2980db99a7527d21f9f381d996bb0a2d63933e30f7bcaecb2d372","pliego":"docs/corpus/staging/2026-11-04-hn-001-tranche-a-drive/canonico-v2/ADJUDICACION_CLO_CODIGO_NINEZ.md","procedencia":"Fuentes mixtas acreditadas por el pliego D1–D8 firmado (ver estado_canonico de cada fila); sin V4/V5 hasta el SQL de visibilidad","norm_id":"HN:CODIGO_NINEZ","instrumento_id":"CODIGO_NINEZ","ingest_batch":"A03_CODIGO_NINEZ_01","ordinal":174,"article_sha256":"f3fb5703a24a1b5a0022d9fd3ac118044144e5293b55bf211ce4727f14b88e82","vigencia":"UNKNOWN","revision_pendiente":true,"marcas":[],"estado_canonico":"TEXTO_V8_D3","fuente_canonica":"V8_LA_GACETA_33222"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_NINEZ','164','d0402378d9c7d9c8d55c1597169c01f26a03f37017a8c0844a0e62ea8265f271','A03_CODIGO_NINEZ_01',now()),
('A03_CODIGO_NINEZ_01:CODIGO_NINEZ:165','mayalex_normativos','10_LEYES_REGLAMENTOS','El maltrato por Trasgresión tendrá lugar cada vez que se produzcan acciones o conductas hostiles, rechazantes o destructivas hacia el niño o niña, tales como hacerlo objeto de malos tratos físicos; proporcionarle drogas o medicamentos que no sean necesarios para su salud o que la perjudiquen; someterle a procedimientos médicos o quirúrgicos innecesarios que pongan en riesgo su salud física, mental o emocional; obligarle a alimentarse en exceso, hacerlo víctima de agresiones emocionales o de palabra, incluyendo la ofensa y la humillación; la incomunicación rechazante; y el castigo por medio de labores pesadas. Cuando el Instituto Hondureño de la Niñez y la Familia (IHNFA) tenga conocimiento de maltratos por trasgresión, presentará inmediatamente la correspondiente denuncia al Ministerio Público, para que se proceda conforme a Derecho.','165','Código de la Niñez y de la Adolescencia (Decreto 73-96), texto canónico v2 con las reformas del Decreto 35-2013 (La Gaceta 33,222)','{"texto_origen":"CANONICO_D3_FUENTES_MIXTAS","transcripcion_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","text_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","cotejado_por":"Abg. y Not. Fredy Omar Pinel Flores, propietario_despacho (CLO / Director Maya Lex), firma D3 del 2026-11-18 sobre la v2 de HN:CODIGO_NINEZ (ADJUDICACION_CLO_CODIGO_NINEZ.md §3)","manifiesto_sha256":"bd4d067d1ff2980db99a7527d21f9f381d996bb0a2d63933e30f7bcaecb2d372","pliego":"docs/corpus/staging/2026-11-04-hn-001-tranche-a-drive/canonico-v2/ADJUDICACION_CLO_CODIGO_NINEZ.md","procedencia":"Fuentes mixtas acreditadas por el pliego D1–D8 firmado (ver estado_canonico de cada fila); sin V4/V5 hasta el SQL de visibilidad","norm_id":"HN:CODIGO_NINEZ","instrumento_id":"CODIGO_NINEZ","ingest_batch":"A03_CODIGO_NINEZ_01","ordinal":175,"article_sha256":"563bd58bfcb5d6f83f67e6aede04f8b62e0f8a3b0fe20002851071a43f7fe0ec","vigencia":"UNKNOWN","revision_pendiente":true,"marcas":[],"estado_canonico":"TEXTO_V8_D3","fuente_canonica":"V8_LA_GACETA_33222"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_NINEZ','165','0ea706f5b52144039affcaaa2f6398a14d08b318209e8dba40db7f51a09ec1f9','A03_CODIGO_NINEZ_01',now()),
('A03_CODIGO_NINEZ_01:CODIGO_NINEZ:166','mayalex_normativos','10_LEYES_REGLAMENTOS','Sin perjuicio de la responsabilidad Civil, Administrativa y Penal a que hubiera lugar en Derecho, el maltrato será sancionado administrativamente por el Instituto Hondureño de la Niñez y la Familia (IHNFA), con multa de uno (1) a dos (2) salarios mínimos en su valor más alto. Asimismo el(la) infractor(a) deberá asistir a los programas de tratamiento y rehabilitación, así como de consejería familiar que tendrá el Instituto Hondureño de la Niñez y la Familia (IHNFA), los que incluirán orientación psicológica y social.

En la aplicación de esta norma, el Instituto Hondureño de la Niñez y la Familia (IHNFA), procurará que las sanciones no menoscaben el legítimo ejercicio de los derechos a que da origen la patria potestad o tutela, en su caso.','166','Código de la Niñez y de la Adolescencia (Decreto 73-96), texto canónico v2 con las reformas del Decreto 35-2013 (La Gaceta 33,222)','{"texto_origen":"CANONICO_D3_FUENTES_MIXTAS","transcripcion_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","text_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","cotejado_por":"Abg. y Not. Fredy Omar Pinel Flores, propietario_despacho (CLO / Director Maya Lex), firma D3 del 2026-11-18 sobre la v2 de HN:CODIGO_NINEZ (ADJUDICACION_CLO_CODIGO_NINEZ.md §3)","manifiesto_sha256":"bd4d067d1ff2980db99a7527d21f9f381d996bb0a2d63933e30f7bcaecb2d372","pliego":"docs/corpus/staging/2026-11-04-hn-001-tranche-a-drive/canonico-v2/ADJUDICACION_CLO_CODIGO_NINEZ.md","procedencia":"Fuentes mixtas acreditadas por el pliego D1–D8 firmado (ver estado_canonico de cada fila); sin V4/V5 hasta el SQL de visibilidad","norm_id":"HN:CODIGO_NINEZ","instrumento_id":"CODIGO_NINEZ","ingest_batch":"A03_CODIGO_NINEZ_01","ordinal":176,"article_sha256":"7dcdce5d6f83b3cd28a4d5f2b7739bf7631ef7ba29ffecda06fbb566abe7fb76","vigencia":"UNKNOWN","revision_pendiente":true,"marcas":[],"estado_canonico":"TEXTO_V8_D3","fuente_canonica":"V8_LA_GACETA_33222"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_NINEZ','166','a3a525f61db78dbdb8cedcd122eb544d85032b3d4b733e238d6f33aa7efdbec7','A03_CODIGO_NINEZ_01',now()),
('A03_CODIGO_NINEZ_01:CODIGO_NINEZ:167','mayalex_normativos','10_LEYES_REGLAMENTOS','El Estado, por medio del Instituto Hondureño de la Niñez y la Familia (IHNFA) formulará y pondrá en práctica programas de detección, registro y seguimiento de los niños y niñas que hayan sido maltratados, así como de quienes hayan sido agresores y demás víctimas.','167','Código de la Niñez y de la Adolescencia (Decreto 73-96), texto canónico v2 con las reformas del Decreto 35-2013 (La Gaceta 33,222)','{"texto_origen":"CANONICO_D3_FUENTES_MIXTAS","transcripcion_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","text_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","cotejado_por":"Abg. y Not. Fredy Omar Pinel Flores, propietario_despacho (CLO / Director Maya Lex), firma D3 del 2026-11-18 sobre la v2 de HN:CODIGO_NINEZ (ADJUDICACION_CLO_CODIGO_NINEZ.md §3)","manifiesto_sha256":"bd4d067d1ff2980db99a7527d21f9f381d996bb0a2d63933e30f7bcaecb2d372","pliego":"docs/corpus/staging/2026-11-04-hn-001-tranche-a-drive/canonico-v2/ADJUDICACION_CLO_CODIGO_NINEZ.md","procedencia":"Fuentes mixtas acreditadas por el pliego D1–D8 firmado (ver estado_canonico de cada fila); sin V4/V5 hasta el SQL de visibilidad","norm_id":"HN:CODIGO_NINEZ","instrumento_id":"CODIGO_NINEZ","ingest_batch":"A03_CODIGO_NINEZ_01","ordinal":177,"article_sha256":"57560d85b10f637169947992f2553e61c17516078ce1a06f202fa79c4ef996be","vigencia":"UNKNOWN","revision_pendiente":true,"marcas":[],"estado_canonico":"TEXTO_V8_D3","fuente_canonica":"V8_LA_GACETA_33222"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_NINEZ','167','42fabc2dcf90be0550d70d3d3d0c956df819f0c8c0043e656185294a0870b4b5','A03_CODIGO_NINEZ_01',now()),
('A03_CODIGO_NINEZ_01:CODIGO_NINEZ:168','mayalex_normativos','10_LEYES_REGLAMENTOS','Los(las) Directores(as) de los hospitales públicos y privados y de los demás centros asistenciales, informarán en un plazo máximo de veinticuatro (24) horas al Instituto Hondureño de la Niñez y la Familia (IHNFA) y al Ministerio Público, sobre los niños y niñas que muestren signos evidentes de agresión y sobre aquellos cuyos exámenes revelen que han sido víctimas de malos tratos.

En la misma obligación incurrirán los(las) Directores(as) de Centros Educativos y Centros de Cuidado, así como los(las) responsables directos de los niños y niñas, en esos centros.

La omisión de estos informes se sancionará con multa de dos (2) a cinco (5) salarios mínimos en su valor más alto, sin perjuicio del cumplimiento de la obligación.','168','Código de la Niñez y de la Adolescencia (Decreto 73-96), texto canónico v2 con las reformas del Decreto 35-2013 (La Gaceta 33,222)','{"texto_origen":"CANONICO_D3_FUENTES_MIXTAS","transcripcion_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","text_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","cotejado_por":"Abg. y Not. Fredy Omar Pinel Flores, propietario_despacho (CLO / Director Maya Lex), firma D3 del 2026-11-18 sobre la v2 de HN:CODIGO_NINEZ (ADJUDICACION_CLO_CODIGO_NINEZ.md §3)","manifiesto_sha256":"bd4d067d1ff2980db99a7527d21f9f381d996bb0a2d63933e30f7bcaecb2d372","pliego":"docs/corpus/staging/2026-11-04-hn-001-tranche-a-drive/canonico-v2/ADJUDICACION_CLO_CODIGO_NINEZ.md","procedencia":"Fuentes mixtas acreditadas por el pliego D1–D8 firmado (ver estado_canonico de cada fila); sin V4/V5 hasta el SQL de visibilidad","norm_id":"HN:CODIGO_NINEZ","instrumento_id":"CODIGO_NINEZ","ingest_batch":"A03_CODIGO_NINEZ_01","ordinal":178,"article_sha256":"bddd42c2af8933d2d22c131f48af65d5b1489263d6f17d3b5d476ebdd5154314","vigencia":"UNKNOWN","revision_pendiente":true,"marcas":[],"estado_canonico":"TEXTO_V8_D3","fuente_canonica":"V8_LA_GACETA_33222"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_NINEZ','168','42bf2de07b054ed26c86a186e9c54e9be054ebf6d773f7868a8c0bba10c6ec6d','A03_CODIGO_NINEZ_01',now()),
('A03_CODIGO_NINEZ_01:CODIGO_NINEZ:169','mayalex_normativos','10_LEYES_REGLAMENTOS','Incurre en responsabilidad Civil, Penal y Administrativa, el(la'') funcionario(a) o empleado(a) del Instituto Hondureño de la Niñez y la Familia (IHNFA) bajo cuyo cuidado se encuentre un niño o niña, cuando incida en la misma situación a la que se refiere el Artículo precedente, en cuanto a sus autoridades superiores.','169','Código de la Niñez y de la Adolescencia (Decreto 73-96), texto canónico v2 con las reformas del Decreto 35-2013 (La Gaceta 33,222)','{"texto_origen":"CANONICO_D3_FUENTES_MIXTAS","transcripcion_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","text_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","cotejado_por":"Abg. y Not. Fredy Omar Pinel Flores, propietario_despacho (CLO / Director Maya Lex), firma D3 del 2026-11-18 sobre la v2 de HN:CODIGO_NINEZ (ADJUDICACION_CLO_CODIGO_NINEZ.md §3)","manifiesto_sha256":"bd4d067d1ff2980db99a7527d21f9f381d996bb0a2d63933e30f7bcaecb2d372","pliego":"docs/corpus/staging/2026-11-04-hn-001-tranche-a-drive/canonico-v2/ADJUDICACION_CLO_CODIGO_NINEZ.md","procedencia":"Fuentes mixtas acreditadas por el pliego D1–D8 firmado (ver estado_canonico de cada fila); sin V4/V5 hasta el SQL de visibilidad","norm_id":"HN:CODIGO_NINEZ","instrumento_id":"CODIGO_NINEZ","ingest_batch":"A03_CODIGO_NINEZ_01","ordinal":179,"article_sha256":"c882c3717cad3103962a53ee0d5f152529d8f79f9fabf48bd6fe8e37b10360fc","vigencia":"UNKNOWN","revision_pendiente":true,"marcas":[],"estado_canonico":"TEXTO_V8_D3","fuente_canonica":"V8_LA_GACETA_33222"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_NINEZ','169','1d7c40c2b70f0683c59ea839f03f016a230b8b7120c304b15db1017ceca0a994','A03_CODIGO_NINEZ_01',now()),
