INSERT INTO public.biblioteca_vectores (id,coleccion,materia,contenido,num_articulo,fuente,metadata,embedding,jurisdiccion,fuente_tipo,es_norma_vigente,revision_pendiente,instrumento_id,num_articulo_norm,hash_contenido,ingest_batch,ingested_at) VALUES
('A03_CODIGO_NINEZ_01:CODIGO_NINEZ:188','mayalex_normativos','10_LEYES_REGLAMENTOS','Serán de aplicación al Proceso, las Medidas Cautelares previstas en el Artículo 173 del Código Procesal Penal, con excepción de las reguladas en los numerales 1), 2), 10) y 12), en todo cuanto no esté regulado en este Título.

Las Medidas Cautelares serán impuestas mediante resolución judicial motivada, deberán ser proporcionales a la infracción y adecuadas a las circunstancias en que se encuentre El Niño(a). Estas serán aplicadas por los períodos más breves posibles, pero no excederán los seis (6) meses.

En todos los casos, el Fiscal fundamentará la solicitud de Medidas y, mediante auto motivado, el Juez resolverá lo procedente conforme a Derecho.','188','Código de la Niñez y de la Adolescencia (Decreto 73-96), texto canónico v2 con las reformas del Decreto 35-2013 (La Gaceta 33,222)','{"texto_origen":"CANONICO_D3_FUENTES_MIXTAS","transcripcion_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","text_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","cotejado_por":"Abg. y Not. Fredy Omar Pinel Flores, propietario_despacho (CLO / Director Maya Lex), firma D3 del 2026-11-18 sobre la v2 de HN:CODIGO_NINEZ (ADJUDICACION_CLO_CODIGO_NINEZ.md §3)","manifiesto_sha256":"bd4d067d1ff2980db99a7527d21f9f381d996bb0a2d63933e30f7bcaecb2d372","pliego":"docs/corpus/staging/2026-11-04-hn-001-tranche-a-drive/canonico-v2/ADJUDICACION_CLO_CODIGO_NINEZ.md","procedencia":"Fuentes mixtas acreditadas por el pliego D1–D8 firmado (ver estado_canonico de cada fila); sin V4/V5 hasta el SQL de visibilidad","norm_id":"HN:CODIGO_NINEZ","instrumento_id":"CODIGO_NINEZ","ingest_batch":"A03_CODIGO_NINEZ_01","ordinal":201,"article_sha256":"63238e6d0319d5fe21cd3cca4ace5a353e9da9abc7f4949bd3d3a7e515980f4c","vigencia":"UNKNOWN","revision_pendiente":true,"marcas":[],"estado_canonico":"TEXTO_V8_D3","fuente_canonica":"V8_LA_GACETA_33222"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_NINEZ','188','80197b6162acadbca5faaf0a799e6916dc1f9660220572b95736f6cbead6589b','A03_CODIGO_NINEZ_01',now()),
('A03_CODIGO_NINEZ_01:CODIGO_NINEZ:189','mayalex_normativos','10_LEYES_REGLAMENTOS','Solamente se podrá aplicar Medidas Cautelares a El Niño(a), con el objetivo de:

a) Asegurar y garantizar su presencia en el Proceso; b) Asegurar las pruebas; y, c) Proteger a la víctima, denunciante o testigo.','189','Código de la Niñez y de la Adolescencia (Decreto 73-96), texto canónico v2 con las reformas del Decreto 35-2013 (La Gaceta 33,222)','{"texto_origen":"CANONICO_D3_FUENTES_MIXTAS","transcripcion_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","text_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","cotejado_por":"Abg. y Not. Fredy Omar Pinel Flores, propietario_despacho (CLO / Director Maya Lex), firma D3 del 2026-11-18 sobre la v2 de HN:CODIGO_NINEZ (ADJUDICACION_CLO_CODIGO_NINEZ.md §3)","manifiesto_sha256":"bd4d067d1ff2980db99a7527d21f9f381d996bb0a2d63933e30f7bcaecb2d372","pliego":"docs/corpus/staging/2026-11-04-hn-001-tranche-a-drive/canonico-v2/ADJUDICACION_CLO_CODIGO_NINEZ.md","procedencia":"Fuentes mixtas acreditadas por el pliego D1–D8 firmado (ver estado_canonico de cada fila); sin V4/V5 hasta el SQL de visibilidad","norm_id":"HN:CODIGO_NINEZ","instrumento_id":"CODIGO_NINEZ","ingest_batch":"A03_CODIGO_NINEZ_01","ordinal":202,"article_sha256":"9862865ec2d4702d7172fc4bf2196243e60fbd7c14ebb901eeea8d1f6115aa7b","vigencia":"UNKNOWN","revision_pendiente":true,"marcas":[],"estado_canonico":"TEXTO_V8_D3","fuente_canonica":"V8_LA_GACETA_33222"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_NINEZ','189','6cc959d30e833d7b390683b7409fa79b18f808d31bce6aac52739979bab6a055','A03_CODIGO_NINEZ_01',now()),
('A03_CODIGO_NINEZ_01:CODIGO_NINEZ:190','mayalex_normativos','10_LEYES_REGLAMENTOS','La aprehensión de El Niño(a) será hecha de conformidad con las disposiciones, principios, derechos y procedimientos consignados en la Constitución de la República, el presente Código y demás leyes aplicables.

Ningún Niño(a) podrá ser aprehendido sin orden escrita de Juez competente, salvo el caso de flagrancia o fuga de un centro especializado de internamiento en el que estuviera cumpliendo una Medida Cautelar o Sanción.

El Ministerio Público lo pondrá a la orden del Juez competente, dentro de las veinticuatro (24) horas siguientes a su detención.

Quienes realicen la aprehensión deberán identificarse y mostrar la orden judicial que los autoriza para ejecutarla, en su caso, además deberán reducir al mínimo el uso de la fuerza u otro medio que pueda ocasionarle daño.

El uso de la fuerza, así como de cualquier otro medio para la aprehensión serán los adecuados a su condición y no podrán atentar contra su dignidad. Queda prohibido el uso de esposas, ataduras o medios de sujeción que atenten contra su dignidad, salvo que exista peligro inminente de fuga o que se cause daño o se le pueda causar a otras personas. Si es necesario el uso de armas, deberá preferirse la incapacitantes no letales.','190','Código de la Niñez y de la Adolescencia (Decreto 73-96), texto canónico v2 con las reformas del Decreto 35-2013 (La Gaceta 33,222)','{"texto_origen":"CANONICO_D3_FUENTES_MIXTAS","transcripcion_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","text_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","cotejado_por":"Abg. y Not. Fredy Omar Pinel Flores, propietario_despacho (CLO / Director Maya Lex), firma D3 del 2026-11-18 sobre la v2 de HN:CODIGO_NINEZ (ADJUDICACION_CLO_CODIGO_NINEZ.md §3)","manifiesto_sha256":"bd4d067d1ff2980db99a7527d21f9f381d996bb0a2d63933e30f7bcaecb2d372","pliego":"docs/corpus/staging/2026-11-04-hn-001-tranche-a-drive/canonico-v2/ADJUDICACION_CLO_CODIGO_NINEZ.md","procedencia":"Fuentes mixtas acreditadas por el pliego D1–D8 firmado (ver estado_canonico de cada fila); sin V4/V5 hasta el SQL de visibilidad","norm_id":"HN:CODIGO_NINEZ","instrumento_id":"CODIGO_NINEZ","ingest_batch":"A03_CODIGO_NINEZ_01","ordinal":203,"article_sha256":"da015b12f0c4866833259f3fd59f882b379a4c3cc6c8705c28141f400336e699","vigencia":"UNKNOWN","revision_pendiente":true,"marcas":[],"estado_canonico":"TEXTO_V8_D3","fuente_canonica":"V8_LA_GACETA_33222"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_NINEZ','190','ea1a14a976e0200b4a1cb2c34e843e699dcf2dfd45e0014b9ca3b3f7717dea86','A03_CODIGO_NINEZ_01',now()),
('A03_CODIGO_NINEZ_01:CODIGO_NINEZ:191','mayalex_normativos','10_LEYES_REGLAMENTOS','Se entenderá por flagrancia, cuando El Niño(a) sea sorprendido:

a) En la comisión del Hecho Delictivo; o, b) Inmediatamente después de cometerlo, es perseguido materialmente.

En este caso, la detención se notificará inmediatamente a sus padres, responsable o al Instituto Hondureño de la Niñez

y la Familia (IHNFA); cuando ello no sea factible, se les notificará en el plazo más breve posible.

Se entenderá por responsables a las personas que lo tengan bajo su cuidado en forma temporal o permanente.

Si es extranjero, se le asegurará la inmediata comunicación con la autoridad consular de su país, de conformidad con los Tratados y Convenios Internacionales vigentes en Honduras.

Si la detención en flagrancia fuere realizada por agentes policiales, éstos deben presentarlo inmediatamente ante el Ministerio Público. Si es practicada por cualquier otra persona, ésta debe entregarlo de inmediato a la autoridad policial más próxima, la que procederá en la forma señalada en este párrafo.

Si muestra señales de maltrato físico o psicológico, inmediatamente el Ministerio Público dispondrá su evaluación psico-fisica, quien de verificar las agresiones, abrirá la investigación para determinar la causa y tipo de las lesiones. así como sus responsables.','191','Código de la Niñez y de la Adolescencia (Decreto 73-96), texto canónico v2 con las reformas del Decreto 35-2013 (La Gaceta 33,222)','{"texto_origen":"CANONICO_D3_FUENTES_MIXTAS","transcripcion_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","text_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","cotejado_por":"Abg. y Not. Fredy Omar Pinel Flores, propietario_despacho (CLO / Director Maya Lex), firma D3 del 2026-11-18 sobre la v2 de HN:CODIGO_NINEZ (ADJUDICACION_CLO_CODIGO_NINEZ.md §3)","manifiesto_sha256":"bd4d067d1ff2980db99a7527d21f9f381d996bb0a2d63933e30f7bcaecb2d372","pliego":"docs/corpus/staging/2026-11-04-hn-001-tranche-a-drive/canonico-v2/ADJUDICACION_CLO_CODIGO_NINEZ.md","procedencia":"Fuentes mixtas acreditadas por el pliego D1–D8 firmado (ver estado_canonico de cada fila); sin V4/V5 hasta el SQL de visibilidad","norm_id":"HN:CODIGO_NINEZ","instrumento_id":"CODIGO_NINEZ","ingest_batch":"A03_CODIGO_NINEZ_01","ordinal":204,"article_sha256":"ab5267e987f80d78574b0c9ded54b4201dc803a2ad77eb1f5819cd3e95fc126b","vigencia":"UNKNOWN","revision_pendiente":true,"marcas":[],"estado_canonico":"TEXTO_V8_D3","fuente_canonica":"V8_LA_GACETA_33222"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_NINEZ','191','c7ebfd200ef5b4be414ae663dd749cd3dadb4bc601ce30be9266376d5eea311f','A03_CODIGO_NINEZ_01',now()),
('A03_CODIGO_NINEZ_01:CODIGO_NINEZ:192','mayalex_normativos','10_LEYES_REGLAMENTOS','Para los efectos de éste Código, la medida prevista en el numeral 3 del Artículo 173 del Código Procesal Penal, se denomina Detención Cautelar y se regirá de conformidad a este Título.

La Detención Cautelar tiene carácter excepcional, por lo que exclusivamente se aplicará si no fuere posible decretar otra Medida Cautelar menos gravosa y solamente podrá imponerse en los supuestos siguientes:

a) Que la infracción supuestamente cometida, haya producido daño a la vida, la integridad personal, la libertad personal o sexual de las personas o implique grave violencia contra de otro u otros seres humanos b) Que El Niño(a) haya rechazado expresa, reiterada e injustificadamente el cumplimiento de otras Medidas Cautelares o Sanciones impuestas por la autoridad competente; o, c) Que exista peligro de fuga u obstrucción de la investigación.

En todos los casos, el Fiscal fundamentará la solicitud de Medidas y, mediante auto motivado, el Juez resolverá lo procedente conforme a Derecho.

A fin que la Detención Cautelar sea lo más breve posible, los tribunales y los órganos de investigación deberán considerar de máxima prioridad la tramitación efectiva de los casos en que un Nino(a) se encuentre detenido.

La Detención Cautelar se cumplirá en los centros especializados que al efecto tenga el Instituto Hondureño de la Niñez y la Familia (IHNFA) o institución que corresponda. Quienes cumplan esta medida deberán estar separados de aquellos que hayan sido sentenciados con el internamiento.

En los centros de privación de libertad no se admitirá el ingreso de Niños(as) sin orden previa y escrita de Juez competente.','192','Código de la Niñez y de la Adolescencia (Decreto 73-96), texto canónico v2 con las reformas del Decreto 35-2013 (La Gaceta 33,222)','{"texto_origen":"CANONICO_D3_FUENTES_MIXTAS","transcripcion_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","text_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","cotejado_por":"Abg. y Not. Fredy Omar Pinel Flores, propietario_despacho (CLO / Director Maya Lex), firma D3 del 2026-11-18 sobre la v2 de HN:CODIGO_NINEZ (ADJUDICACION_CLO_CODIGO_NINEZ.md §3)","manifiesto_sha256":"bd4d067d1ff2980db99a7527d21f9f381d996bb0a2d63933e30f7bcaecb2d372","pliego":"docs/corpus/staging/2026-11-04-hn-001-tranche-a-drive/canonico-v2/ADJUDICACION_CLO_CODIGO_NINEZ.md","procedencia":"Fuentes mixtas acreditadas por el pliego D1–D8 firmado (ver estado_canonico de cada fila); sin V4/V5 hasta el SQL de visibilidad","norm_id":"HN:CODIGO_NINEZ","instrumento_id":"CODIGO_NINEZ","ingest_batch":"A03_CODIGO_NINEZ_01","ordinal":205,"article_sha256":"28ec8b41ecb77aa71adfecd3f924df58c836a4539cc28c4dbc0b28ec6988939e","vigencia":"UNKNOWN","revision_pendiente":true,"marcas":[],"estado_canonico":"TEXTO_V8_D3","fuente_canonica":"V8_LA_GACETA_33222"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_NINEZ','192','5e9300300bb102f89bccd2fe87e8b22d4919f19430ac179c78c83a56ae2abfe0','A03_CODIGO_NINEZ_01',now()),
('A03_CODIGO_NINEZ_01:CODIGO_NINEZ:193','mayalex_normativos','10_LEYES_REGLAMENTOS','No procederá la Detención Cautelar contra Niños(as), cuando:

a) Estén en estado de embarazo; b) Madres durante la lactancia de sus hijos; y,

c) Adolezcan de una enfermedad en su fase terminal o degenerativa del sistema nervioso, de conformidad al Decreto No.5-2007 de fecha 13 de marzo de 2007.

En tales casos, la Detención Cautelar se sustituirá por arresto domiciliario o internamiento en un centro especializado adecuado, según sean las circunstancias.','193','Código de la Niñez y de la Adolescencia (Decreto 73-96), texto canónico v2 con las reformas del Decreto 35-2013 (La Gaceta 33,222)','{"texto_origen":"CANONICO_D3_FUENTES_MIXTAS","transcripcion_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","text_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","cotejado_por":"Abg. y Not. Fredy Omar Pinel Flores, propietario_despacho (CLO / Director Maya Lex), firma D3 del 2026-11-18 sobre la v2 de HN:CODIGO_NINEZ (ADJUDICACION_CLO_CODIGO_NINEZ.md §3)","manifiesto_sha256":"bd4d067d1ff2980db99a7527d21f9f381d996bb0a2d63933e30f7bcaecb2d372","pliego":"docs/corpus/staging/2026-11-04-hn-001-tranche-a-drive/canonico-v2/ADJUDICACION_CLO_CODIGO_NINEZ.md","procedencia":"Fuentes mixtas acreditadas por el pliego D1–D8 firmado (ver estado_canonico de cada fila); sin V4/V5 hasta el SQL de visibilidad","norm_id":"HN:CODIGO_NINEZ","instrumento_id":"CODIGO_NINEZ","ingest_batch":"A03_CODIGO_NINEZ_01","ordinal":206,"article_sha256":"fac6180b34aae215fd678489cdb91809190b6753f024aee9c6a899042e3d33f5","vigencia":"UNKNOWN","revision_pendiente":true,"marcas":[],"estado_canonico":"TEXTO_V8_D3","fuente_canonica":"V8_LA_GACETA_33222"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_NINEZ','193','9339817bba841e33e881a9f01646258dbed5d06ba6ad8a1e48d88160987f1171','A03_CODIGO_NINEZ_01',now()),
('A03_CODIGO_NINEZ_01:CODIGO_NINEZ:194','mayalex_normativos','10_LEYES_REGLAMENTOS','Las partes podrán solicitar en cualquier momento del Proceso hasta antes que quede firme la sentencia, audiencia para la revocación o sustitución de la Detención Cautelar por otra Medida menos gravosa, la cual tramitará conforme al Artículo 188 del Código Procesal Penal.

Dicha audiencia tendrá lugar dentro de las veinticuatro (24) horas siguientes a la fecha en que se haya presentado la respectiva petición, debiéndose celebrar con la comparecencia de las partes y resolverse en la misma.','194','Código de la Niñez y de la Adolescencia (Decreto 73-96), texto canónico v2 con las reformas del Decreto 35-2013 (La Gaceta 33,222)','{"texto_origen":"CANONICO_D3_FUENTES_MIXTAS","transcripcion_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","text_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","cotejado_por":"Abg. y Not. Fredy Omar Pinel Flores, propietario_despacho (CLO / Director Maya Lex), firma D3 del 2026-11-18 sobre la v2 de HN:CODIGO_NINEZ (ADJUDICACION_CLO_CODIGO_NINEZ.md §3)","manifiesto_sha256":"bd4d067d1ff2980db99a7527d21f9f381d996bb0a2d63933e30f7bcaecb2d372","pliego":"docs/corpus/staging/2026-11-04-hn-001-tranche-a-drive/canonico-v2/ADJUDICACION_CLO_CODIGO_NINEZ.md","procedencia":"Fuentes mixtas acreditadas por el pliego D1–D8 firmado (ver estado_canonico de cada fila); sin V4/V5 hasta el SQL de visibilidad","norm_id":"HN:CODIGO_NINEZ","instrumento_id":"CODIGO_NINEZ","ingest_batch":"A03_CODIGO_NINEZ_01","ordinal":207,"article_sha256":"448db49cc9e9847ae42ef1d5aac3395334c1881a01bdadf02e9dcb3fcf0396b1","vigencia":"UNKNOWN","revision_pendiente":true,"marcas":[],"estado_canonico":"TEXTO_V8_D3","fuente_canonica":"V8_LA_GACETA_33222"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_NINEZ','194','a1608e634a33f2651fa688c7513605f9c75f7fcbae0553208416c2d3c69f2aef','A03_CODIGO_NINEZ_01',now()),
('A03_CODIGO_NINEZ_01:CODIGO_NINEZ:195','mayalex_normativos','10_LEYES_REGLAMENTOS','Las Sanciones a los Niños(as) tienen por objeto su incorporación a un proceso reeducativo, por medio de,su formación integral y familiar, para lograr su reinserción social y el pleno desarrollo de sus capacidades, mediante su orientación y tratamiento.

El Juez podrá ordenar que su ejecución se realice en forma simultánea o sucesiva, verificando que las mismas no sean incompatibles entre sí.

Son sanciones aplicables las siguientes:

a) Sanciones no privativas de libertad:

1) Amonestación; 2) Libertad asistida; 3) Prestación de servicios a la comunidad; y, 4) Reparación del daño a la víctima.

b) Sanciones de orientación y supervisión:

1) Residir en un lugar determinado o cambiarse de él; 2) Frecuentar o dejar de frecuentar determinados lugares o personas; 3) Abstenerse de consumir drogas, otros estupefacientes o bebidas alcohólicas, que produzcan adicción o hábito; 4) Participar en programas especiales para la prevención y tratamiento de adicciones; 5) Someterse a programas educativos con el fin de comenzar o finalizar la escolaridad básica, si no la ha cumplido, aprender una profesión u oficio o seguir cursos de capacitación en el lugar o la institución que determine el Juez; 6) Someterse, si es necesario, a tratamiento médico o psicológico, de preferencia en instituciones públicas; y, 7) Asistir o integrarse a los correspondientes sistemas o centros educativos.

c) Sanciones privativas de libertad: 1) La privación de libertad domiciliaria; 2) Régimen de Semi-libertad; y, 3) La privación de libertad en centros certificados o especializados del Instituto Hondureño de la Niñez y la Familia (IHNFA) para Sancionados.','195','Código de la Niñez y de la Adolescencia (Decreto 73-96), texto canónico v2 con las reformas del Decreto 35-2013 (La Gaceta 33,222)','{"texto_origen":"CANONICO_D3_FUENTES_MIXTAS","transcripcion_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","text_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","cotejado_por":"Abg. y Not. Fredy Omar Pinel Flores, propietario_despacho (CLO / Director Maya Lex), firma D3 del 2026-11-18 sobre la v2 de HN:CODIGO_NINEZ (ADJUDICACION_CLO_CODIGO_NINEZ.md §3)","manifiesto_sha256":"bd4d067d1ff2980db99a7527d21f9f381d996bb0a2d63933e30f7bcaecb2d372","pliego":"docs/corpus/staging/2026-11-04-hn-001-tranche-a-drive/canonico-v2/ADJUDICACION_CLO_CODIGO_NINEZ.md","procedencia":"Fuentes mixtas acreditadas por el pliego D1–D8 firmado (ver estado_canonico de cada fila); sin V4/V5 hasta el SQL de visibilidad","norm_id":"HN:CODIGO_NINEZ","instrumento_id":"CODIGO_NINEZ","ingest_batch":"A03_CODIGO_NINEZ_01","ordinal":208,"article_sha256":"705269c2c39f8bdfe903ab49bd6f2621d3b3f9d51474f90fcf4df6297c79669f","vigencia":"UNKNOWN","revision_pendiente":true,"marcas":[],"estado_canonico":"TEXTO_V8_D3","fuente_canonica":"V8_LA_GACETA_33222"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_NINEZ','195','e4854a0cfda5f7c3b478f9591484724e9902ff7c5730c80182637915493a2c00','A03_CODIGO_NINEZ_01',now()),
('A03_CODIGO_NINEZ_01:CODIGO_NINEZ:196','mayalex_normativos','10_LEYES_REGLAMENTOS','La Amonestación es el llamado de atención al Sancionado, que el Juez le hará en audiencia oral, exhortándolo para que en lo sucesivo se acoja a las normas familiares y de convivencia social que éste establezca expresamente. Cuando corresponda, deberá advertir a los

padres, representantes legales o responsables, sobre la conducta infractora de El Niño(a) y les solicitará intervenir para que el amonestado respete las normas legales y sociales de convivencia.

La Amonestación deberá ser clara y directa, de manera que tanto El Niño(a) como sus representantes legales o responsables, comprendan la ilicitud de los hechos cometidos así como la responsabilidad de los padres, representantes o responsables en el cuidado de sus hijos o representados.','196','Código de la Niñez y de la Adolescencia (Decreto 73-96), texto canónico v2 con las reformas del Decreto 35-2013 (La Gaceta 33,222)','{"texto_origen":"CANONICO_D3_FUENTES_MIXTAS","transcripcion_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","text_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","cotejado_por":"Abg. y Not. Fredy Omar Pinel Flores, propietario_despacho (CLO / Director Maya Lex), firma D3 del 2026-11-18 sobre la v2 de HN:CODIGO_NINEZ (ADJUDICACION_CLO_CODIGO_NINEZ.md §3)","manifiesto_sha256":"bd4d067d1ff2980db99a7527d21f9f381d996bb0a2d63933e30f7bcaecb2d372","pliego":"docs/corpus/staging/2026-11-04-hn-001-tranche-a-drive/canonico-v2/ADJUDICACION_CLO_CODIGO_NINEZ.md","procedencia":"Fuentes mixtas acreditadas por el pliego D1–D8 firmado (ver estado_canonico de cada fila); sin V4/V5 hasta el SQL de visibilidad","norm_id":"HN:CODIGO_NINEZ","instrumento_id":"CODIGO_NINEZ","ingest_batch":"A03_CODIGO_NINEZ_01","ordinal":209,"article_sha256":"966c0261734e12ff9dfff4e271ca47a198586240394976a356fe6fd7f24ba70e","vigencia":"UNKNOWN","revision_pendiente":true,"marcas":[],"estado_canonico":"TEXTO_V8_D3","fuente_canonica":"V8_LA_GACETA_33222"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_NINEZ','196','65e7e284b2b78e5683d519be24ddfa91d76d78736017030f903134c4858e75f2','A03_CODIGO_NINEZ_01',now()),
('A03_CODIGO_NINEZ_01:CODIGO_NINEZ:197','mayalex_normativos','10_LEYES_REGLAMENTOS','Libertad Asistida es la medida educativa, socializadora e individualizada, que consiste en otorgar libertad al Sancionado, bajo la supervisión y orientación de personal especializado del Instituto Hondureño de la Niñez y la Familia (IHNFA), con la finalidad de desarrollar sus habilidades, destrezas, capacidades y aptitudes, especialmente en áreas educativas y de formación laboral, para lograr su desarrollo personal y su reinserción familiar y social.

Esta medida no podrá ser inferior a seis (6) meses ni superior a dos (2) años.','197','Código de la Niñez y de la Adolescencia (Decreto 73-96), texto canónico v2 con las reformas del Decreto 35-2013 (La Gaceta 33,222)','{"texto_origen":"CANONICO_D3_FUENTES_MIXTAS","transcripcion_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","text_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","cotejado_por":"Abg. y Not. Fredy Omar Pinel Flores, propietario_despacho (CLO / Director Maya Lex), firma D3 del 2026-11-18 sobre la v2 de HN:CODIGO_NINEZ (ADJUDICACION_CLO_CODIGO_NINEZ.md §3)","manifiesto_sha256":"bd4d067d1ff2980db99a7527d21f9f381d996bb0a2d63933e30f7bcaecb2d372","pliego":"docs/corpus/staging/2026-11-04-hn-001-tranche-a-drive/canonico-v2/ADJUDICACION_CLO_CODIGO_NINEZ.md","procedencia":"Fuentes mixtas acreditadas por el pliego D1–D8 firmado (ver estado_canonico de cada fila); sin V4/V5 hasta el SQL de visibilidad","norm_id":"HN:CODIGO_NINEZ","instrumento_id":"CODIGO_NINEZ","ingest_batch":"A03_CODIGO_NINEZ_01","ordinal":210,"article_sha256":"3cdc4a4bd5566afa481c5d47fdba7e09580bfb814f45dbdff44d8f09f7fe3a70","vigencia":"UNKNOWN","revision_pendiente":true,"marcas":[],"estado_canonico":"TEXTO_V8_D3","fuente_canonica":"V8_LA_GACETA_33222"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_NINEZ','197','8560a49d5a37001a3994f38a98db1bea45062a5199da7474a3e90485a731915c','A03_CODIGO_NINEZ_01',now()),
('A03_CODIGO_NINEZ_01:CODIGO_NINEZ:198','mayalex_normativos','10_LEYES_REGLAMENTOS','La Prestación de Servicios a la Comunidad consiste en la realización de tareas de interés general por parte del Sancionado, la cual se prestará de modo gratuito en entidades de asistencia pública o privada sin fines de lucro, orientadas a la asistencia social, tales como hospitales, escuelas, iglesias, municipalidades, cuerpos de bomberos, cruz roja y otras instituciones similares, siempre y cuando éstas tareas no atenten contra su salud, o integridad física y psicológica, no interfieran con sus estudios o su trabajo y sean compatibles con la ley que regule la respectiva actividad.

Las actividades asignadas deberán guardar proporción con las aptitudes del Sancionado y con su nivel de desarrollo, tomando en cuenta el estudio técnico correspondiente. Podrán ser cumplidas durante una jornada mínima de seis (6) y máxima de ocho (8) horas semanales, en los días que goce de tiempo libre, o en días inhábiles. La prestación de servicio a la comunidad no podrá ser inferior a seis (6) meses ni superior a un (1) año.','198','Código de la Niñez y de la Adolescencia (Decreto 73-96), texto canónico v2 con las reformas del Decreto 35-2013 (La Gaceta 33,222)','{"texto_origen":"CANONICO_D3_FUENTES_MIXTAS","transcripcion_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","text_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","cotejado_por":"Abg. y Not. Fredy Omar Pinel Flores, propietario_despacho (CLO / Director Maya Lex), firma D3 del 2026-11-18 sobre la v2 de HN:CODIGO_NINEZ (ADJUDICACION_CLO_CODIGO_NINEZ.md §3)","manifiesto_sha256":"bd4d067d1ff2980db99a7527d21f9f381d996bb0a2d63933e30f7bcaecb2d372","pliego":"docs/corpus/staging/2026-11-04-hn-001-tranche-a-drive/canonico-v2/ADJUDICACION_CLO_CODIGO_NINEZ.md","procedencia":"Fuentes mixtas acreditadas por el pliego D1–D8 firmado (ver estado_canonico de cada fila); sin V4/V5 hasta el SQL de visibilidad","norm_id":"HN:CODIGO_NINEZ","instrumento_id":"CODIGO_NINEZ","ingest_batch":"A03_CODIGO_NINEZ_01","ordinal":211,"article_sha256":"07c11710a697659e114a130e189ec8544e4cd124e29bcaeb4e85d75c95c0e1ab","vigencia":"UNKNOWN","revision_pendiente":true,"marcas":[],"estado_canonico":"TEXTO_V8_D3","fuente_canonica":"V8_LA_GACETA_33222"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_NINEZ','198','131550bb1b441f59c1b702bb3ed4d3431e8bfeafc37346a12e01d16de8b544c6','A03_CODIGO_NINEZ_01',now()),
('A03_CODIGO_NINEZ_01:CODIGO_NINEZ:199','mayalex_normativos','10_LEYES_REGLAMENTOS','La Reparación del Daño a la Víctima tiene por finalidad resarcir el daño causado, asignando al

Sancionado una obligación de dar o de restituir la cosa dañada por su conducta o entregar un valor sustituto.

Solamente podrá imponerse, si la víctima y el Sancionado hayan manifestado su acuerdo.

Si ambas partes acuerdan sustituir la obligación de hacer por una suma de dinero, el Juez procederá a fijar la cuantía que considere equivalente a los daños y perjuicios ocasionados por el Hecho Delictivo.

En la Resolución respectiva deberá estipularse el plazo de cumplimiento, el cual no podrá ser mayor a un (1) año.

El Juez a cargo de la Ejecución declarará que la Sanción se encuentra cumplida, cuando el daño haya sido reparado en la forma acordada.','199','Código de la Niñez y de la Adolescencia (Decreto 73-96), texto canónico v2 con las reformas del Decreto 35-2013 (La Gaceta 33,222)','{"texto_origen":"CANONICO_D3_FUENTES_MIXTAS","transcripcion_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","text_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","cotejado_por":"Abg. y Not. Fredy Omar Pinel Flores, propietario_despacho (CLO / Director Maya Lex), firma D3 del 2026-11-18 sobre la v2 de HN:CODIGO_NINEZ (ADJUDICACION_CLO_CODIGO_NINEZ.md §3)","manifiesto_sha256":"bd4d067d1ff2980db99a7527d21f9f381d996bb0a2d63933e30f7bcaecb2d372","pliego":"docs/corpus/staging/2026-11-04-hn-001-tranche-a-drive/canonico-v2/ADJUDICACION_CLO_CODIGO_NINEZ.md","procedencia":"Fuentes mixtas acreditadas por el pliego D1–D8 firmado (ver estado_canonico de cada fila); sin V4/V5 hasta el SQL de visibilidad","norm_id":"HN:CODIGO_NINEZ","instrumento_id":"CODIGO_NINEZ","ingest_batch":"A03_CODIGO_NINEZ_01","ordinal":212,"article_sha256":"99cb558b432ce27e66be06ecc5465589bb88d00ac0a9de9b68deb6cf643002bd","vigencia":"UNKNOWN","revision_pendiente":true,"marcas":[],"estado_canonico":"TEXTO_V8_D3","fuente_canonica":"V8_LA_GACETA_33222"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_NINEZ','199','d5780ad1cc74db918f4ddd42ec471a1b835c40d23873f8b4eeac4b64ed02800d','A03_CODIGO_NINEZ_01',now()),
('A03_CODIGO_NINEZ_01:CODIGO_NINEZ:200','mayalex_normativos','10_LEYES_REGLAMENTOS','Las Órdenes de Orientación y Supervisión consisten en reglas de conducta o prohibiciones impuestas por el Juez y supervisadas por el Instituto Hondureño de la Niñez y la Familia (IHNFA), para promover y asegurar la formación integral y reinserción social de El Niño(a).

Su duración no será menor de tres (3) meses ni superior a dos (2) años.

El Juez de Ejecución podrá modificar las órdenes impuestas en caso de incumplimiento.','200','Código de la Niñez y de la Adolescencia (Decreto 73-96), texto canónico v2 con las reformas del Decreto 35-2013 (La Gaceta 33,222)','{"texto_origen":"CANONICO_D3_FUENTES_MIXTAS","transcripcion_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","text_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","cotejado_por":"Abg. y Not. Fredy Omar Pinel Flores, propietario_despacho (CLO / Director Maya Lex), firma D3 del 2026-11-18 sobre la v2 de HN:CODIGO_NINEZ (ADJUDICACION_CLO_CODIGO_NINEZ.md §3)","manifiesto_sha256":"bd4d067d1ff2980db99a7527d21f9f381d996bb0a2d63933e30f7bcaecb2d372","pliego":"docs/corpus/staging/2026-11-04-hn-001-tranche-a-drive/canonico-v2/ADJUDICACION_CLO_CODIGO_NINEZ.md","procedencia":"Fuentes mixtas acreditadas por el pliego D1–D8 firmado (ver estado_canonico de cada fila); sin V4/V5 hasta el SQL de visibilidad","norm_id":"HN:CODIGO_NINEZ","instrumento_id":"CODIGO_NINEZ","ingest_batch":"A03_CODIGO_NINEZ_01","ordinal":213,"article_sha256":"65f423a2eb61c592fc223ba8bb5dfa4335f48780f27e3b2050ccb8fae1ce764f","vigencia":"UNKNOWN","revision_pendiente":true,"marcas":[],"estado_canonico":"TEXTO_V8_D3","fuente_canonica":"V8_LA_GACETA_33222"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_NINEZ','200','2b15d11438f9fea86fcebc5a7d799ddebd443c1fe62b5e59a0e4517aeeb723e4','A03_CODIGO_NINEZ_01',now()),
('A03_CODIGO_NINEZ_01:CODIGO_NINEZ:201','mayalex_normativos','10_LEYES_REGLAMENTOS','La Privación de Libertad es de carácter excepcional, la cual deberá utilizarse cuando no sea posible aplicar ninguna otra Sanción, en los casos en los que el Sancionado sea declarado responsable por un Hecho Delictivo grave, en los términos que establecen los Artículos 204 y 205 y demás disposiciones aplicables de este Título.','201','Código de la Niñez y de la Adolescencia (Decreto 73-96), texto canónico v2 con las reformas del Decreto 35-2013 (La Gaceta 33,222)','{"texto_origen":"CANONICO_D3_FUENTES_MIXTAS","transcripcion_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","text_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","cotejado_por":"Abg. y Not. Fredy Omar Pinel Flores, propietario_despacho (CLO / Director Maya Lex), firma D3 del 2026-11-18 sobre la v2 de HN:CODIGO_NINEZ (ADJUDICACION_CLO_CODIGO_NINEZ.md §3)","manifiesto_sha256":"bd4d067d1ff2980db99a7527d21f9f381d996bb0a2d63933e30f7bcaecb2d372","pliego":"docs/corpus/staging/2026-11-04-hn-001-tranche-a-drive/canonico-v2/ADJUDICACION_CLO_CODIGO_NINEZ.md","procedencia":"Fuentes mixtas acreditadas por el pliego D1–D8 firmado (ver estado_canonico de cada fila); sin V4/V5 hasta el SQL de visibilidad","norm_id":"HN:CODIGO_NINEZ","instrumento_id":"CODIGO_NINEZ","ingest_batch":"A03_CODIGO_NINEZ_01","ordinal":214,"article_sha256":"7564f3e304c15b59af9442a62f090a7d078c1bd8589d4dfb7fcec94e17cc926b","vigencia":"UNKNOWN","revision_pendiente":true,"marcas":[],"estado_canonico":"TEXTO_V8_D3","fuente_canonica":"V8_LA_GACETA_33222"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_NINEZ','201','46d2edff2b8788c613e160d8b4cfbed51181d1406a30d5cb1e39184e77e988c3','A03_CODIGO_NINEZ_01',now()),
('A03_CODIGO_NINEZ_01:CODIGO_NINEZ:202','mayalex_normativos','10_LEYES_REGLAMENTOS','La Privación de Libertad Domiciliaria consiste en el arraigo del Sancionado a su domicilio y con su familia.

De no poder cumplirse en su domicilio, se practicará en la casa de cualquier familiar y, en su defecto, podrá ordenarse en una vivienda o en centro estatal, de comprobada idoneidad.

Esta no debe afectar el cumplimiento del trabajo, ni la asistencia al centro educativo a que concurra el Sancionado.

No será menor a uno (1) ni superior a nueve (9) meses.','202','Código de la Niñez y de la Adolescencia (Decreto 73-96), texto canónico v2 con las reformas del Decreto 35-2013 (La Gaceta 33,222)','{"texto_origen":"CANONICO_D3_FUENTES_MIXTAS","transcripcion_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","text_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","cotejado_por":"Abg. y Not. Fredy Omar Pinel Flores, propietario_despacho (CLO / Director Maya Lex), firma D3 del 2026-11-18 sobre la v2 de HN:CODIGO_NINEZ (ADJUDICACION_CLO_CODIGO_NINEZ.md §3)","manifiesto_sha256":"bd4d067d1ff2980db99a7527d21f9f381d996bb0a2d63933e30f7bcaecb2d372","pliego":"docs/corpus/staging/2026-11-04-hn-001-tranche-a-drive/canonico-v2/ADJUDICACION_CLO_CODIGO_NINEZ.md","procedencia":"Fuentes mixtas acreditadas por el pliego D1–D8 firmado (ver estado_canonico de cada fila); sin V4/V5 hasta el SQL de visibilidad","norm_id":"HN:CODIGO_NINEZ","instrumento_id":"CODIGO_NINEZ","ingest_batch":"A03_CODIGO_NINEZ_01","ordinal":215,"article_sha256":"6e5ff16c838ee47abed4f7df77f823b0c3bc70850b5e330219c69b2b04161145","vigencia":"UNKNOWN","revision_pendiente":true,"marcas":[],"estado_canonico":"TEXTO_V8_D3","fuente_canonica":"V8_LA_GACETA_33222"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_NINEZ','202','2750da80803e2addec9384ff920b5e24f157e9322e74073b4d549dcb2398edb6','A03_CODIGO_NINEZ_01',now()),
('A03_CODIGO_NINEZ_01:CODIGO_NINEZ:203','mayalex_normativos','10_LEYES_REGLAMENTOS','El Régimen de Semi-Libertad consistirá en que El Niño(a) deberá cumplir la sanción privativa de libertad durante días inhábiles, en el centro especializado que determine la respectiva Sentencia, sin perjuicio de poder realizar actividades fuera del mismo.

Esta no debe afectar el cumplimiento del trabajo, ni la asistencia al centro educativo al que concurra el Sancionado.

Esta Sanción no podrá dictarse por un plazo inferior a dos (2) ni superior a ocho (8) meses.','203','Código de la Niñez y de la Adolescencia (Decreto 73-96), texto canónico v2 con las reformas del Decreto 35-2013 (La Gaceta 33,222)','{"texto_origen":"CANONICO_D3_FUENTES_MIXTAS","transcripcion_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","text_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","cotejado_por":"Abg. y Not. Fredy Omar Pinel Flores, propietario_despacho (CLO / Director Maya Lex), firma D3 del 2026-11-18 sobre la v2 de HN:CODIGO_NINEZ (ADJUDICACION_CLO_CODIGO_NINEZ.md §3)","manifiesto_sha256":"bd4d067d1ff2980db99a7527d21f9f381d996bb0a2d63933e30f7bcaecb2d372","pliego":"docs/corpus/staging/2026-11-04-hn-001-tranche-a-drive/canonico-v2/ADJUDICACION_CLO_CODIGO_NINEZ.md","procedencia":"Fuentes mixtas acreditadas por el pliego D1–D8 firmado (ver estado_canonico de cada fila); sin V4/V5 hasta el SQL de visibilidad","norm_id":"HN:CODIGO_NINEZ","instrumento_id":"CODIGO_NINEZ","ingest_batch":"A03_CODIGO_NINEZ_01","ordinal":216,"article_sha256":"c922585ea85a43ff2efc45ab3efce1d63f7828f3150a8cb1ef3fdb9979e2cf40","vigencia":"UNKNOWN","revision_pendiente":true,"marcas":[],"estado_canonico":"TEXTO_V8_D3","fuente_canonica":"V8_LA_GACETA_33222"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_NINEZ','203','8a5fbbfbab4def1baf58de9453d185edd384bf789c36484c592209679ded2dec','A03_CODIGO_NINEZ_01',now()),
('A03_CODIGO_NINEZ_01:CODIGO_NINEZ:204','mayalex_normativos','10_LEYES_REGLAMENTOS','La Privación de Libertad en un Centro Estatal Especializado o certificado por el Instituto Hondureño de la Niñez y la Familia (IHNFA), es de carácter excepcional, podrá ser aplicada cuando:

a) Se trate de una conducta realizada mediante grave amenaza o violencia hacia las personas, la vida, la libertad individual, la libertad sexual, robo agravado y tráfico de estupefacientes; y, b) Se trate de delitos dolosos y graves, sancionados por la Ley, con una pena mínima superior a ocho (8) años.','204','Código de la Niñez y de la Adolescencia (Decreto 73-96), texto canónico v2 con las reformas del Decreto 35-2013 (La Gaceta 33,222)','{"texto_origen":"CANONICO_D3_FUENTES_MIXTAS","transcripcion_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","text_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","cotejado_por":"Abg. y Not. Fredy Omar Pinel Flores, propietario_despacho (CLO / Director Maya Lex), firma D3 del 2026-11-18 sobre la v2 de HN:CODIGO_NINEZ (ADJUDICACION_CLO_CODIGO_NINEZ.md §3)","manifiesto_sha256":"bd4d067d1ff2980db99a7527d21f9f381d996bb0a2d63933e30f7bcaecb2d372","pliego":"docs/corpus/staging/2026-11-04-hn-001-tranche-a-drive/canonico-v2/ADJUDICACION_CLO_CODIGO_NINEZ.md","procedencia":"Fuentes mixtas acreditadas por el pliego D1–D8 firmado (ver estado_canonico de cada fila); sin V4/V5 hasta el SQL de visibilidad","norm_id":"HN:CODIGO_NINEZ","instrumento_id":"CODIGO_NINEZ","ingest_batch":"A03_CODIGO_NINEZ_01","ordinal":217,"article_sha256":"92a18b725e30fd4170b3d6f9cd03a5dcf2922d9b8d4f1d409904876972df428e","vigencia":"UNKNOWN","revision_pendiente":true,"marcas":[],"estado_canonico":"TEXTO_V8_D3","fuente_canonica":"V8_LA_GACETA_33222"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_NINEZ','204','58c5dd719532dcbfc922610aa136578c8a1ad3a4eeb1999adc68ba868b4b2fc5','A03_CODIGO_NINEZ_01',now()),
('A03_CODIGO_NINEZ_01:CODIGO_NINEZ:205','mayalex_normativos','10_LEYES_REGLAMENTOS','La Privación de Libertad en un Centro Estatal Especializado o certificado por el Instituto Hondureño de la Niñez y la Familia (IHNFA), se ajustará a las reglas especiales siguientes:

a) Cuando la edad del infractor oscile entre dieciséis (16) y los dieciocho (18) años no cumplidos, la privación de libertad no podrá ser inferior a seis (6) meses ni exceder los ocho (8) años; b) Cuando la edad del infractor oscile entre catorce (14) y quince (15) años, la privación de libertad no podrá ser inferior a cuatro (4) meses ni exceder los cinco (5) años; y, c) Cuando la edad del infractor oscile entre doce (12) y trece (13) años, la privación de libertad no podrá ser inferior a un.(1) mes ni superior a tres (3) años.

El cumplimiento de esta Sanción se llevará a cabo de acuerdo al régimen que el Juez señale, tomando en cuenta

sus circunstancias personales, familiares, sociales y educativas. Para la individualización de la sanción, el Juez, deberá considerar el período de Detención Cautelar al que hubiera sido sometido.','205','Código de la Niñez y de la Adolescencia (Decreto 73-96), texto canónico v2 con las reformas del Decreto 35-2013 (La Gaceta 33,222)','{"texto_origen":"CANONICO_D3_FUENTES_MIXTAS","transcripcion_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","text_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","cotejado_por":"Abg. y Not. Fredy Omar Pinel Flores, propietario_despacho (CLO / Director Maya Lex), firma D3 del 2026-11-18 sobre la v2 de HN:CODIGO_NINEZ (ADJUDICACION_CLO_CODIGO_NINEZ.md §3)","manifiesto_sha256":"bd4d067d1ff2980db99a7527d21f9f381d996bb0a2d63933e30f7bcaecb2d372","pliego":"docs/corpus/staging/2026-11-04-hn-001-tranche-a-drive/canonico-v2/ADJUDICACION_CLO_CODIGO_NINEZ.md","procedencia":"Fuentes mixtas acreditadas por el pliego D1–D8 firmado (ver estado_canonico de cada fila); sin V4/V5 hasta el SQL de visibilidad","norm_id":"HN:CODIGO_NINEZ","instrumento_id":"CODIGO_NINEZ","ingest_batch":"A03_CODIGO_NINEZ_01","ordinal":218,"article_sha256":"75fb673861cba6e9ba8c4d876957565acfedd67bc5ba4bf2e753bc7ade2a3b5f","vigencia":"UNKNOWN","revision_pendiente":true,"marcas":[],"estado_canonico":"TEXTO_V8_D3","fuente_canonica":"V8_LA_GACETA_33222"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_NINEZ','205','ff606f1c701dfc095f8ae09b77d1d8669a9406baad7178fb96297d1b6b65744d','A03_CODIGO_NINEZ_01',now()),
('A03_CODIGO_NINEZ_01:CODIGO_NINEZ:206','mayalex_normativos','10_LEYES_REGLAMENTOS','El Juez podrá ordenar la Suspensión de la Ejecución Condicional de la sanción privativa de libertad, por un período de prueba de tres (3) años, tomando en cuenta los supuestos siguientes:

a) La sanción no exceda de dos (2) años; b) Sean notorios los esfuerzos de El Niño (a) por reparar el daño causado; c) La menor gravedad de los hechos cometidos; y, d) La conveniencia para su desarrollo educativo o laboral.

Si durante la Suspensión de la Ejecución Condicional fuere encontrado responsable de cometer un nuevo Hecho Delictivo, se le revocará el beneficio y cumplirá con la Sanción impuesta originalmente. Si no incurriera en un nuevo Hecho Delictivo durante el período de prueba y cumpliere sus condiciones, se tendrá por extinta la Sanción.','206','Código de la Niñez y de la Adolescencia (Decreto 73-96), texto canónico v2 con las reformas del Decreto 35-2013 (La Gaceta 33,222)','{"texto_origen":"CANONICO_D3_FUENTES_MIXTAS","transcripcion_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","text_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","cotejado_por":"Abg. y Not. Fredy Omar Pinel Flores, propietario_despacho (CLO / Director Maya Lex), firma D3 del 2026-11-18 sobre la v2 de HN:CODIGO_NINEZ (ADJUDICACION_CLO_CODIGO_NINEZ.md §3)","manifiesto_sha256":"bd4d067d1ff2980db99a7527d21f9f381d996bb0a2d63933e30f7bcaecb2d372","pliego":"docs/corpus/staging/2026-11-04-hn-001-tranche-a-drive/canonico-v2/ADJUDICACION_CLO_CODIGO_NINEZ.md","procedencia":"Fuentes mixtas acreditadas por el pliego D1–D8 firmado (ver estado_canonico de cada fila); sin V4/V5 hasta el SQL de visibilidad","norm_id":"HN:CODIGO_NINEZ","instrumento_id":"CODIGO_NINEZ","ingest_batch":"A03_CODIGO_NINEZ_01","ordinal":219,"article_sha256":"7cd541b0ff28065beb331c20e3e6124ac0da6511d27dd64b47503923ee465e4c","vigencia":"UNKNOWN","revision_pendiente":true,"marcas":[],"estado_canonico":"TEXTO_V8_D3","fuente_canonica":"V8_LA_GACETA_33222"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_NINEZ','206','6c88bf86217074a9b30208c105b690a3a6b44bb2c28393e433e3622d051e1da4','A03_CODIGO_NINEZ_01',now()),
('A03_CODIGO_NINEZ_01:CODIGO_NINEZ:207','mayalex_normativos','10_LEYES_REGLAMENTOS','Al menos cada tres (3) meses, el Juez de Ejecución deberá revisar de oficio o a solicitud de parte, o por recomendación técnica del equipo multidisciplinario que supervisa la ejecución de la Sanción, la posibilidad de sustituirla por otra menos gravosa, de conformidad con el desenvolvimiento de El Niño(a) durante el cumplimiento de su Sanción.

Este período no será tomado en cuenta, cuando las circunstancias del infractor ameriten la revisión inmediata de la Sanción.','207','Código de la Niñez y de la Adolescencia (Decreto 73-96), texto canónico v2 con las reformas del Decreto 35-2013 (La Gaceta 33,222)','{"texto_origen":"CANONICO_D3_FUENTES_MIXTAS","transcripcion_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","text_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","cotejado_por":"Abg. y Not. Fredy Omar Pinel Flores, propietario_despacho (CLO / Director Maya Lex), firma D3 del 2026-11-18 sobre la v2 de HN:CODIGO_NINEZ (ADJUDICACION_CLO_CODIGO_NINEZ.md §3)","manifiesto_sha256":"bd4d067d1ff2980db99a7527d21f9f381d996bb0a2d63933e30f7bcaecb2d372","pliego":"docs/corpus/staging/2026-11-04-hn-001-tranche-a-drive/canonico-v2/ADJUDICACION_CLO_CODIGO_NINEZ.md","procedencia":"Fuentes mixtas acreditadas por el pliego D1–D8 firmado (ver estado_canonico de cada fila); sin V4/V5 hasta el SQL de visibilidad","norm_id":"HN:CODIGO_NINEZ","instrumento_id":"CODIGO_NINEZ","ingest_batch":"A03_CODIGO_NINEZ_01","ordinal":220,"article_sha256":"29e12d47f90e9b0f0c7cfd2393bd6b5bc4bfe52c69827235604c03d0eff6a685","vigencia":"UNKNOWN","revision_pendiente":true,"marcas":[],"estado_canonico":"TEXTO_V8_D3","fuente_canonica":"V8_LA_GACETA_33222"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_NINEZ','207','26a4497f35b066e2e57c3b7f356a87f144d3eadae74419f4695923b0b183ed80','A03_CODIGO_NINEZ_01',now()),
('A03_CODIGO_NINEZ_01:CODIGO_NINEZ:208','mayalex_normativos','10_LEYES_REGLAMENTOS','No podrá atribuirse al Sancionado el incumplimiento de las sanciones que se le hayan impuesto, cuando sea el Estado quien haya incumplido en la creación y organización de los programas para el seguimiento, supervisión y atención integral de éstos. Caso en el cual, se deducirá la responsabilidad administrativa, civil o penal que corresponda.','208','Código de la Niñez y de la Adolescencia (Decreto 73-96), texto canónico v2 con las reformas del Decreto 35-2013 (La Gaceta 33,222)','{"texto_origen":"CANONICO_D3_FUENTES_MIXTAS","transcripcion_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","text_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","cotejado_por":"Abg. y Not. Fredy Omar Pinel Flores, propietario_despacho (CLO / Director Maya Lex), firma D3 del 2026-11-18 sobre la v2 de HN:CODIGO_NINEZ (ADJUDICACION_CLO_CODIGO_NINEZ.md §3)","manifiesto_sha256":"bd4d067d1ff2980db99a7527d21f9f381d996bb0a2d63933e30f7bcaecb2d372","pliego":"docs/corpus/staging/2026-11-04-hn-001-tranche-a-drive/canonico-v2/ADJUDICACION_CLO_CODIGO_NINEZ.md","procedencia":"Fuentes mixtas acreditadas por el pliego D1–D8 firmado (ver estado_canonico de cada fila); sin V4/V5 hasta el SQL de visibilidad","norm_id":"HN:CODIGO_NINEZ","instrumento_id":"CODIGO_NINEZ","ingest_batch":"A03_CODIGO_NINEZ_01","ordinal":221,"article_sha256":"80304f4b08d29e8e25f68e3ea9ae52dd1cba8fd8b2992a73b5c463b45b6d7204","vigencia":"UNKNOWN","revision_pendiente":true,"marcas":[],"estado_canonico":"TEXTO_V8_D3","fuente_canonica":"V8_LA_GACETA_33222"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_NINEZ','208','395655d273ffe4dde2715f2171a0b531eb16499e4e1185afb90169ca79d802f3','A03_CODIGO_NINEZ_01',now()),
('A03_CODIGO_NINEZ_01:CODIGO_NINEZ:209','mayalex_normativos','10_LEYES_REGLAMENTOS','El Proceso Para la Niñez Infractora de La Ley tiene como objetivo establecer la existencia jurídica de una conducta tipificada como Hecho Delictivo o Falta,

quién es su autor, el grado de responsabilidad de éste y, en su caso, determinar la aplicación de las sanciones que correspondan.

Este se llevará a cabo de acuerdo a lo dispuesto en este Código y, supletoriamente, conforme al Código Procesal Penal, orientándose por los principios rectores y demás disposiciones de especialidad establecidas en este Título.

Comprenderá las Fases: Preparatoria, Intermedia y de Juicio, así como las Formas Alternativas o Simplificadas del Proceso y los presupuestos de procedibilidad y aplicación de los recursos.

No se aplicará la figura de procedimiento abreviado en materia penal para Niños(as).','209','Código de la Niñez y de la Adolescencia (Decreto 73-96), texto canónico v2 con las reformas del Decreto 35-2013 (La Gaceta 33,222)','{"texto_origen":"CANONICO_D3_FUENTES_MIXTAS","transcripcion_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","text_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","cotejado_por":"Abg. y Not. Fredy Omar Pinel Flores, propietario_despacho (CLO / Director Maya Lex), firma D3 del 2026-11-18 sobre la v2 de HN:CODIGO_NINEZ (ADJUDICACION_CLO_CODIGO_NINEZ.md §3)","manifiesto_sha256":"bd4d067d1ff2980db99a7527d21f9f381d996bb0a2d63933e30f7bcaecb2d372","pliego":"docs/corpus/staging/2026-11-04-hn-001-tranche-a-drive/canonico-v2/ADJUDICACION_CLO_CODIGO_NINEZ.md","procedencia":"Fuentes mixtas acreditadas por el pliego D1–D8 firmado (ver estado_canonico de cada fila); sin V4/V5 hasta el SQL de visibilidad","norm_id":"HN:CODIGO_NINEZ","instrumento_id":"CODIGO_NINEZ","ingest_batch":"A03_CODIGO_NINEZ_01","ordinal":222,"article_sha256":"bd09dcf576f9f0711ed814bed042d2c1d8ef44b869374601d4e83fa626dcbfc4","vigencia":"UNKNOWN","revision_pendiente":true,"marcas":[],"estado_canonico":"TEXTO_V8_D3","fuente_canonica":"V8_LA_GACETA_33222"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_NINEZ','209','ba5623826433d4cf76cf7f662abc91c50ccdee5172276d65a64d438a69ccd294','A03_CODIGO_NINEZ_01',now()),
('A03_CODIGO_NINEZ_01:CODIGO_NINEZ:210','mayalex_normativos','10_LEYES_REGLAMENTOS','El Estado creará progresivamente la Jurisdicción Especial de la Niñez Infractora de La Ley, la que estará integrada por:

a) Jueces de Garantías; b) Jueces de Juicio; c) Jueces de Ej ecución; y, d) Tribunales de Apelaciones.

En tanto ésta se crea, el Estado garantizará que al funcionario que haya ejercido la función de Juez de Garantías en un determinado Proceso, no se le asigne el conocimiento de su juzgamiento ni su ejecución.

Para tales efectos, por medio de las instancias respectivas, adoptará las medidas generales y particulares que aseguren una adecuada distribución de competencias entre los Jueces de Letras de Niñez y los Jueces de Letras Seccionales.','210','Código de la Niñez y de la Adolescencia (Decreto 73-96), texto canónico v2 con las reformas del Decreto 35-2013 (La Gaceta 33,222)','{"texto_origen":"CANONICO_D3_FUENTES_MIXTAS","transcripcion_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","text_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","cotejado_por":"Abg. y Not. Fredy Omar Pinel Flores, propietario_despacho (CLO / Director Maya Lex), firma D3 del 2026-11-18 sobre la v2 de HN:CODIGO_NINEZ (ADJUDICACION_CLO_CODIGO_NINEZ.md §3)","manifiesto_sha256":"bd4d067d1ff2980db99a7527d21f9f381d996bb0a2d63933e30f7bcaecb2d372","pliego":"docs/corpus/staging/2026-11-04-hn-001-tranche-a-drive/canonico-v2/ADJUDICACION_CLO_CODIGO_NINEZ.md","procedencia":"Fuentes mixtas acreditadas por el pliego D1–D8 firmado (ver estado_canonico de cada fila); sin V4/V5 hasta el SQL de visibilidad","norm_id":"HN:CODIGO_NINEZ","instrumento_id":"CODIGO_NINEZ","ingest_batch":"A03_CODIGO_NINEZ_01","ordinal":223,"article_sha256":"188b26946789cbf202198bae6d7b8a6595d7be59e5f307c867fd43bbfa10b3c2","vigencia":"UNKNOWN","revision_pendiente":true,"marcas":[],"estado_canonico":"TEXTO_V8_D3","fuente_canonica":"V8_LA_GACETA_33222"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_NINEZ','210','898be465bf6ed1290f11a1600cd1b6d45837c331dc4bb95fb3b388483756df83','A03_CODIGO_NINEZ_01',now()),
('A03_CODIGO_NINEZ_01:CODIGO_NINEZ:211','mayalex_normativos','10_LEYES_REGLAMENTOS','Corresponde al Juez de Garantías:

a) Conocer de las Fases Preparatoria e Intermedia, de conformidad a lo establecido en este Título; b) Velar por el respeto de los derechos fundamentales de los Niños(as) en Proceso; c) Dictar, en los plazos y términos previstos, la Vinculación al Proceso y las Medidas Cautelares aplicables, cuando correspondiere; d) Llamar y presidir la audiencia intermedia y dictar el auto de Apertura a Juicio;

e) Aprobar la solicitud de Suspensión del Proceso a Prueba y sus condiciones, así como resolver sobre la revocación de la misma y la reanudación del Proceso cuando procediere; f) Ordenar, cuando proceda, la evacuación de elementos de prueba con las formalidades de prueba anticipada g) Declarar la extinción de la acción penal o la reanudación del Proceso por incumplimiento de la Conciliación; h) Decidir sobre el uso de las formas alternativas de solución de conflictos establecidas en este Título; e, i) Las demás que se disponen en este Código.','211','Código de la Niñez y de la Adolescencia (Decreto 73-96), texto canónico v2 con las reformas del Decreto 35-2013 (La Gaceta 33,222)','{"texto_origen":"CANONICO_D3_FUENTES_MIXTAS","transcripcion_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","text_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","cotejado_por":"Abg. y Not. Fredy Omar Pinel Flores, propietario_despacho (CLO / Director Maya Lex), firma D3 del 2026-11-18 sobre la v2 de HN:CODIGO_NINEZ (ADJUDICACION_CLO_CODIGO_NINEZ.md §3)","manifiesto_sha256":"bd4d067d1ff2980db99a7527d21f9f381d996bb0a2d63933e30f7bcaecb2d372","pliego":"docs/corpus/staging/2026-11-04-hn-001-tranche-a-drive/canonico-v2/ADJUDICACION_CLO_CODIGO_NINEZ.md","procedencia":"Fuentes mixtas acreditadas por el pliego D1–D8 firmado (ver estado_canonico de cada fila); sin V4/V5 hasta el SQL de visibilidad","norm_id":"HN:CODIGO_NINEZ","instrumento_id":"CODIGO_NINEZ","ingest_batch":"A03_CODIGO_NINEZ_01","ordinal":224,"article_sha256":"f5391d1883601e72dad3970fc1b5862db949f50663abf9e75d772e7833787616","vigencia":"UNKNOWN","revision_pendiente":true,"marcas":[],"estado_canonico":"TEXTO_V8_D3","fuente_canonica":"V8_LA_GACETA_33222"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_NINEZ','211','52750e5ecea821869bbf02e0324aaf31460eac593955c049452c9a6bbaec0c84','A03_CODIGO_NINEZ_01',now()),
('A03_CODIGO_NINEZ_01:CODIGO_NINEZ:212','mayalex_normativos','10_LEYES_REGLAMENTOS','Corresponde al Juez de Juicio:

a) Presidir la Audiencia de Juicio y resolver los asuntos sometidos a su conocimiento, conforme a los plazos y términos previstos; b) Declarar la responsabilidad penal o inocencia de Niños(as) en Proceso; c) Imponer las sanciones, atendiendo a los principios rectores descritos en este Código, la proporcionalidad y racionalidad de la conducta, así como a la circunstancias de gravedad de la conducta características y necesidades de los Niños(as); y, d) Las demás responsabilidades que se disponen en este Código.','212','Código de la Niñez y de la Adolescencia (Decreto 73-96), texto canónico v2 con las reformas del Decreto 35-2013 (La Gaceta 33,222)','{"texto_origen":"CANONICO_D3_FUENTES_MIXTAS","transcripcion_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","text_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","cotejado_por":"Abg. y Not. Fredy Omar Pinel Flores, propietario_despacho (CLO / Director Maya Lex), firma D3 del 2026-11-18 sobre la v2 de HN:CODIGO_NINEZ (ADJUDICACION_CLO_CODIGO_NINEZ.md §3)","manifiesto_sha256":"bd4d067d1ff2980db99a7527d21f9f381d996bb0a2d63933e30f7bcaecb2d372","pliego":"docs/corpus/staging/2026-11-04-hn-001-tranche-a-drive/canonico-v2/ADJUDICACION_CLO_CODIGO_NINEZ.md","procedencia":"Fuentes mixtas acreditadas por el pliego D1–D8 firmado (ver estado_canonico de cada fila); sin V4/V5 hasta el SQL de visibilidad","norm_id":"HN:CODIGO_NINEZ","instrumento_id":"CODIGO_NINEZ","ingest_batch":"A03_CODIGO_NINEZ_01","ordinal":225,"article_sha256":"4051a81f08573e5cb3dcfca0437b3d534a696b10f43dbd028785ca4165213365","vigencia":"UNKNOWN","revision_pendiente":true,"marcas":[],"estado_canonico":"TEXTO_V8_D3","fuente_canonica":"V8_LA_GACETA_33222"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_NINEZ','212','ccd1b048d5440862a7b0c478f838f53e5deb2d6746479cbbc5e77f6ded13b3e3','A03_CODIGO_NINEZ_01',now()),
('A03_CODIGO_NINEZ_01:CODIGO_NINEZ:213','mayalex_normativos','10_LEYES_REGLAMENTOS','Corresponde al Juez de Ejecución:

a) Controlar que la ejecución de toda Sanción se conforme con la sentencia que la impuso, garantizando la legalidad y demás derechos y garantías que asisten al Sancionado; b) Revisar las sanciones de oficio o a solicitud de parte al menos cada tres (3) meses, para cesarlas modificarlas o sustituirlas por otras menos gravosas cuando no cumplan con los objetivos para los que fueron impuestas o por ser contrarias al proceso de reinserción social; c) La vigilancia y control de la ejecución de las sanciones así como velar por la correcta aplicación de las normas que regulan el régimen de privación de libertad; d) Controlar el otorgamiento o denegación de cualquier beneficio relacionado con las sanciones impuestas; e) Ordenar la cesación de la sanción una vez transcurrido el plazo o condición fijado por la sentencia y enviar

las comunicaciones a la institución estatal responsable de la Ejecución; f) Atender las solicitudes que hagan los Sancionados, dar curso a sus quejas cuando así lo amerite la situación y resolver lo que corresponda; g) Corregir los abusos y desviaciones que puedan producirse en el cumplimiento de los preceptos contenidos en este Código, relacionados con sus competencias; h) Visitar los centros de Ejecución o cumplimiento de la sanción privativa de libertad, al menos una (1) vez al mes y formular las recomendaciones necesarias; i) Conocer y resolver los reclamos sobre las decisiones de los órganos directivos, administrativos y técnicos de los Centros Especializados de Privación de Libertad; y, j) Las demás responsabilidades que éste Código y las leyes le atribuyan.','213','Código de la Niñez y de la Adolescencia (Decreto 73-96), texto canónico v2 con las reformas del Decreto 35-2013 (La Gaceta 33,222)','{"texto_origen":"CANONICO_D3_FUENTES_MIXTAS","transcripcion_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","text_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","cotejado_por":"Abg. y Not. Fredy Omar Pinel Flores, propietario_despacho (CLO / Director Maya Lex), firma D3 del 2026-11-18 sobre la v2 de HN:CODIGO_NINEZ (ADJUDICACION_CLO_CODIGO_NINEZ.md §3)","manifiesto_sha256":"bd4d067d1ff2980db99a7527d21f9f381d996bb0a2d63933e30f7bcaecb2d372","pliego":"docs/corpus/staging/2026-11-04-hn-001-tranche-a-drive/canonico-v2/ADJUDICACION_CLO_CODIGO_NINEZ.md","procedencia":"Fuentes mixtas acreditadas por el pliego D1–D8 firmado (ver estado_canonico de cada fila); sin V4/V5 hasta el SQL de visibilidad","norm_id":"HN:CODIGO_NINEZ","instrumento_id":"CODIGO_NINEZ","ingest_batch":"A03_CODIGO_NINEZ_01","ordinal":226,"article_sha256":"af64ffc4efbfb7a9bbf96a89561d9813f2ef8b2cfd1385b2a01cdf87d23c9679","vigencia":"UNKNOWN","revision_pendiente":true,"marcas":[],"estado_canonico":"TEXTO_V8_D3","fuente_canonica":"V8_LA_GACETA_33222"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_NINEZ','213','e43b28e88bec684ce348f1ec7ae28da1040f62a7e4d14b7770223d3358594634','A03_CODIGO_NINEZ_01',now()),
('A03_CODIGO_NINEZ_01:CODIGO_NINEZ:214','mayalex_normativos','10_LEYES_REGLAMENTOS','Los Tribunales de Apelaciones, resolverán los recursos de apelación en esta materia, en el término territorial que les corresponda, conforme a lo dispuesto en el Código Procesal Penal y las disposiciones especiales previstas en este Título.

Mientras se crean estas instancias, la Corte de Apelaciones Ordinaria respectiva conocerá de la vía recursiva en esta materia, conforme a la competencia por razón del territorio.','214','Código de la Niñez y de la Adolescencia (Decreto 73-96), texto canónico v2 con las reformas del Decreto 35-2013 (La Gaceta 33,222)','{"texto_origen":"CANONICO_D3_FUENTES_MIXTAS","transcripcion_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","text_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","cotejado_por":"Abg. y Not. Fredy Omar Pinel Flores, propietario_despacho (CLO / Director Maya Lex), firma D3 del 2026-11-18 sobre la v2 de HN:CODIGO_NINEZ (ADJUDICACION_CLO_CODIGO_NINEZ.md §3)","manifiesto_sha256":"bd4d067d1ff2980db99a7527d21f9f381d996bb0a2d63933e30f7bcaecb2d372","pliego":"docs/corpus/staging/2026-11-04-hn-001-tranche-a-drive/canonico-v2/ADJUDICACION_CLO_CODIGO_NINEZ.md","procedencia":"Fuentes mixtas acreditadas por el pliego D1–D8 firmado (ver estado_canonico de cada fila); sin V4/V5 hasta el SQL de visibilidad","norm_id":"HN:CODIGO_NINEZ","instrumento_id":"CODIGO_NINEZ","ingest_batch":"A03_CODIGO_NINEZ_01","ordinal":227,"article_sha256":"126bd591829784aeff58534a0aa048948fb6891ef9833cc707bcd79a6f8b9211","vigencia":"UNKNOWN","revision_pendiente":true,"marcas":[],"estado_canonico":"TEXTO_V8_D3","fuente_canonica":"V8_LA_GACETA_33222"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_NINEZ','214','a688582588113bd33d05f3991bfd54acf7de994254e773cc3064da720c440622','A03_CODIGO_NINEZ_01',now()),
('A03_CODIGO_NINEZ_01:CODIGO_NINEZ:215','mayalex_normativos','10_LEYES_REGLAMENTOS','El Ministerio Público, la Defensa Pública, La Policía Nacional y otros funcionarios intervinientes en el Proceso, tendrán en materia de la Jurisdicción Especial de la Niñez Infractora de la Ley, los deberes, facultades y atribuciones que en este Título, en el Código Procesal Penal y en sus regulaciones propias se disponga.','215','Código de la Niñez y de la Adolescencia (Decreto 73-96), texto canónico v2 con las reformas del Decreto 35-2013 (La Gaceta 33,222)','{"texto_origen":"CANONICO_D3_FUENTES_MIXTAS","transcripcion_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","text_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","cotejado_por":"Abg. y Not. Fredy Omar Pinel Flores, propietario_despacho (CLO / Director Maya Lex), firma D3 del 2026-11-18 sobre la v2 de HN:CODIGO_NINEZ (ADJUDICACION_CLO_CODIGO_NINEZ.md §3)","manifiesto_sha256":"bd4d067d1ff2980db99a7527d21f9f381d996bb0a2d63933e30f7bcaecb2d372","pliego":"docs/corpus/staging/2026-11-04-hn-001-tranche-a-drive/canonico-v2/ADJUDICACION_CLO_CODIGO_NINEZ.md","procedencia":"Fuentes mixtas acreditadas por el pliego D1–D8 firmado (ver estado_canonico de cada fila); sin V4/V5 hasta el SQL de visibilidad","norm_id":"HN:CODIGO_NINEZ","instrumento_id":"CODIGO_NINEZ","ingest_batch":"A03_CODIGO_NINEZ_01","ordinal":228,"article_sha256":"9d821818e02acddd475a85db5317497e3ef10737a67eef2a1915c9a8a37d3f21","vigencia":"UNKNOWN","revision_pendiente":true,"marcas":[],"estado_canonico":"TEXTO_V8_D3","fuente_canonica":"V8_LA_GACETA_33222"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_NINEZ','215','d21c562f9afe1dd556926621a40a77ad6fc9543f82444e3bfd8aa853f26aabdc','A03_CODIGO_NINEZ_01',now()),
('A03_CODIGO_NINEZ_01:CODIGO_NINEZ:216','mayalex_normativos','10_LEYES_REGLAMENTOS','Son Formas Alternativas o Simplificadas de Solución de los Conflictos sometidos a la Jurisdicción Especial de la Niñez, las siguientes:

a) Criterio de Oportunidad; b) Conciliación; y, c) Suspensión del Proceso a Prueba".','216','Código de la Niñez y de la Adolescencia (Decreto 73-96), texto canónico v2 con las reformas del Decreto 35-2013 (La Gaceta 33,222)','{"texto_origen":"CANONICO_D3_FUENTES_MIXTAS","transcripcion_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","text_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","cotejado_por":"Abg. y Not. Fredy Omar Pinel Flores, propietario_despacho (CLO / Director Maya Lex), firma D3 del 2026-11-18 sobre la v2 de HN:CODIGO_NINEZ (ADJUDICACION_CLO_CODIGO_NINEZ.md §3)","manifiesto_sha256":"bd4d067d1ff2980db99a7527d21f9f381d996bb0a2d63933e30f7bcaecb2d372","pliego":"docs/corpus/staging/2026-11-04-hn-001-tranche-a-drive/canonico-v2/ADJUDICACION_CLO_CODIGO_NINEZ.md","procedencia":"Fuentes mixtas acreditadas por el pliego D1–D8 firmado (ver estado_canonico de cada fila); sin V4/V5 hasta el SQL de visibilidad","norm_id":"HN:CODIGO_NINEZ","instrumento_id":"CODIGO_NINEZ","ingest_batch":"A03_CODIGO_NINEZ_01","ordinal":229,"article_sha256":"b3e00a784b9107cbd76584aa66d5624fd5493624cab66e798dd4141ceaa0ee60","vigencia":"UNKNOWN","revision_pendiente":true,"marcas":[],"estado_canonico":"TEXTO_V8_D3","fuente_canonica":"V8_LA_GACETA_33222"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_NINEZ','216','34ce94c60fb5bc6be5a997aa9aff141d4e18d11450f2cfdaf714433c78dd9f05','A03_CODIGO_NINEZ_01',now()),
('A03_CODIGO_NINEZ_01:CODIGO_NINEZ:217','mayalex_normativos','10_LEYES_REGLAMENTOS','El representante del Ministerio Público deberá ejercer la acción penal en todos los casos en que sea procedente, con arreglo a las disposiciones de este Código. No obstante, podrá solicitar que se prescinda, total

o parcialmente de la persecución penal, que se limite a alguno o a varios hechos o a solamente alguno de los Niños(as) que supuestamente participaron en su realización, en los casos siguientes:

a) Cuando la pena aplicable al Hecho Delictivo no exceda de cinco (5) años, la afectación del interés público sea mínima y, de los antecedentes y circunstancias personales de los Niños(as), se infiera su falta de peligrosidad; b) Se trate de un hecho insignificante, de mínima culpabilidad del supuesto autor o partícipe o ínfima contribución de éste, salvo que afecte seriamente un interés público; c) El Niño(a) haya sufrido a consecuencia del hecho, grave daño físico o psíquico que torne desproporcionada la aplicación de una Sanción o cuando en ocasión de una infracción culposa haya sufrido un daño moral de difícil superación; d) El Niño(a), hubiera hecho cuanto estaba a su alcance para impedir los efectos de la consumación del Hecho Delictivo; e) Cuando la pena a aplicar por un delito, sea de menor importancia, en comparación con la que se le impuso o se le debe imponer a la misma persona por otro Hecho delictivo conexo; y, f) Cuando se trate de Hechos Delictivos de delincuencia organizada, criminalidad violenta protagonizada por grupos o bandas de delincuentes, otros delitos graves de realización compleja que dificulte su investigación y persecución, y colabore eficazmente con la investigación, brinde información especial para evitar que continúe el Hecho Delictivo o se perpetren otros o ayude a esclarecer el hecho investigado u otros conexos o proporcione información útil para probar la participación de terceras personas, siempre que la acción penal de la cual se trate resulte más leve que los hechos punibles cuya persecución facilite o cuya continuación evite.

El Fiscal del caso deberá aplicar el Criterio de Oportunidad sobre la base de razones objetivas y sin discriminación, valorando las pautas descritas en cada caso individual, salvo en el supuesto contemplado por el inciso f) donde se procederá conforme las reglas generales que al efecto haya dictado el Ministerio Público.

El Ministerio Público velará que el daño causado sea razonablemente reparado.

Para la tramitación del Criterio de Oportunidad, se estará a lo dispuesto en el Código Procesal Penal.','217','Código de la Niñez y de la Adolescencia (Decreto 73-96), texto canónico v2 con las reformas del Decreto 35-2013 (La Gaceta 33,222)','{"texto_origen":"CANONICO_D3_FUENTES_MIXTAS","transcripcion_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","text_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","cotejado_por":"Abg. y Not. Fredy Omar Pinel Flores, propietario_despacho (CLO / Director Maya Lex), firma D3 del 2026-11-18 sobre la v2 de HN:CODIGO_NINEZ (ADJUDICACION_CLO_CODIGO_NINEZ.md §3)","manifiesto_sha256":"bd4d067d1ff2980db99a7527d21f9f381d996bb0a2d63933e30f7bcaecb2d372","pliego":"docs/corpus/staging/2026-11-04-hn-001-tranche-a-drive/canonico-v2/ADJUDICACION_CLO_CODIGO_NINEZ.md","procedencia":"Fuentes mixtas acreditadas por el pliego D1–D8 firmado (ver estado_canonico de cada fila); sin V4/V5 hasta el SQL de visibilidad","norm_id":"HN:CODIGO_NINEZ","instrumento_id":"CODIGO_NINEZ","ingest_batch":"A03_CODIGO_NINEZ_01","ordinal":230,"article_sha256":"1996af82c32585c9d961e163521fba29f0c64e85e9d0d704acbff53f75be946f","vigencia":"UNKNOWN","revision_pendiente":true,"marcas":[],"estado_canonico":"TEXTO_V8_D3","fuente_canonica":"V8_LA_GACETA_33222"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_NINEZ','217','a8207cc1a4542acd3b7ca299c0a95cc2b0c01c510dcf7f9315245c80fa33dab6','A03_CODIGO_NINEZ_01',now()),
('A03_CODIGO_NINEZ_01:CODIGO_NINEZ:218','mayalex_normativos','10_LEYES_REGLAMENTOS','Procederá la Conciliación entre la víctima y El Niño(a), en todo momento y hasta antes de dictarse el auto de Apertura a Juicio.

Podrán solicitarla tanto el Ministerio Público o las partes, igualmente en el caso de las Faltas, los Hechos Delictivos de acción privada, de acción pública dependientes de instancia particular como en los que admitan la Suspensión del Proceso a Prueba, a cuyo efecto el Juez les hará saber que cuentan con la posibilidad de conciliar y si están de acuerdo y preparados, practicará la Conciliación.

La conciliación se rige por los principios de: voluntariedad de las partes, confidencialidad, flexibilidad, neutralidad, imparcialidad, equidad, legalidad y honestidad.

La información que se genere en los procedimientos respectivos no podrá ser utilizada en perjuicio de las partes dentro del Proceso o del Proceso Penal, en su caso.

Para los efectos de la Conciliación el Juez podrá aprobar el asesoramiento y el auxilio de personas o entidades especializadas en la materia.

No se aprobará la conciliación cuando se tengan fundados motivos para estimar que alguno de los intervinientes no se encontraba en condiciones de igualdad para negociar o hubiera actuado bajo coacción o amenaza.

Una vez propuesta la Conciliación, el Juez señalará la audiencia respectiva dentro de un plazo que no podrá exceder los veinte (20) días.

El plazo fijado para el cumplimiento de las obligaciones pactadas no podrá ser superior a tres (3) meses; durante el cual se suspenderá el trámite del Proceso y de la prescripción de la acción penal. Comenzará a contarse a partir del día siguiente de la homologación del acuerdo.

No se podrá conciliar cuando se trate de los Hechos Delictivos siguientes:

a) De naturaleza dolosa contra la vida y las lesiones graves; b) Contra la libertad e integridad física, psicológica y sexual; c) Cuando el Sujeto Pasivo sea menor de dieciocho (18) años de edad; y, d) Sea producto de redes de crimen organizado.','218','Código de la Niñez y de la Adolescencia (Decreto 73-96), texto canónico v2 con las reformas del Decreto 35-2013 (La Gaceta 33,222)','{"texto_origen":"CANONICO_D3_FUENTES_MIXTAS","transcripcion_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","text_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","cotejado_por":"Abg. y Not. Fredy Omar Pinel Flores, propietario_despacho (CLO / Director Maya Lex), firma D3 del 2026-11-18 sobre la v2 de HN:CODIGO_NINEZ (ADJUDICACION_CLO_CODIGO_NINEZ.md §3)","manifiesto_sha256":"bd4d067d1ff2980db99a7527d21f9f381d996bb0a2d63933e30f7bcaecb2d372","pliego":"docs/corpus/staging/2026-11-04-hn-001-tranche-a-drive/canonico-v2/ADJUDICACION_CLO_CODIGO_NINEZ.md","procedencia":"Fuentes mixtas acreditadas por el pliego D1–D8 firmado (ver estado_canonico de cada fila); sin V4/V5 hasta el SQL de visibilidad","norm_id":"HN:CODIGO_NINEZ","instrumento_id":"CODIGO_NINEZ","ingest_batch":"A03_CODIGO_NINEZ_01","ordinal":231,"article_sha256":"dc6a3a74f754854f79644a3303925756048f06c620c8ff6f89d1e64dcd0d83b8","vigencia":"UNKNOWN","revision_pendiente":true,"marcas":[],"estado_canonico":"TEXTO_V8_D3","fuente_canonica":"V8_LA_GACETA_33222"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_NINEZ','218','7314fc18862a36ab02d251ce0f8b1cbece9e7e02eb6230bbf66d4448ec67ae40','A03_CODIGO_NINEZ_01',now()),
('A03_CODIGO_NINEZ_01:CODIGO_NINEZ:219','mayalex_normativos','10_LEYES_REGLAMENTOS','Procederá la Suspensión del Proceso a Prueba en los casos en que el máximo de la pena aplicable al Hecho Delictivo de que se trate no exceda de nueve (9) años y siempre que no se encuentre o haya gozado de este beneficio en otro Proceso.

La solicitud podrá ser presentada por El Niño(a) o por el Fiscal, en cualquier momento hasta antes del auto de Apertura a Juicio.','219','Código de la Niñez y de la Adolescencia (Decreto 73-96), texto canónico v2 con las reformas del Decreto 35-2013 (La Gaceta 33,222)','{"texto_origen":"CANONICO_D3_FUENTES_MIXTAS","transcripcion_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","text_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","cotejado_por":"Abg. y Not. Fredy Omar Pinel Flores, propietario_despacho (CLO / Director Maya Lex), firma D3 del 2026-11-18 sobre la v2 de HN:CODIGO_NINEZ (ADJUDICACION_CLO_CODIGO_NINEZ.md §3)","manifiesto_sha256":"bd4d067d1ff2980db99a7527d21f9f381d996bb0a2d63933e30f7bcaecb2d372","pliego":"docs/corpus/staging/2026-11-04-hn-001-tranche-a-drive/canonico-v2/ADJUDICACION_CLO_CODIGO_NINEZ.md","procedencia":"Fuentes mixtas acreditadas por el pliego D1–D8 firmado (ver estado_canonico de cada fila); sin V4/V5 hasta el SQL de visibilidad","norm_id":"HN:CODIGO_NINEZ","instrumento_id":"CODIGO_NINEZ","ingest_batch":"A03_CODIGO_NINEZ_01","ordinal":232,"article_sha256":"c1dbb228f34e919bad5fd01d2a2e4a3f5761cb5435f33a0e98166ec6f843b562","vigencia":"UNKNOWN","revision_pendiente":true,"marcas":[],"estado_canonico":"TEXTO_V8_D3","fuente_canonica":"V8_LA_GACETA_33222"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_NINEZ','219','fdd5dd749795b9e45997554fae6aae535fd747aeff826f20bce2e1b0460c275b','A03_CODIGO_NINEZ_01',now()),
('A03_CODIGO_NINEZ_01:CODIGO_NINEZ:220','mayalex_normativos','10_LEYES_REGLAMENTOS','La solicitud de Suspensión del Proceso a Prueba deberá contener un Plan de Reparación del Daño causado por el Hecho Delictivo y un detalle de las condiciones que El Niño(a) estaría dispuesto a cumplir. Este podrá consistir en una indemnización equivalente a la reparación del daño que, en su caso, pudiera llegar a imponerse o una reparación simbólica, inmediata o por cumplir a plazos.

Para el otorgamiento de la suspensión será condición indispensable que El Niño(a) admita el hecho que se le atribuye. El trámite no podrá exceder de veinte (20) días, contados a partir de la solicitud.

La resolución que declare inadmisible la solicitud de Suspensión del Proceso a Prueba será recurrible".','220','Código de la Niñez y de la Adolescencia (Decreto 73-96), texto canónico v2 con las reformas del Decreto 35-2013 (La Gaceta 33,222)','{"texto_origen":"CANONICO_D3_FUENTES_MIXTAS","transcripcion_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","text_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","cotejado_por":"Abg. y Not. Fredy Omar Pinel Flores, propietario_despacho (CLO / Director Maya Lex), firma D3 del 2026-11-18 sobre la v2 de HN:CODIGO_NINEZ (ADJUDICACION_CLO_CODIGO_NINEZ.md §3)","manifiesto_sha256":"bd4d067d1ff2980db99a7527d21f9f381d996bb0a2d63933e30f7bcaecb2d372","pliego":"docs/corpus/staging/2026-11-04-hn-001-tranche-a-drive/canonico-v2/ADJUDICACION_CLO_CODIGO_NINEZ.md","procedencia":"Fuentes mixtas acreditadas por el pliego D1–D8 firmado (ver estado_canonico de cada fila); sin V4/V5 hasta el SQL de visibilidad","norm_id":"HN:CODIGO_NINEZ","instrumento_id":"CODIGO_NINEZ","ingest_batch":"A03_CODIGO_NINEZ_01","ordinal":233,"article_sha256":"152d78166b75f211d039b2debb126a0b52c7cdbe3fe6a1d0d366f01a7ae376bf","vigencia":"UNKNOWN","revision_pendiente":true,"marcas":[],"estado_canonico":"TEXTO_V8_D3","fuente_canonica":"V8_LA_GACETA_33222"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_NINEZ','220','24343052fb45a6b4eac5ac17524c21fc19d3e4b7bfabcb1f7c65c024d47e8e9a','A03_CODIGO_NINEZ_01',now()),
('A03_CODIGO_NINEZ_01:CODIGO_NINEZ:221','mayalex_normativos','10_LEYES_REGLAMENTOS','El Juez oirá en audiencia al peticionario sobre la solicitud de Suspensión del Proceso a Prueba, así mismo a las partes, debiendo resolver de inmediato, salvo que difiera su decisión para nueva audiencia, la que se realizará dentro de un plazo no mayor de diez (10) días.

La resolución fijará las condiciones bajo las cuales se suspende el proceso o se rechaza la solicitud; en el primer caso aprobará o modificará el plan de reparación con el acuerdo entre las partes. La sola falta de recursos de El Niño(a) no podrá aducirse para rechazar la solicitud.

Si se rechaza la solicitud, la admisión de los hechos por parte de El Niño(a) no tendrá valor probatorio alguno.','221','Código de la Niñez y de la Adolescencia (Decreto 73-96), texto canónico v2 con las reformas del Decreto 35-2013 (La Gaceta 33,222)','{"texto_origen":"CANONICO_D3_FUENTES_MIXTAS","transcripcion_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","text_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","cotejado_por":"Abg. y Not. Fredy Omar Pinel Flores, propietario_despacho (CLO / Director Maya Lex), firma D3 del 2026-11-18 sobre la v2 de HN:CODIGO_NINEZ (ADJUDICACION_CLO_CODIGO_NINEZ.md §3)","manifiesto_sha256":"bd4d067d1ff2980db99a7527d21f9f381d996bb0a2d63933e30f7bcaecb2d372","pliego":"docs/corpus/staging/2026-11-04-hn-001-tranche-a-drive/canonico-v2/ADJUDICACION_CLO_CODIGO_NINEZ.md","procedencia":"Fuentes mixtas acreditadas por el pliego D1–D8 firmado (ver estado_canonico de cada fila); sin V4/V5 hasta el SQL de visibilidad","norm_id":"HN:CODIGO_NINEZ","instrumento_id":"CODIGO_NINEZ","ingest_batch":"A03_CODIGO_NINEZ_01","ordinal":234,"article_sha256":"a17d44c9c3aed06fab3d5f0fba36c3aa72d3ee391d467cc14b0ce6d285ff0383","vigencia":"UNKNOWN","revision_pendiente":true,"marcas":[],"estado_canonico":"TEXTO_V8_D3","fuente_canonica":"V8_LA_GACETA_33222"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_NINEZ','221','abddea6ffee6e01c56c9a3917388a22044f729752b18d08fdd6f5cbfaed479a2','A03_CODIGO_NINEZ_01',now()),
('A03_CODIGO_NINEZ_01:CODIGO_NINEZ:222','mayalex_normativos','10_LEYES_REGLAMENTOS','El Juez fijará el plazo de Suspensión del Proceso a Prueba, el cual no podrá ser inferior a seis (6) meses ni mayor a un (1) año, asimismo, determinará la imposición de una o varias reglas de cumplimiento, entre ellas las siguientes:

a) Residir en un lugar determinado; b) Frecuentar o dejar de frecuentar determinados lugares o personas; c) Abstenerse de consumir drogas, otros estupefacientes o bebidas alcohólicas; d) Participar en programas especiales para la prevención y tratamiento de adicciones; e) Comenzar o finalizar la escolaridad básica si no la ha cumplido, aprender una profesión u oficio o seguir cursos de capacitación en el lugar o la institución que determine el Juez; f) Prestar servicio social comunitario a favor del Estado o de instituciones públicas de servicio; g) Someterse a tratamiento médico o psicológico, de preferencia en instituciones públicas; h) Permanecer en un trabajo o empleo, o adquirir, en el plazo que el Juez determine, el entrenamiento en un oficio, industria o profesión, si no tiene medios propios de subsistencia; i) Someterse a la vigilancia que determine el Juez; j) No conducir vehículos automotores o de otra índole; k) Abstenerse de viajar al extranjero; y, I) Cumplir con los deberes de deudor alimentario.

Cuando se acredite plenamente que El Niño(a) no puede cumplir con alguna de las reglas anteriores, por ser contrarias a su salud, sus creencias religiosas o alguna otra causa de especial relevancia, el Juez podrá sustituirlas fundada y motivadamente, por el cumplimiento de otra u otras análogas que resulten razonables.

El Juez prevendrá a El Niño(a) sobre las reglas de conducta impuestas y las consecuencias de su inobservancia.

Contra la resolución que deniegue la Suspensión del Proceso a Prueba, procederá el recurso de Apelación. La resolución que admita esta figura, sólo será apelable, cuando las reglas fijadas resulten manifiestamente excesivas o que el Juez se haya excedido en sus facultades.

En ningún caso el Juez podrá imponer reglas más gravosas que las solicitadas por el Fiscal.','222','Código de la Niñez y de la Adolescencia (Decreto 73-96), texto canónico v2 con las reformas del Decreto 35-2013 (La Gaceta 33,222)','{"texto_origen":"CANONICO_D3_FUENTES_MIXTAS","transcripcion_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","text_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","cotejado_por":"Abg. y Not. Fredy Omar Pinel Flores, propietario_despacho (CLO / Director Maya Lex), firma D3 del 2026-11-18 sobre la v2 de HN:CODIGO_NINEZ (ADJUDICACION_CLO_CODIGO_NINEZ.md §3)","manifiesto_sha256":"bd4d067d1ff2980db99a7527d21f9f381d996bb0a2d63933e30f7bcaecb2d372","pliego":"docs/corpus/staging/2026-11-04-hn-001-tranche-a-drive/canonico-v2/ADJUDICACION_CLO_CODIGO_NINEZ.md","procedencia":"Fuentes mixtas acreditadas por el pliego D1–D8 firmado (ver estado_canonico de cada fila); sin V4/V5 hasta el SQL de visibilidad","norm_id":"HN:CODIGO_NINEZ","instrumento_id":"CODIGO_NINEZ","ingest_batch":"A03_CODIGO_NINEZ_01","ordinal":235,"article_sha256":"865c40c1ce7b5a7709f71766a53ca525f1e4eb8ae0e599c9e066a46354038ea3","vigencia":"UNKNOWN","revision_pendiente":true,"marcas":[],"estado_canonico":"TEXTO_V8_D3","fuente_canonica":"V8_LA_GACETA_33222"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_NINEZ','222','01374530b030c3470336a70d814bb451c1d7eb76645b26fbed8e2e90234b3434','A03_CODIGO_NINEZ_01',now()),
('A03_CODIGO_NINEZ_01:CODIGO_NINEZ:223','mayalex_normativos','10_LEYES_REGLAMENTOS','Ante el incumplimiento injustificado del plan de reparación o las reglas impuestas, de oficio o a petición de parte, el Juez llamará a una audiencia en la que se resolverá fundada y motivadamente sobre la revocación de la Suspensión del Proceso a Prueba.

Si mediara justificación válida, podrá reprogramar el plazo con la finalidad de asegurar el cumplimiento del término decretado, no obstante, esta no excederá los tres (3) meses adicionales, y solo podrá concederse por una vez.','223','Código de la Niñez y de la Adolescencia (Decreto 73-96), texto canónico v2 con las reformas del Decreto 35-2013 (La Gaceta 33,222)','{"texto_origen":"CANONICO_D3_FUENTES_MIXTAS","transcripcion_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","text_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","cotejado_por":"Abg. y Not. Fredy Omar Pinel Flores, propietario_despacho (CLO / Director Maya Lex), firma D3 del 2026-11-18 sobre la v2 de HN:CODIGO_NINEZ (ADJUDICACION_CLO_CODIGO_NINEZ.md §3)","manifiesto_sha256":"bd4d067d1ff2980db99a7527d21f9f381d996bb0a2d63933e30f7bcaecb2d372","pliego":"docs/corpus/staging/2026-11-04-hn-001-tranche-a-drive/canonico-v2/ADJUDICACION_CLO_CODIGO_NINEZ.md","procedencia":"Fuentes mixtas acreditadas por el pliego D1–D8 firmado (ver estado_canonico de cada fila); sin V4/V5 hasta el SQL de visibilidad","norm_id":"HN:CODIGO_NINEZ","instrumento_id":"CODIGO_NINEZ","ingest_batch":"A03_CODIGO_NINEZ_01","ordinal":236,"article_sha256":"2e4be41e7a977a913153fc3198097894bbcddcfdc8726e4932d54693ebf29e0c","vigencia":"UNKNOWN","revision_pendiente":true,"marcas":[],"estado_canonico":"TEXTO_V8_D3","fuente_canonica":"V8_LA_GACETA_33222"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_NINEZ','223','0184dbb7013a470b016e694c851dad924c7cf74cc303b982a6de4232d432d2a5','A03_CODIGO_NINEZ_01',now()),
('A03_CODIGO_NINEZ_01:CODIGO_NINEZ:224','mayalex_normativos','10_LEYES_REGLAMENTOS','En los asuntos suspendidos en virtud de las disposiciones correspondientes a esta Sección, el Fiscal tomará las medidas necesarias para evitar la pérdida, destrucción o ineficacia de los medios de prueba conocidos y las que soliciten las partes.','224','Código de la Niñez y de la Adolescencia (Decreto 73-96), texto canónico v2 con las reformas del Decreto 35-2013 (La Gaceta 33,222)','{"texto_origen":"CANONICO_D3_FUENTES_MIXTAS","transcripcion_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","text_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","cotejado_por":"Abg. y Not. Fredy Omar Pinel Flores, propietario_despacho (CLO / Director Maya Lex), firma D3 del 2026-11-18 sobre la v2 de HN:CODIGO_NINEZ (ADJUDICACION_CLO_CODIGO_NINEZ.md §3)","manifiesto_sha256":"bd4d067d1ff2980db99a7527d21f9f381d996bb0a2d63933e30f7bcaecb2d372","pliego":"docs/corpus/staging/2026-11-04-hn-001-tranche-a-drive/canonico-v2/ADJUDICACION_CLO_CODIGO_NINEZ.md","procedencia":"Fuentes mixtas acreditadas por el pliego D1–D8 firmado (ver estado_canonico de cada fila); sin V4/V5 hasta el SQL de visibilidad","norm_id":"HN:CODIGO_NINEZ","instrumento_id":"CODIGO_NINEZ","ingest_batch":"A03_CODIGO_NINEZ_01","ordinal":237,"article_sha256":"f392243028033b837f4557e2196200c125f2c6155ccb28136c4db6e97c67a497","vigencia":"UNKNOWN","revision_pendiente":true,"marcas":[],"estado_canonico":"TEXTO_V8_D3","fuente_canonica":"V8_LA_GACETA_33222"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_NINEZ','224','54a5bd2413f32f7c1034b11c0272a2aefd1fae22627951e70040b764c5b1c3be','A03_CODIGO_NINEZ_01',now()),
('A03_CODIGO_NINEZ_01:CODIGO_NINEZ:225','mayalex_normativos','10_LEYES_REGLAMENTOS','Los efectos de la Suspensión del Proceso a Prueba cesarán mientras El Niño(a) esté privado de su libertad por otro Proceso, pero si goza de libertad, el plazo seguirá su curso, no obstante no podrá decretarse la extinción de la acción penal sino cuando quede firme la resolución que lo exime de responsabilidad por el nuevo hecho.

La revocatoria de la Suspensión del Proceso a Prueba no impedirá el pronunciamiento de una sentencia absolutoria ni la concesión de algunas de las medidas sustitutivas a la privación de libertad, cuando fueren procedentes.','225','Código de la Niñez y de la Adolescencia (Decreto 73-96), texto canónico v2 con las reformas del Decreto 35-2013 (La Gaceta 33,222)','{"texto_origen":"CANONICO_D3_FUENTES_MIXTAS","transcripcion_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","text_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","cotejado_por":"Abg. y Not. Fredy Omar Pinel Flores, propietario_despacho (CLO / Director Maya Lex), firma D3 del 2026-11-18 sobre la v2 de HN:CODIGO_NINEZ (ADJUDICACION_CLO_CODIGO_NINEZ.md §3)","manifiesto_sha256":"bd4d067d1ff2980db99a7527d21f9f381d996bb0a2d63933e30f7bcaecb2d372","pliego":"docs/corpus/staging/2026-11-04-hn-001-tranche-a-drive/canonico-v2/ADJUDICACION_CLO_CODIGO_NINEZ.md","procedencia":"Fuentes mixtas acreditadas por el pliego D1–D8 firmado (ver estado_canonico de cada fila); sin V4/V5 hasta el SQL de visibilidad","norm_id":"HN:CODIGO_NINEZ","instrumento_id":"CODIGO_NINEZ","ingest_batch":"A03_CODIGO_NINEZ_01","ordinal":238,"article_sha256":"441f34e2f2f0c4c5a6bff32e00103f28bac5ec4979f7cc2ef2d823e135e6c810","vigencia":"UNKNOWN","revision_pendiente":true,"marcas":[],"estado_canonico":"TEXTO_V8_D3","fuente_canonica":"V8_LA_GACETA_33222"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_NINEZ','225','608cf5ee910dec33f98e4465dd6c4068876effe4ce468e9bdf8ffa7860402baf','A03_CODIGO_NINEZ_01',now()),
('A03_CODIGO_NINEZ_01:CODIGO_NINEZ:226','mayalex_normativos','10_LEYES_REGLAMENTOS','La Suspensión del Proceso a Prueba no extingue las acciones civiles de la víctima o de terceros. Sin embargo, si la víctima recibe pagos en virtud de la procedencia de la suspensión, ellos se destinarán a cuenta de la indemnización por daños y perjuicios que le pudiere corresponder.

Transcurrido el plazo que se fije sin que la suspensión fuere revocada y cumplido el plan de reparación, se extinguirá la acción penal y el Juez deberá dictar de oficio o a petición de parte, el sobreseimiento definitivo.

Durante el período de Suspensión del Proceso a Prueba de que tratan los artículos precedentes, quedará suspendida la prescripción de la acción penal.','226','Código de la Niñez y de la Adolescencia (Decreto 73-96), texto canónico v2 con las reformas del Decreto 35-2013 (La Gaceta 33,222)','{"texto_origen":"CANONICO_D3_FUENTES_MIXTAS","transcripcion_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","text_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","cotejado_por":"Abg. y Not. Fredy Omar Pinel Flores, propietario_despacho (CLO / Director Maya Lex), firma D3 del 2026-11-18 sobre la v2 de HN:CODIGO_NINEZ (ADJUDICACION_CLO_CODIGO_NINEZ.md §3)","manifiesto_sha256":"bd4d067d1ff2980db99a7527d21f9f381d996bb0a2d63933e30f7bcaecb2d372","pliego":"docs/corpus/staging/2026-11-04-hn-001-tranche-a-drive/canonico-v2/ADJUDICACION_CLO_CODIGO_NINEZ.md","procedencia":"Fuentes mixtas acreditadas por el pliego D1–D8 firmado (ver estado_canonico de cada fila); sin V4/V5 hasta el SQL de visibilidad","norm_id":"HN:CODIGO_NINEZ","instrumento_id":"CODIGO_NINEZ","ingest_batch":"A03_CODIGO_NINEZ_01","ordinal":239,"article_sha256":"62630020e5644e937f745e67242fd8e94ff4b50b36902e3a23f5788ff71b486c","vigencia":"UNKNOWN","revision_pendiente":true,"marcas":[],"estado_canonico":"TEXTO_V8_D3","fuente_canonica":"V8_LA_GACETA_33222"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_NINEZ','226','137f17369551f72b6b95b64d3d49bfb37061b7cb0f3cd3fbf8cd3d9912b4b9e4','A03_CODIGO_NINEZ_01',now()),
('A03_CODIGO_NINEZ_01:CODIGO_NINEZ:227','mayalex_normativos','10_LEYES_REGLAMENTOS','El Proceso Para la Niñez Infractora de Ley, estará compuesto por las fases siguientes:

a) Preparatoria; b) Intermedia; y, c) Juicio.

La Fase Preparatoria comprenderá los actos siguientes:

a) Denuncia; b) Investigación; c) Acusación; y, d) Vinculación al proceso.

La Fase Intermedia comprenderá los actos siguientes:

a) Interposición de incidentes, excepciones y nulidades; b) Formalización de la acusación y contestación de cargos; y, c) Auto de apertura a Debate.

La Fase de Juicio integra los actos siguientes:

a) Preparación del Debate; b) Audiencia de Debate; c) Individualización de la Sanción; y, d) Sentencia.','227','Código de la Niñez y de la Adolescencia (Decreto 73-96), texto canónico v2 con las reformas del Decreto 35-2013 (La Gaceta 33,222)','{"texto_origen":"CANONICO_D3_FUENTES_MIXTAS","transcripcion_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","text_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","cotejado_por":"Abg. y Not. Fredy Omar Pinel Flores, propietario_despacho (CLO / Director Maya Lex), firma D3 del 2026-11-18 sobre la v2 de HN:CODIGO_NINEZ (ADJUDICACION_CLO_CODIGO_NINEZ.md §3)","manifiesto_sha256":"bd4d067d1ff2980db99a7527d21f9f381d996bb0a2d63933e30f7bcaecb2d372","pliego":"docs/corpus/staging/2026-11-04-hn-001-tranche-a-drive/canonico-v2/ADJUDICACION_CLO_CODIGO_NINEZ.md","procedencia":"Fuentes mixtas acreditadas por el pliego D1–D8 firmado (ver estado_canonico de cada fila); sin V4/V5 hasta el SQL de visibilidad","norm_id":"HN:CODIGO_NINEZ","instrumento_id":"CODIGO_NINEZ","ingest_batch":"A03_CODIGO_NINEZ_01","ordinal":240,"article_sha256":"876a83c2f939931f88e56060717bb2e56f4116af4919ffeb850d2467a8798bbb","vigencia":"UNKNOWN","revision_pendiente":true,"marcas":[],"estado_canonico":"TEXTO_V8_D3","fuente_canonica":"V8_LA_GACETA_33222"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_NINEZ','227','5161c70a5bb9c9ebedd8dcb6ec953b5bb59eb8949fb2e960d3c513f9503d942f','A03_CODIGO_NINEZ_01',now()),
('A03_CODIGO_NINEZ_01:CODIGO_NINEZ:228','mayalex_normativos','10_LEYES_REGLAMENTOS','La Fase Preparatoria del Proceso Para la Niñez Infractora de Ley iniciará a través de la denuncia, siéndole aplicables las disposiciones conducentes del Código Procesal Penal.

De igual manera serán aplicables tales disposiciones, con respecto a la investigación de los Hechos Delictivos atribuidos a El Niño(a).

En ambos casos, siempre y cuando no contravengan los principios y derechos inherentes de esta materia.','228','Código de la Niñez y de la Adolescencia (Decreto 73-96), texto canónico v2 con las reformas del Decreto 35-2013 (La Gaceta 33,222)','{"texto_origen":"CANONICO_D3_FUENTES_MIXTAS","transcripcion_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","text_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","cotejado_por":"Abg. y Not. Fredy Omar Pinel Flores, propietario_despacho (CLO / Director Maya Lex), firma D3 del 2026-11-18 sobre la v2 de HN:CODIGO_NINEZ (ADJUDICACION_CLO_CODIGO_NINEZ.md §3)","manifiesto_sha256":"bd4d067d1ff2980db99a7527d21f9f381d996bb0a2d63933e30f7bcaecb2d372","pliego":"docs/corpus/staging/2026-11-04-hn-001-tranche-a-drive/canonico-v2/ADJUDICACION_CLO_CODIGO_NINEZ.md","procedencia":"Fuentes mixtas acreditadas por el pliego D1–D8 firmado (ver estado_canonico de cada fila); sin V4/V5 hasta el SQL de visibilidad","norm_id":"HN:CODIGO_NINEZ","instrumento_id":"CODIGO_NINEZ","ingest_batch":"A03_CODIGO_NINEZ_01","ordinal":241,"article_sha256":"61997f0f4f9c868b4b29004e0a95432a0a5881df4652646d6a49fffffe7c36b9","vigencia":"UNKNOWN","revision_pendiente":true,"marcas":[],"estado_canonico":"TEXTO_V8_D3","fuente_canonica":"V8_LA_GACETA_33222"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_NINEZ','228','59bd053a0164f213db00c4f3a0723b7a35d2c297ebebdbedbe96bf0dc6a9e92f','A03_CODIGO_NINEZ_01',now()),
('A03_CODIGO_NINEZ_01:CODIGO_NINEZ:229','mayalex_normativos','10_LEYES_REGLAMENTOS','Concluidas las investigaciones iniciales, el Ministerio Público podrá:

a) Ordenar el archivo del respectivo expediente; b) Formular por escrito al Juez, la solicitud para que le autorice la Suspensión del Proceso a Prueba; c) Solicitar sobreseimiento definitivo; o, d) Presentar la respectiva Acusación.

En el caso previsto en el inciso b) de este Artículo, el Juez resolverá sin más trámite la solicitud correspondiente.','229','Código de la Niñez y de la Adolescencia (Decreto 73-96), texto canónico v2 con las reformas del Decreto 35-2013 (La Gaceta 33,222)','{"texto_origen":"CANONICO_D3_FUENTES_MIXTAS","transcripcion_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","text_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","cotejado_por":"Abg. y Not. Fredy Omar Pinel Flores, propietario_despacho (CLO / Director Maya Lex), firma D3 del 2026-11-18 sobre la v2 de HN:CODIGO_NINEZ (ADJUDICACION_CLO_CODIGO_NINEZ.md §3)","manifiesto_sha256":"bd4d067d1ff2980db99a7527d21f9f381d996bb0a2d63933e30f7bcaecb2d372","pliego":"docs/corpus/staging/2026-11-04-hn-001-tranche-a-drive/canonico-v2/ADJUDICACION_CLO_CODIGO_NINEZ.md","procedencia":"Fuentes mixtas acreditadas por el pliego D1–D8 firmado (ver estado_canonico de cada fila); sin V4/V5 hasta el SQL de visibilidad","norm_id":"HN:CODIGO_NINEZ","instrumento_id":"CODIGO_NINEZ","ingest_batch":"A03_CODIGO_NINEZ_01","ordinal":242,"article_sha256":"9a31e31f2ed15a72f3ac097fce240d3e1929dfc8bcb5aca92baf054eca48fb1b","vigencia":"UNKNOWN","revision_pendiente":true,"marcas":[],"estado_canonico":"TEXTO_V8_D3","fuente_canonica":"V8_LA_GACETA_33222"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_NINEZ','229','b50a3a5ee8f2c91033012d83b9edc69f1e458fc631ccf23fd0003376774b07f2','A03_CODIGO_NINEZ_01',now()),
('A03_CODIGO_NINEZ_01:CODIGO_NINEZ:230','mayalex_normativos','10_LEYES_REGLAMENTOS','En caso que el Ministerio Público decida presentar Acusación, si El Niño(a) se encuentra detenido por flagrancia será puesto a la orden del Juez competente dentro de las veinticuatro (24) horas siguientes a su detención; en caso de ser detenido por orden de captura emitida por autoridad judicial deberá ser puesto inmediatamente a la orden del Juez de la Niñez o el que haga sus veces.

Una vez que El Niño(a) se encuentre a disposición del Juez competente, inmediatamente se celebrará audiencia de vinculación al proceso, en la que el Ministerio Público formulará su acusación, solicitará su vinculación a proceso o la solicitud de aplicación de las medidas de simplificación en su caso y las Medidas Cautelares que considere procedentes. Asimismo de ser menor de doce (12) años actuará de conformidad a Ley.

El Ministerio Publico en esta audiencia deberá acreditar mínimamente, la existencia del Hecho Delictivo y de la probable participación de El Niño(a) en éste.

En la misma audiencia, si El Niño(a) desea hacerlo, se le recibirá su declaración inicial.

Esta audiencia se realizará con la presencia de El Niño(a) su Defensor, el Fiscal y el acusador privado, la ausencia de este último no impedirá la realización de esta audiencia.

Con anterioridad a la audiencia o durante el transcurso de ella, El Niño(a) o su defensor podrán solicitar la suspensión de la audiencia de vinculación, por un plazo de hasta setenta y dos (72) horas para aportar elementos de convicción antes de que se resuelva su situación jurídica o se pronuncie el Juez sobre la Medida Cautelar.

La prolongación de la detención en su perjuicio será sancionada por la ley Penal.

Finalizada la intervención de las partes y con base en los elementos de prueba desarrollados, de inmediato el Juez resolverá, dictando:

a) Sobreseimiento provisional; b) Sobreseimiento definitivo; c) Con lugar la vinculación al Proceso; o d) La imposición o no de las Medidas Cautelares procedentes.

En el caso del literal a) el plazo para que el Ministerio Público pueda promover la persecución del Proceso será de dos (2) años seis (6) meses.

Resuelta la vinculación al Proceso, el Juez ordenará la celebración de la Audiencia Intermedia, fijando su fecha en un plazo no mayor a treinta (30) días, quedando al efecto, las partes debidamente citadas.

No obstante, en los casos complejos, a petición del Ministerio Público ese plazo podrá prorrogarse hasta treinta (30) días adicionales, por una sola vez. Se entenderán por casos complejos aquéllos que involucren: múltiples hechos, imputados o víctimas y los que en cuanto a las investigaciones "requieran el cumplimiento de actuaciones en el exterior o la producción de prueba de difícil realización. En este último caso, el Fiscal deberá detallarlas diligencias de investigación pendientes de finalizar, a efecto que el Juez valore el tiempo necesario de la prórroga, el que en ningún caso excederá el tiempo máximo establecido.

Si considera que la Vinculación al Proceso es improcedente, ordenará de inmediato la libertad de El Niño(a).','230','Código de la Niñez y de la Adolescencia (Decreto 73-96), texto canónico v2 con las reformas del Decreto 35-2013 (La Gaceta 33,222)','{"texto_origen":"CANONICO_D3_FUENTES_MIXTAS","transcripcion_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","text_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","cotejado_por":"Abg. y Not. Fredy Omar Pinel Flores, propietario_despacho (CLO / Director Maya Lex), firma D3 del 2026-11-18 sobre la v2 de HN:CODIGO_NINEZ (ADJUDICACION_CLO_CODIGO_NINEZ.md §3)","manifiesto_sha256":"bd4d067d1ff2980db99a7527d21f9f381d996bb0a2d63933e30f7bcaecb2d372","pliego":"docs/corpus/staging/2026-11-04-hn-001-tranche-a-drive/canonico-v2/ADJUDICACION_CLO_CODIGO_NINEZ.md","procedencia":"Fuentes mixtas acreditadas por el pliego D1–D8 firmado (ver estado_canonico de cada fila); sin V4/V5 hasta el SQL de visibilidad","norm_id":"HN:CODIGO_NINEZ","instrumento_id":"CODIGO_NINEZ","ingest_batch":"A03_CODIGO_NINEZ_01","ordinal":243,"article_sha256":"6ad3a760569f8107df0f101bf821853b0c5cedfdca1fd52a29ae1fc2451d97d6","vigencia":"UNKNOWN","revision_pendiente":true,"marcas":[],"estado_canonico":"TEXTO_V8_D3","fuente_canonica":"V8_LA_GACETA_33222"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_NINEZ','230','253bef0d55661b3325d244894666c4170a71d8ced960c78383c7b36ad2650457','A03_CODIGO_NINEZ_01',now()),
('A03_CODIGO_NINEZ_01:CODIGO_NINEZ:231','mayalex_normativos','10_LEYES_REGLAMENTOS','Los Procesos contra Niños(as) son de alta prioridad y especial interés público, con plena salvaguarda del derecho que tienen a ser escuchados. Bajo pena de nulidad, su declaración debe ser rendida conforme a las reglas siguientes:

a) Únicamente ante Juez competente; b) Voluntariamente, de manera que sólo se puede tomar, cuando lo haya consultado con su Defensor; c) Asistida, de modo que se realice con la asistencia de su Defensor; d) Se dará prioridad a la declaración, procurando que el tiempo entre la presentación y la declaración sea el menor posible; e) Será breve, de modo que la comparecencia ante el Juez tome estrictamente el tiempo requerido, considerando inclusive períodos de descanso para El Niño(a);

f) Será eficiente, por lo que la autoridad tendrá que preparar la comparecencia con antelación a fin de obtener la información que requiera para el ejercicio de sus funciones, en el menor número de sesiones que sea posible; y, g) Se evacuará en presencia de sus padres, responsables o funcionarios competentes del Instituto Hondureño de la Niñez y la Familia (IHNFA), a cargo de la protección a los niños y niñas, siempre que éste o su defensor lo soliciten y el Juez lo estime conveniente.

Las mismas reglas se observarán, en lo aplicable, en las entrevistas que voluntariamente tenga un Niño(a), con el Ministerio Público.','231','Código de la Niñez y de la Adolescencia (Decreto 73-96), texto canónico v2 con las reformas del Decreto 35-2013 (La Gaceta 33,222)','{"texto_origen":"CANONICO_D3_FUENTES_MIXTAS","transcripcion_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","text_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","cotejado_por":"Abg. y Not. Fredy Omar Pinel Flores, propietario_despacho (CLO / Director Maya Lex), firma D3 del 2026-11-18 sobre la v2 de HN:CODIGO_NINEZ (ADJUDICACION_CLO_CODIGO_NINEZ.md §3)","manifiesto_sha256":"bd4d067d1ff2980db99a7527d21f9f381d996bb0a2d63933e30f7bcaecb2d372","pliego":"docs/corpus/staging/2026-11-04-hn-001-tranche-a-drive/canonico-v2/ADJUDICACION_CLO_CODIGO_NINEZ.md","procedencia":"Fuentes mixtas acreditadas por el pliego D1–D8 firmado (ver estado_canonico de cada fila); sin V4/V5 hasta el SQL de visibilidad","norm_id":"HN:CODIGO_NINEZ","instrumento_id":"CODIGO_NINEZ","ingest_batch":"A03_CODIGO_NINEZ_01","ordinal":244,"article_sha256":"3f17a41f40a04b9ac1da8cfd06b92eca1ddd2d4b6087c1444b9aae1bee70b320","vigencia":"UNKNOWN","revision_pendiente":true,"marcas":[],"estado_canonico":"TEXTO_V8_D3","fuente_canonica":"V8_LA_GACETA_33222"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_NINEZ','231','2ac7faf9de664e4018ec66e51cb954dbd0cf2ad0c358fd1cc98eef7038bb6e4f','A03_CODIGO_NINEZ_01',now()),
('A03_CODIGO_NINEZ_01:CODIGO_NINEZ:232','mayalex_normativos','10_LEYES_REGLAMENTOS','La Fase Intermedia se desarrollará en una audiencia a celebrarse el día y hora señalados, la cual comprenderá los actos siguientes:

a) Interposición de incidentes, excepciones y nulidades; b) Solicitud de sobreseimiento provisional o definitivo; c) Formalización de la acusación y contestación de cargos; y d) Auto de apertura a debate.

La acusación deberá contener: a) Una breve y precisa relación de los Hechos Delictivos imputados; b) La calificación legal de los hechos, conforme lo dispuesto en la Ley; c) El grado de participación que supuestamente tuvo El Niño(a); y, d) La Sanción que considera debe aplicarse.

En caso de duda, la calificación podrá recaer alternativamente sobre tipos delictivos que se excluyan entre sí.','232','Código de la Niñez y de la Adolescencia (Decreto 73-96), texto canónico v2 con las reformas del Decreto 35-2013 (La Gaceta 33,222)','{"texto_origen":"CANONICO_D3_FUENTES_MIXTAS","transcripcion_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","text_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","cotejado_por":"Abg. y Not. Fredy Omar Pinel Flores, propietario_despacho (CLO / Director Maya Lex), firma D3 del 2026-11-18 sobre la v2 de HN:CODIGO_NINEZ (ADJUDICACION_CLO_CODIGO_NINEZ.md §3)","manifiesto_sha256":"bd4d067d1ff2980db99a7527d21f9f381d996bb0a2d63933e30f7bcaecb2d372","pliego":"docs/corpus/staging/2026-11-04-hn-001-tranche-a-drive/canonico-v2/ADJUDICACION_CLO_CODIGO_NINEZ.md","procedencia":"Fuentes mixtas acreditadas por el pliego D1–D8 firmado (ver estado_canonico de cada fila); sin V4/V5 hasta el SQL de visibilidad","norm_id":"HN:CODIGO_NINEZ","instrumento_id":"CODIGO_NINEZ","ingest_batch":"A03_CODIGO_NINEZ_01","ordinal":245,"article_sha256":"cc8cb82961ed5de2f415220566ac5338aa14c0cc7f14c92fb0f2c5a192870ad2","vigencia":"UNKNOWN","revision_pendiente":true,"marcas":[],"estado_canonico":"TEXTO_V8_D3","fuente_canonica":"V8_LA_GACETA_33222"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_NINEZ','232','f71cf71d48af385a71da715869a07596d4b69b4de4158cef2f7c09578239ad4d','A03_CODIGO_NINEZ_01',now()),
('A03_CODIGO_NINEZ_01:CODIGO_NINEZ:233','mayalex_normativos','10_LEYES_REGLAMENTOS','El Juez notificará, a las partes su resolución sobre los puntos planteados, en audiencia que se celebrará dentro de los tres (3) días siguientes a la Audiencia Intermedia.

De resultar procedente la acusación, dictará Auto de Apertura a Juicio, caso contrario dictará sobreseimiento provisional o definitivo, según sea el caso, de conformidad con las reglas establecidas en el Código Procesal Penal.

De decretarse el Auto de Apertura, dentro de las veinticuatro (24) horas siguientes, el Juez ordenará la remisión de las diligencias al Juez que deba conocer la Fase de Juicio.','233','Código de la Niñez y de la Adolescencia (Decreto 73-96), texto canónico v2 con las reformas del Decreto 35-2013 (La Gaceta 33,222)','{"texto_origen":"CANONICO_D3_FUENTES_MIXTAS","transcripcion_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","text_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","cotejado_por":"Abg. y Not. Fredy Omar Pinel Flores, propietario_despacho (CLO / Director Maya Lex), firma D3 del 2026-11-18 sobre la v2 de HN:CODIGO_NINEZ (ADJUDICACION_CLO_CODIGO_NINEZ.md §3)","manifiesto_sha256":"bd4d067d1ff2980db99a7527d21f9f381d996bb0a2d63933e30f7bcaecb2d372","pliego":"docs/corpus/staging/2026-11-04-hn-001-tranche-a-drive/canonico-v2/ADJUDICACION_CLO_CODIGO_NINEZ.md","procedencia":"Fuentes mixtas acreditadas por el pliego D1–D8 firmado (ver estado_canonico de cada fila); sin V4/V5 hasta el SQL de visibilidad","norm_id":"HN:CODIGO_NINEZ","instrumento_id":"CODIGO_NINEZ","ingest_batch":"A03_CODIGO_NINEZ_01","ordinal":246,"article_sha256":"08f9ce7f434a8ff9dc13768c9ca0e0f7603aa3cc2f2da01311a663decd4121dc","vigencia":"UNKNOWN","revision_pendiente":true,"marcas":[],"estado_canonico":"TEXTO_V8_D3","fuente_canonica":"V8_LA_GACETA_33222"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_NINEZ','233','f8403596746ab9cef5ad9e9bc6e21762b101d46655081691801726703c9db329','A03_CODIGO_NINEZ_01',now()),
('A03_CODIGO_NINEZ_01:CODIGO_NINEZ:234','mayalex_normativos','10_LEYES_REGLAMENTOS','La Fase de Juicio integra los actos siguientes:

a) Preparación del Debate; b) Audiencia de Debate; c) Individualización de la Sanción; y, d) Sentencia.','234','Código de la Niñez y de la Adolescencia (Decreto 73-96), texto canónico v2 con las reformas del Decreto 35-2013 (La Gaceta 33,222)','{"texto_origen":"CANONICO_D3_FUENTES_MIXTAS","transcripcion_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","text_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","cotejado_por":"Abg. y Not. Fredy Omar Pinel Flores, propietario_despacho (CLO / Director Maya Lex), firma D3 del 2026-11-18 sobre la v2 de HN:CODIGO_NINEZ (ADJUDICACION_CLO_CODIGO_NINEZ.md §3)","manifiesto_sha256":"bd4d067d1ff2980db99a7527d21f9f381d996bb0a2d63933e30f7bcaecb2d372","pliego":"docs/corpus/staging/2026-11-04-hn-001-tranche-a-drive/canonico-v2/ADJUDICACION_CLO_CODIGO_NINEZ.md","procedencia":"Fuentes mixtas acreditadas por el pliego D1–D8 firmado (ver estado_canonico de cada fila); sin V4/V5 hasta el SQL de visibilidad","norm_id":"HN:CODIGO_NINEZ","instrumento_id":"CODIGO_NINEZ","ingest_batch":"A03_CODIGO_NINEZ_01","ordinal":247,"article_sha256":"a5f25f9571a1a60f2f38804367aa919399c7595103faf11a9c811d7dbbc8295d","vigencia":"UNKNOWN","revision_pendiente":true,"marcas":[],"estado_canonico":"TEXTO_V8_D3","fuente_canonica":"V8_LA_GACETA_33222"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_NINEZ','234','675eb3b36079f8d50a2a90e36ffe4cf67491cd38f1e4707939434306789d8d71','A03_CODIGO_NINEZ_01',now()),
('A03_CODIGO_NINEZ_01:CODIGO_NINEZ:235','mayalex_normativos','10_LEYES_REGLAMENTOS','Recibidas las diligencias, el Juez de Juicio señalará audiencia de proposición de prueba, dentro de los cinco (5) días siguientes, citando a las partes para tal efecto. Los medios de prueba serán propuestos con indicación de los hechos o circunstancias que se pretenda probar.

En esta audiencia, las partes presentarán la lista de los testigos y peritos con indicación de sus nombres y apellidos, profesión u oficio y dirección exacta, señalando los hechos sobre los cuales deberán ser examinados durante el debate.

Asimismo propondrán los documentos y demás medios con los que pretenda probar las pretensiones deducidas en el Juicio y señalarán en su caso, el lugar en que se encuentran.

Propuestas las pruebas y oídas las alegaciones que al respecto hagan las partes, el Juez resolverá mediante auto motivado sobre su admisión, en la misma audiencia o en el plazo de los tres (3) días.

Solamente podrán ser rechazados los medios de prueba manifiestamente impertinentes, inútiles o desproporcionados en relación con la finalidad probatoria que se pretende, así como los meramente dilatorios o, cuando se trate de prueba ilícita.

En el acto que notifique la resolución, el Juez señalará fecha y hora para la Audiencia de Debate, la que tendrá lugar dentro de los quince (15) días siguientes a la misma.','235','Código de la Niñez y de la Adolescencia (Decreto 73-96), texto canónico v2 con las reformas del Decreto 35-2013 (La Gaceta 33,222)','{"texto_origen":"CANONICO_D3_FUENTES_MIXTAS","transcripcion_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","text_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","cotejado_por":"Abg. y Not. Fredy Omar Pinel Flores, propietario_despacho (CLO / Director Maya Lex), firma D3 del 2026-11-18 sobre la v2 de HN:CODIGO_NINEZ (ADJUDICACION_CLO_CODIGO_NINEZ.md §3)","manifiesto_sha256":"bd4d067d1ff2980db99a7527d21f9f381d996bb0a2d63933e30f7bcaecb2d372","pliego":"docs/corpus/staging/2026-11-04-hn-001-tranche-a-drive/canonico-v2/ADJUDICACION_CLO_CODIGO_NINEZ.md","procedencia":"Fuentes mixtas acreditadas por el pliego D1–D8 firmado (ver estado_canonico de cada fila); sin V4/V5 hasta el SQL de visibilidad","norm_id":"HN:CODIGO_NINEZ","instrumento_id":"CODIGO_NINEZ","ingest_batch":"A03_CODIGO_NINEZ_01","ordinal":248,"article_sha256":"8ef6ca8c56383e7a05368dd215c2acf191c0bffe583ba8b7287e40ebde8d6f7f","vigencia":"UNKNOWN","revision_pendiente":true,"marcas":[],"estado_canonico":"TEXTO_V8_D3","fuente_canonica":"V8_LA_GACETA_33222"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_NINEZ','235','1488f621b3766f2dcb6539b9595739cbcf27bd853705497bac23beb8ec0f3b85','A03_CODIGO_NINEZ_01',now()),
('A03_CODIGO_NINEZ_01:CODIGO_NINEZ:236','mayalex_normativos','10_LEYES_REGLAMENTOS','Sin perjuicio de lo previsto en este Título, la Audiencia de Debate se regirá por lo prescrito por los artículos 319a 346 del Código Procesal Penal, excepto los artículos 335,336 y 338 del mismo.

La Audiencia de Debate no puede suspenderse por más de diez (10) días, debiendo procederse conforme lo dispuesto en el Artículo 312 del Código Procesal Penal.

Concluidos los alegatos finales y consultado El Niño(a) sobre si desea agregar algo más o no, el Juez se retirará a fin de realizar los análisis y valoraciones que considere necesarios para dictar la Sentencia conforme a Derecho.

La audiencia se reanudará para notificar a las partes la resolución respectiva, el Juez explicará en forma clara y sencilla los razonamientos de su decisión.

En caso que El Niño(a) sea declarado absuelto, el Juez ordenará dejar sin efecto la Medida Cautelar impuesta, una vez firme la Sentencia.

Si fuere declarado culpable, inmediatamente el Juez cederá la palabra a las partes, para ofrecer prueba sobre la individualización de la Sanción a imponer, conforme a las reglas aplicables a la Audiencia de Debate.

La Sentencia deberá fundamentarse en las pruebas evacuadas, pero teniendo siempre en consideración el medio social y las condiciones en que se ha desarrollado la vida de El Niño(a) y las circunstancias en que se cometió el Hecho Delictivo. Esta se notificará personalmente a las partes en la audiencia en que se dicte.

Posteriormente a la reproducción de la prueba admitida para la individualización de la Sanción, el Juez señalará día y hora para audiencia de lectura de Sentencia, la que se efectuará en un plazo no mayor de cinco (5) días.','236','Código de la Niñez y de la Adolescencia (Decreto 73-96), texto canónico v2 con las reformas del Decreto 35-2013 (La Gaceta 33,222)','{"texto_origen":"CANONICO_D3_FUENTES_MIXTAS","transcripcion_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","text_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","cotejado_por":"Abg. y Not. Fredy Omar Pinel Flores, propietario_despacho (CLO / Director Maya Lex), firma D3 del 2026-11-18 sobre la v2 de HN:CODIGO_NINEZ (ADJUDICACION_CLO_CODIGO_NINEZ.md §3)","manifiesto_sha256":"bd4d067d1ff2980db99a7527d21f9f381d996bb0a2d63933e30f7bcaecb2d372","pliego":"docs/corpus/staging/2026-11-04-hn-001-tranche-a-drive/canonico-v2/ADJUDICACION_CLO_CODIGO_NINEZ.md","procedencia":"Fuentes mixtas acreditadas por el pliego D1–D8 firmado (ver estado_canonico de cada fila); sin V4/V5 hasta el SQL de visibilidad","norm_id":"HN:CODIGO_NINEZ","instrumento_id":"CODIGO_NINEZ","ingest_batch":"A03_CODIGO_NINEZ_01","ordinal":249,"article_sha256":"f1a8da36b18d55c53eb0d1e2a8b6cd213bb712d7fc3f542d9d352578f37a576d","vigencia":"UNKNOWN","revision_pendiente":true,"marcas":[],"estado_canonico":"TEXTO_V8_D3","fuente_canonica":"V8_LA_GACETA_33222"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_NINEZ','236','fa0e41a4bddaae8e482739aeb1a123d35a5821f1262883687e753ac1d7878670','A03_CODIGO_NINEZ_01',now()),
('A03_CODIGO_NINEZ_01:CODIGO_NINEZ:237','mayalex_normativos','10_LEYES_REGLAMENTOS','Para la determinación de la Sanción y a fin de lograr su mejor individualización, el Juez debe considerar:

a) La proporcionalidad con el hecho, las circunstancias de El Niño(a) y la gravedad de la conducta realizada; b) Los Principios Rectores y fines establecidos en este Título; c) La edad del Sancionado y sus circunstancias personales, familiares, sociales y culturales; d) El grado de participación en el hecho; e) Las características del caso concreto, su gravedad y las circunstancias en que se hubiese cometido.

tomando especialmente en cuenta aquellas que atenúen la responsabilidad; f) La posibilidad de cumplimiento de la Sanción;

g) El daño causado y los esfuerzos de El Niño(a) por repararlo; y, h) Cualquier otro supuesto que establezca este Título.

En la Sentencia, el Juez podrá imponer la amonestación y hasta un máximo de dos (2) sanciones más, compatibles entre sí, de modo que su Ejecución pueda ser simultánea y sucesiva, de ser el caso.','237','Código de la Niñez y de la Adolescencia (Decreto 73-96), texto canónico v2 con las reformas del Decreto 35-2013 (La Gaceta 33,222)','{"texto_origen":"CANONICO_D3_FUENTES_MIXTAS","transcripcion_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","text_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","cotejado_por":"Abg. y Not. Fredy Omar Pinel Flores, propietario_despacho (CLO / Director Maya Lex), firma D3 del 2026-11-18 sobre la v2 de HN:CODIGO_NINEZ (ADJUDICACION_CLO_CODIGO_NINEZ.md §3)","manifiesto_sha256":"bd4d067d1ff2980db99a7527d21f9f381d996bb0a2d63933e30f7bcaecb2d372","pliego":"docs/corpus/staging/2026-11-04-hn-001-tranche-a-drive/canonico-v2/ADJUDICACION_CLO_CODIGO_NINEZ.md","procedencia":"Fuentes mixtas acreditadas por el pliego D1–D8 firmado (ver estado_canonico de cada fila); sin V4/V5 hasta el SQL de visibilidad","norm_id":"HN:CODIGO_NINEZ","instrumento_id":"CODIGO_NINEZ","ingest_batch":"A03_CODIGO_NINEZ_01","ordinal":250,"article_sha256":"bfe2104b570df63cf358d576447f6ca8e4ae720fb19c0251aa94491b4bae1873","vigencia":"UNKNOWN","revision_pendiente":true,"marcas":[],"estado_canonico":"TEXTO_V8_D3","fuente_canonica":"V8_LA_GACETA_33222"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_NINEZ','237','1f0f95bc8b70bcef930bdc5c88e5190c4cc973b48946b9b19ef7e052f71f9ec3','A03_CODIGO_NINEZ_01',now())
