INSERT INTO public.biblioteca_vectores (id,coleccion,materia,contenido,num_articulo,fuente,metadata,embedding,jurisdiccion,fuente_tipo,es_norma_vigente,revision_pendiente,instrumento_id,num_articulo_norm,hash_contenido,ingest_batch,ingested_at) VALUES
('A03_CODIGO_NINEZ_01:CODIGO_NINEZ:238','mayalex_normativos','10_LEYES_REGLAMENTOS','En la Audiencia de Lectura de Sentencia estarán presentes las partes, El Niño(a), sus representantes legales o en su caso, el representante del Instituto Hondureño de la Niñez y la Familia (IHNFA).

En esta audiencia, el Juez explicará con especial atención al Sancionado, las motivaciones de la imposición, las características generales de la Ejecución y las consecuencias de su incumplimiento.

La Sentencia será dictada en nombre del Estado de Honduras y deberá contener los requisitos siguientes:

a) El nombre y la ubicación del Juzgado de Letras de la Niñez o el que haga sus veces que dicte la resolución y la fecha de la misma; b) Nombre de las partes intervinientes; c) Los datos personales de El Niño (a) y cualquier otro dato de identificación relevante; d) El razonamiento y la decisión del Juez sobre cada una de las cuestiones planteadas durante el juicio, con exposición expresa de los motivos de hecho y de derecho en que se basa; e) La determinación precisa del hecho o hechos que el Juez tenga por probado; f) En su caso, deberá determinarse en forma clara, precisa y fundamentada la Sanción impuesta y su duración; S) El lugar de Ejecución de la Sanción, debiendo notificar al ente estatal encargado para ejecutar la o las mismas; h) El destino de las piezas de convicción, instrumentos y efectos del Hecho Delictivo; e, i) La firma del Juez y el Secretario.','238','Código de la Niñez y de la Adolescencia (Decreto 73-96), texto canónico v2 con las reformas del Decreto 35-2013 (La Gaceta 33,222)','{"texto_origen":"CANONICO_D3_FUENTES_MIXTAS","transcripcion_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","text_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","cotejado_por":"Abg. y Not. Fredy Omar Pinel Flores, propietario_despacho (CLO / Director Maya Lex), firma D3 del 2026-11-18 sobre la v2 de HN:CODIGO_NINEZ (ADJUDICACION_CLO_CODIGO_NINEZ.md §3)","manifiesto_sha256":"bd4d067d1ff2980db99a7527d21f9f381d996bb0a2d63933e30f7bcaecb2d372","pliego":"docs/corpus/staging/2026-11-04-hn-001-tranche-a-drive/canonico-v2/ADJUDICACION_CLO_CODIGO_NINEZ.md","procedencia":"Fuentes mixtas acreditadas por el pliego D1–D8 firmado (ver estado_canonico de cada fila); sin V4/V5 hasta el SQL de visibilidad","norm_id":"HN:CODIGO_NINEZ","instrumento_id":"CODIGO_NINEZ","ingest_batch":"A03_CODIGO_NINEZ_01","ordinal":251,"article_sha256":"287148501355042d265124be7be803d477e48ece58cc1108a34964cf12e2473e","vigencia":"UNKNOWN","revision_pendiente":true,"marcas":[],"estado_canonico":"TEXTO_V8_D3","fuente_canonica":"V8_LA_GACETA_33222"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_NINEZ','238','acd80e7009c9020f4ec5d9a8235c0ab7503282bb5178c1465be7c0199c1ce420','A03_CODIGO_NINEZ_01',now()),
('A03_CODIGO_NINEZ_01:CODIGO_NINEZ:239','mayalex_normativos','10_LEYES_REGLAMENTOS','En caso que se recurra la Sentencia Condenatoria, El Niño(a) continuará sometido a las Medidas Cautelares que establezca el Juez.

Firme la Sentencia condenatoria, el Juez establecerá las condiciones y la forma en que debe cumplirla. Así mismo el Instituto Hondureño de la Niñez y la Familia (IHNFA), formulará el Plan de Atención Individual para la ejecución de la Sanción, el que estará supeditado a la aprobación del Juez de Ejecución.','239','Código de la Niñez y de la Adolescencia (Decreto 73-96), texto canónico v2 con las reformas del Decreto 35-2013 (La Gaceta 33,222)','{"texto_origen":"CANONICO_D3_FUENTES_MIXTAS","transcripcion_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","text_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","cotejado_por":"Abg. y Not. Fredy Omar Pinel Flores, propietario_despacho (CLO / Director Maya Lex), firma D3 del 2026-11-18 sobre la v2 de HN:CODIGO_NINEZ (ADJUDICACION_CLO_CODIGO_NINEZ.md §3)","manifiesto_sha256":"bd4d067d1ff2980db99a7527d21f9f381d996bb0a2d63933e30f7bcaecb2d372","pliego":"docs/corpus/staging/2026-11-04-hn-001-tranche-a-drive/canonico-v2/ADJUDICACION_CLO_CODIGO_NINEZ.md","procedencia":"Fuentes mixtas acreditadas por el pliego D1–D8 firmado (ver estado_canonico de cada fila); sin V4/V5 hasta el SQL de visibilidad","norm_id":"HN:CODIGO_NINEZ","instrumento_id":"CODIGO_NINEZ","ingest_batch":"A03_CODIGO_NINEZ_01","ordinal":252,"article_sha256":"298d29c329d715df3607b3a04c87a8f96aa79ac2b6715eac15edaa7b2b17cc81","vigencia":"UNKNOWN","revision_pendiente":true,"marcas":[],"estado_canonico":"TEXTO_V8_D3","fuente_canonica":"V8_LA_GACETA_33222"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_NINEZ','239','a23b61026e139f3a3df0f8b616d87384f4e8fb6fd08be70691f5576f690dbd19','A03_CODIGO_NINEZ_01',now()),
('A03_CODIGO_NINEZ_01:CODIGO_NINEZ:240','mayalex_normativos','10_LEYES_REGLAMENTOS','En el caso de Faltas, si no fuere aplicable el Criterio de Oportunidad, el Juez competente señalará audiencia reservada dentro de los cinco (5) días siguientes a la presentación de la Acusación, en la cual oirá a El Niño(a), si su madurez lo hace aconsejable, y al ofendido, recibiendo la prueba que se presente.

Concluida la audiencia, dictará resolución absolviéndole o imponiéndole lo procedente.

Teniendo en cuenta su gravedad, las Faltas se sancionarán con:

a) Amonestación verbal o escrita; b) La imposición de órdenes de orientación y supervisión, cuya duración máxima será de treinta (30) días; o, c) La obligación de reparar el daño.','240','Código de la Niñez y de la Adolescencia (Decreto 73-96), texto canónico v2 con las reformas del Decreto 35-2013 (La Gaceta 33,222)','{"texto_origen":"CANONICO_D3_FUENTES_MIXTAS","transcripcion_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","text_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","cotejado_por":"Abg. y Not. Fredy Omar Pinel Flores, propietario_despacho (CLO / Director Maya Lex), firma D3 del 2026-11-18 sobre la v2 de HN:CODIGO_NINEZ (ADJUDICACION_CLO_CODIGO_NINEZ.md §3)","manifiesto_sha256":"bd4d067d1ff2980db99a7527d21f9f381d996bb0a2d63933e30f7bcaecb2d372","pliego":"docs/corpus/staging/2026-11-04-hn-001-tranche-a-drive/canonico-v2/ADJUDICACION_CLO_CODIGO_NINEZ.md","procedencia":"Fuentes mixtas acreditadas por el pliego D1–D8 firmado (ver estado_canonico de cada fila); sin V4/V5 hasta el SQL de visibilidad","norm_id":"HN:CODIGO_NINEZ","instrumento_id":"CODIGO_NINEZ","ingest_batch":"A03_CODIGO_NINEZ_01","ordinal":253,"article_sha256":"65367c84655545e80eaee293963f3d735fdbdc08a2ca76a1da52d2a7f8eea2d1","vigencia":"UNKNOWN","revision_pendiente":true,"marcas":[],"estado_canonico":"TEXTO_V8_D3","fuente_canonica":"V8_LA_GACETA_33222"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_NINEZ','240','cffd4a9a6d359ef200e48504187188407720fc06d59727728b8b2e64e2950a2f','A03_CODIGO_NINEZ_01',now()),
('A03_CODIGO_NINEZ_01:CODIGO_NINEZ:241','mayalex_normativos','10_LEYES_REGLAMENTOS','Las partes podrán recurrir las resoluciones del Juzgado de Letras de la Niñez o quien haga sus veces, mediante los recursos y trámites establecidos en el Código Procesal Penal, salvo las disposiciones especiales establecidas en este Título.

Cuando proceda, en aras de la justicia, el Ministerio Público podrá presentar impugnación a favor de El Niño(a).

Contra las sentencias definitivas pronunciadas por el Juez de Letras de la Niñez o el que haga sus veces podrá interponerse el Recurso de Casación.

En la tramitación de los recursos, se observará irrestrictamente lo establecido en el Artículo 10 de este Código, so pena de incurrir en la responsabilidad prevista en la Ley.','241','Código de la Niñez y de la Adolescencia (Decreto 73-96), texto canónico v2 con las reformas del Decreto 35-2013 (La Gaceta 33,222)','{"texto_origen":"CANONICO_D3_FUENTES_MIXTAS","transcripcion_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","text_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","cotejado_por":"Abg. y Not. Fredy Omar Pinel Flores, propietario_despacho (CLO / Director Maya Lex), firma D3 del 2026-11-18 sobre la v2 de HN:CODIGO_NINEZ (ADJUDICACION_CLO_CODIGO_NINEZ.md §3)","manifiesto_sha256":"bd4d067d1ff2980db99a7527d21f9f381d996bb0a2d63933e30f7bcaecb2d372","pliego":"docs/corpus/staging/2026-11-04-hn-001-tranche-a-drive/canonico-v2/ADJUDICACION_CLO_CODIGO_NINEZ.md","procedencia":"Fuentes mixtas acreditadas por el pliego D1–D8 firmado (ver estado_canonico de cada fila); sin V4/V5 hasta el SQL de visibilidad","norm_id":"HN:CODIGO_NINEZ","instrumento_id":"CODIGO_NINEZ","ingest_batch":"A03_CODIGO_NINEZ_01","ordinal":254,"article_sha256":"20e7ae1ad76671741a1eb5a12e534922978796991e61bd985c0e8b86c6b95db8","vigencia":"UNKNOWN","revision_pendiente":true,"marcas":[],"estado_canonico":"TEXTO_V8_D3","fuente_canonica":"V8_LA_GACETA_33222"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_NINEZ','241','8bf097625946eb22b7e3f25f6eca9cb23a4a261a7bc366f0c6d542b4cb6423ce','A03_CODIGO_NINEZ_01',now()),
('A03_CODIGO_NINEZ_01:CODIGO_NINEZ:242','mayalex_normativos','10_LEYES_REGLAMENTOS','El Recurso de Apelación procederá contra las resoluciones que:

a) Concedan el sobreseimiento provisional o definitivo; b) Decidan un incidente o excepción; c) Vinculen al Proceso; d) Ordenen la Detención Cautelar o la imposición de otras Medidas Cautelares y las modificaciones de la primera o de las segundas; e) Declaren la extinción de la acción penal o que Suspenda el Proceso a Prueba; f) Denieguen la Suspensión Condicional de Ej ecución de la Sanción; g) Ordenen una restricción provisional a un derecho fundamental; h) Decidan los juicios por Faltas; i) Modifiquen o sustituyan cualquier tipo de Sanción en su Ejecución; . j) Resuelvan la solicitud de revisión de las sanciones impuestas; y, k) Las demás expresamente establecidas en este Código.

La interposición del recurso no suspenderá la continuación del procedimiento, salvo en los casos en que por su propia naturaleza no pueda o no deba proseguirse.

Solamente se suspenderá la ejecución de las resoluciones apeladas en el caso a que se refiere el numeral f), y en los demás que determine el presente Código.

Las sentencias sobre Faltas, sólo serán apelables cuando violenten alguno de los derechos que, según el presente Código, le corresponde a El Niño(a).','242','Código de la Niñez y de la Adolescencia (Decreto 73-96), texto canónico v2 con las reformas del Decreto 35-2013 (La Gaceta 33,222)','{"texto_origen":"CANONICO_D3_FUENTES_MIXTAS","transcripcion_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","text_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","cotejado_por":"Abg. y Not. Fredy Omar Pinel Flores, propietario_despacho (CLO / Director Maya Lex), firma D3 del 2026-11-18 sobre la v2 de HN:CODIGO_NINEZ (ADJUDICACION_CLO_CODIGO_NINEZ.md §3)","manifiesto_sha256":"bd4d067d1ff2980db99a7527d21f9f381d996bb0a2d63933e30f7bcaecb2d372","pliego":"docs/corpus/staging/2026-11-04-hn-001-tranche-a-drive/canonico-v2/ADJUDICACION_CLO_CODIGO_NINEZ.md","procedencia":"Fuentes mixtas acreditadas por el pliego D1–D8 firmado (ver estado_canonico de cada fila); sin V4/V5 hasta el SQL de visibilidad","norm_id":"HN:CODIGO_NINEZ","instrumento_id":"CODIGO_NINEZ","ingest_batch":"A03_CODIGO_NINEZ_01","ordinal":255,"article_sha256":"12bf8ff0df9488a73d26fbf7f1411d28106e972a8f0034b96da4efc15cf676cc","vigencia":"UNKNOWN","revision_pendiente":true,"marcas":[],"estado_canonico":"TEXTO_V8_D3","fuente_canonica":"V8_LA_GACETA_33222"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_NINEZ','242','86d135727e0c06628708d7fb75ea574cacac00a8bf5ce27151f66003f89a7e50','A03_CODIGO_NINEZ_01',now()),
('A03_CODIGO_NINEZ_01:CODIGO_NINEZ:243','mayalex_normativos','10_LEYES_REGLAMENTOS','La Ejecución de las sanciones deberá procurar que el Sancionado alcance su desarrollo personal integral, la inserción a su familia y a la sociedad, así como el desarrollo pleno de sus capacidades y su sentido de responsabilidad.

Para lograr los objetivos de la Ejecución se promoverá:

a) Satisfacer sus necesidades básicas; b) Posibilitar su desarrollo personal; c) Reforzar su sentimiento de dignidad y autoestima;

d) Incorporarle activamente en la elaboración ejecución de su Plan de Atención Individual; e) Minimizar los efectos negativos que la Sanción pudiera tener en su vida futura; f) Fomentar, cuando sea posible y conveniente, los vínculos familiares, sociales y culturales que contribuyan a su desarrollo personal; y, g) Promover las redes sociales entre el Sancionado, la familia y la comunidad.','243','Código de la Niñez y de la Adolescencia (Decreto 73-96), texto canónico v2 con las reformas del Decreto 35-2013 (La Gaceta 33,222)','{"texto_origen":"CANONICO_D3_FUENTES_MIXTAS","transcripcion_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","text_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","cotejado_por":"Abg. y Not. Fredy Omar Pinel Flores, propietario_despacho (CLO / Director Maya Lex), firma D3 del 2026-11-18 sobre la v2 de HN:CODIGO_NINEZ (ADJUDICACION_CLO_CODIGO_NINEZ.md §3)","manifiesto_sha256":"bd4d067d1ff2980db99a7527d21f9f381d996bb0a2d63933e30f7bcaecb2d372","pliego":"docs/corpus/staging/2026-11-04-hn-001-tranche-a-drive/canonico-v2/ADJUDICACION_CLO_CODIGO_NINEZ.md","procedencia":"Fuentes mixtas acreditadas por el pliego D1–D8 firmado (ver estado_canonico de cada fila); sin V4/V5 hasta el SQL de visibilidad","norm_id":"HN:CODIGO_NINEZ","instrumento_id":"CODIGO_NINEZ","ingest_batch":"A03_CODIGO_NINEZ_01","ordinal":256,"article_sha256":"be8b202a6a37c9cf8a4842c49ea7fc721eabfde3dc24e213539d84d964aed53e","vigencia":"UNKNOWN","revision_pendiente":true,"marcas":[],"estado_canonico":"TEXTO_V8_D3","fuente_canonica":"V8_LA_GACETA_33222"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_NINEZ','243','664bbea5e115e9cf6fda9fecc15d83cef468b7f2dcdec6667c13d21825cdc6fe','A03_CODIGO_NINEZ_01',now()),
('A03_CODIGO_NINEZ_01:CODIGO_NINEZ:244','mayalex_normativos','10_LEYES_REGLAMENTOS','Son Garantías y Derechos aplicables a la Ejecución, los siguientes:

a) Se apliquen en todo momento los Principios Rectores del Sistema, Garantías y Derechos establecidos en este Código y en especial los de este Título; b) Solicitar información sobre sus derechos a las personas o funcionarios bajo cuya responsabilidad se encuentre; c) Recibir información sobre los reglamentos internos de la institución a la que asiste o en la que se encuentre privado de libertad, especialmente las relativas a la normas disciplinarias que puedan aplicársele; d) Tener formas y medios pertinentes de comunicación con sus padres o responsables, así como con cualquier persona con quien mantengan un vínculo afectivo; e) Recibir los servicios de salud, educación y otras asistencias sociales por profesionales debidamente capacitados y en condiciones que garanticen su adecuado desarrollo físico y psicológico; f) A que a su ingreso y salida de los centros de privación de libertad, se le practique exámenes médicos autorizados, a fin de verificar su estado físico y mental y si han sido objeto de maltrato. g) Tomar en consideración la opinión del Sancionado en la implementación del Plan de Atención Individual de la Sanción; h) Tener garantizado el derecho a la Defensa Técnica durante toda la Fase de Ejecución; i) Presentar peticiones por si o mediante su Defensor ante cualquier autoridad y que se le garantice una rápida respuesta; j) Estar separado de los mayores de dieciocho (18) años de edad que se encuentren privados de libertad y preferiblemente estar con quienes formen parte de su mismo grupo etario; k) La ejecución de la sanción transcurra en programas lugares e instituciones lo más cercanos posibles a

lugar de residencia habitual y a no ser trasladado del centro de internamiento de modo arbitrario, a menos que sea sobre la base de una orden judicial; 1) Se respete su cultura y costumbres sociales, indígenas o afro descendientes; m) En caso de padecer una enfermedad en fase terminal o degenerativa del sistema nervioso, recibir atención y tratamiento médico especializado y el beneficio de excarcelación cuando proceda, debiendo garantizarse que sus derechos fundamentales les sean respetados y que no sea objeto de discriminación; n) No se limite su libertad u otros derechos, sino a consecuencia directa e inevitable de la Sanción impuesta; o) No ser sometido a restricciones o medidas disciplinarias que no estén debidamente establecidos en el respectivo Reglamento; p) No ser incomunicado en ningún caso y a que no se le imponga castigo físico ni medidas de aislamiento; y, q) Los demás derechos que sean compatibles con los principios que rigen este Título y los instrumentos internacionales sobre la materia.','244','Código de la Niñez y de la Adolescencia (Decreto 73-96), texto canónico v2 con las reformas del Decreto 35-2013 (La Gaceta 33,222)','{"texto_origen":"CANONICO_D3_FUENTES_MIXTAS","transcripcion_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","text_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","cotejado_por":"Abg. y Not. Fredy Omar Pinel Flores, propietario_despacho (CLO / Director Maya Lex), firma D3 del 2026-11-18 sobre la v2 de HN:CODIGO_NINEZ (ADJUDICACION_CLO_CODIGO_NINEZ.md §3)","manifiesto_sha256":"bd4d067d1ff2980db99a7527d21f9f381d996bb0a2d63933e30f7bcaecb2d372","pliego":"docs/corpus/staging/2026-11-04-hn-001-tranche-a-drive/canonico-v2/ADJUDICACION_CLO_CODIGO_NINEZ.md","procedencia":"Fuentes mixtas acreditadas por el pliego D1–D8 firmado (ver estado_canonico de cada fila); sin V4/V5 hasta el SQL de visibilidad","norm_id":"HN:CODIGO_NINEZ","instrumento_id":"CODIGO_NINEZ","ingest_batch":"A03_CODIGO_NINEZ_01","ordinal":257,"article_sha256":"79e5e863846dfbb783bfe6587e636ec3c66be8fa2fea55488964e1fac19c31e7","vigencia":"UNKNOWN","revision_pendiente":true,"marcas":[],"estado_canonico":"TEXTO_V8_D3","fuente_canonica":"V8_LA_GACETA_33222"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_NINEZ','244','8e43198caaeca10c9b38d1315bb7ea3d010fdacbb14e7a1a99ec86eea8755df1','A03_CODIGO_NINEZ_01',now()),
('A03_CODIGO_NINEZ_01:CODIGO_NINEZ:245','mayalex_normativos','10_LEYES_REGLAMENTOS','Todo Sancionado tendrá un Plan de Atención Individual, el cual será elaborado por el Instituto Hondureño de la Niñez y la Familia (IHNFA), con la activa participación de éste, así como de sus padres o responsables. En el cual se establecerán objetivos o metas reales para la Ejecución de la Sanción, debiéndose considerar sus condiciones y aptitudes personales y familiares.

El Plan de Atención Individual será remitido para su aprobación al Juez de Ejecución competente, a más tardar tres (3) semanas después de iniciado el cumplimiento de ésta. Para su aprobación deberá consultar al respectivo equipo técnico y tendrá el plazo de tres (3) días hábiles para resolver sobre si lo aprueba o no.','245','Código de la Niñez y de la Adolescencia (Decreto 73-96), texto canónico v2 con las reformas del Decreto 35-2013 (La Gaceta 33,222)','{"texto_origen":"CANONICO_D3_FUENTES_MIXTAS","transcripcion_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","text_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","cotejado_por":"Abg. y Not. Fredy Omar Pinel Flores, propietario_despacho (CLO / Director Maya Lex), firma D3 del 2026-11-18 sobre la v2 de HN:CODIGO_NINEZ (ADJUDICACION_CLO_CODIGO_NINEZ.md §3)","manifiesto_sha256":"bd4d067d1ff2980db99a7527d21f9f381d996bb0a2d63933e30f7bcaecb2d372","pliego":"docs/corpus/staging/2026-11-04-hn-001-tranche-a-drive/canonico-v2/ADJUDICACION_CLO_CODIGO_NINEZ.md","procedencia":"Fuentes mixtas acreditadas por el pliego D1–D8 firmado (ver estado_canonico de cada fila); sin V4/V5 hasta el SQL de visibilidad","norm_id":"HN:CODIGO_NINEZ","instrumento_id":"CODIGO_NINEZ","ingest_batch":"A03_CODIGO_NINEZ_01","ordinal":258,"article_sha256":"e20545b5ba82bafc7bfccb67d05684bba9600d84c6d17f420fc36496ac82e74e","vigencia":"UNKNOWN","revision_pendiente":true,"marcas":[],"estado_canonico":"TEXTO_V8_D3","fuente_canonica":"V8_LA_GACETA_33222"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_NINEZ','245','5a4e7a4835be4d9eda79366a817606a3a4a2ffb53af5ba4063fc8ea488b68020','A03_CODIGO_NINEZ_01',now()),
('A03_CODIGO_NINEZ_01:CODIGO_NINEZ:246','mayalex_normativos','10_LEYES_REGLAMENTOS','El Instituto Hondureño de la Niñez y la Familia (IHNFA) dará seguimiento y evaluará el Plan de Atención Individual, debiendo informar trimestralmente al Juez de Ejecución competente sobre los avances, obstáculos e incidencias, así como del ambiente familiar y social en que el Sancionado se desarrolle.

De ser necesario le realizará ajustes, debiendo informar de inmediato al Juez de Ejecución, para su confirmación, modificación o revocatoria.','246','Código de la Niñez y de la Adolescencia (Decreto 73-96), texto canónico v2 con las reformas del Decreto 35-2013 (La Gaceta 33,222)','{"texto_origen":"CANONICO_D3_FUENTES_MIXTAS","transcripcion_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","text_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","cotejado_por":"Abg. y Not. Fredy Omar Pinel Flores, propietario_despacho (CLO / Director Maya Lex), firma D3 del 2026-11-18 sobre la v2 de HN:CODIGO_NINEZ (ADJUDICACION_CLO_CODIGO_NINEZ.md §3)","manifiesto_sha256":"bd4d067d1ff2980db99a7527d21f9f381d996bb0a2d63933e30f7bcaecb2d372","pliego":"docs/corpus/staging/2026-11-04-hn-001-tranche-a-drive/canonico-v2/ADJUDICACION_CLO_CODIGO_NINEZ.md","procedencia":"Fuentes mixtas acreditadas por el pliego D1–D8 firmado (ver estado_canonico de cada fila); sin V4/V5 hasta el SQL de visibilidad","norm_id":"HN:CODIGO_NINEZ","instrumento_id":"CODIGO_NINEZ","ingest_batch":"A03_CODIGO_NINEZ_01","ordinal":259,"article_sha256":"cb8d5b425437507ac50eae576b8c4d590242a911e3bf4ac606b3e64b0c4d4e1c","vigencia":"UNKNOWN","revision_pendiente":true,"marcas":[],"estado_canonico":"TEXTO_V8_D3","fuente_canonica":"V8_LA_GACETA_33222"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_NINEZ','246','1ed40f1804a2ad3aa9d6192430789dccc1ff4f6537b2d89828dbeb5ef09105bc','A03_CODIGO_NINEZ_01',now()),
('A03_CODIGO_NINEZ_01:CODIGO_NINEZ:247','mayalex_normativos','10_LEYES_REGLAMENTOS','Para asegurar el correcto cumplimiento de este Título, el Instituto Hondureño de la Niñez y la Familia (IHNFA) tendrá las funciones de ejecución siguientes:

a) Formular, promover, ejecutar y fiscalizar, en coordinación con las instituciones del sector público y prjvado pertinentes, las políticas de prevención y protección integral a la Niñez que cumple sanciones; b) Crear, administrar, sostener, supervisar y dirigir los programas, centros de rehabilitación u organismos que requieran los Juzgados de la Niñez, para efectos de diagnóstico, tratamiento y seguimiento de los Niños(as) sancionados; c) Crear y mantener Programas de atención integral, con equipos multidisciplinarios de especialistas certificados en trabajo social, psicología, psiquiatría, medicina, orientación, Derecho, pedagogía y otros de carácter técnico que se estime conveniente, para brindar atención integral, supervisión y seguimiento durante la ejecución de las Sanciones, sin perjuicio del auxilio de los especialistas de las instituciones públicas o privadas cuando ello sea necesario; d) Asegurar el cumplimiento y garantía de los derechos que asisten a los Niños(as) sancionados; e) Brindar la información que requieran los Jueces de Ejecución y acatar las instrucciones de éstos, sobre la misma, los programas y proyectos, así como el manejo de los centros privativos de libertad; - f) Poner en conocimiento del Ministerio Público, los hechos constitutivos de delito que se susciten en los centros de privación de libertad; g) Certificar centros no estatales, para el cumplimiento de las sanciones privativas de libertad, cuando cumplan con las condiciones previstas en la Ley; h) Llevar un registro de las entidades sin fines de lucro interesadas en colaborar en el apoyo de la Ejecución de Sanciones No Privativas de Libertad, debiendo comprobar su idoneidad y la de los programas que ofrecen antes de darles su aprobación; i) Velar porque las instituciones coadyuvantes del proceso de reeducación y reinserción social de los Sancionados, se desenvuelvan en forma eficaz y

respetuosa de los derechos de éstos, dentro de los límites establecidos en este Título; j) Garantizar, coordinar y supervisar la existencia de programas de atención terapéutica y orientación psico-social, a quienes estén sancionados, en coordinación con sus familiares más cercanos; k) Organizar, supervisar y coordinar la administración de los centros de privación de libertad, encargados de la atención integral de los Niños(as) sancionados; 1) Establecer la coordinación a nivel local y con participación activa de la sociedad civil, las comunidades, los centros de educación formal y alternativa, patronatos y redes de apoyo, programas para el proceso de educación y reinserción social de los Niños(as) sancionados, así como llevar un registro de las mismas; m) Vigilar y asegurar que el Plan de Atención Individual sea acorde a los objetivos fijados en la sentencia definitiva respectiva, este Título y demás instrumentos . - aplicables, incluidos los internacionales; n) Solicitar al Juez de Ejecución, la modificación de la Sanción impuesta a un Sancionado, por otra menos gravosa, cuando lo considere pertinente o, cuando haya alcanzado los objetivos para los que fue impuesta; o) Hacer del conocimiento de las autoridades competentes, las acciones u omisiones que amenacen, violenten o pongan en peligro efectivo los bienes jurídicos protegidos de los Sancionados; y, p) Las demás atribuciones que este Título estipule y las que se establezcan mediante la respectiva reglamentación, siempre que garanticen los fines dispuestos en este Código.

Las autoridades de ejecución y cumplimiento de las sanciones, deberán orientarse y armonizarse con la Política General en materia de protección integral a la niñez y adolescencia a nivel nacional, rectorada por el Instituto Hondureño de la Niñez y la Familia (IHNFA), la cual deberá contener enfoque de justicia restaurativa.','247','Código de la Niñez y de la Adolescencia (Decreto 73-96), texto canónico v2 con las reformas del Decreto 35-2013 (La Gaceta 33,222)','{"texto_origen":"CANONICO_D3_FUENTES_MIXTAS","transcripcion_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","text_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","cotejado_por":"Abg. y Not. Fredy Omar Pinel Flores, propietario_despacho (CLO / Director Maya Lex), firma D3 del 2026-11-18 sobre la v2 de HN:CODIGO_NINEZ (ADJUDICACION_CLO_CODIGO_NINEZ.md §3)","manifiesto_sha256":"bd4d067d1ff2980db99a7527d21f9f381d996bb0a2d63933e30f7bcaecb2d372","pliego":"docs/corpus/staging/2026-11-04-hn-001-tranche-a-drive/canonico-v2/ADJUDICACION_CLO_CODIGO_NINEZ.md","procedencia":"Fuentes mixtas acreditadas por el pliego D1–D8 firmado (ver estado_canonico de cada fila); sin V4/V5 hasta el SQL de visibilidad","norm_id":"HN:CODIGO_NINEZ","instrumento_id":"CODIGO_NINEZ","ingest_batch":"A03_CODIGO_NINEZ_01","ordinal":260,"article_sha256":"1193c9b8193d65a19ae161299fd8eae265aa7886185f93315179492914ac14d4","vigencia":"UNKNOWN","revision_pendiente":true,"marcas":[],"estado_canonico":"TEXTO_V8_D3","fuente_canonica":"V8_LA_GACETA_33222"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_NINEZ','247','6640ba2839aa6e64dad5c89ead12d13e3e0525421853fbfa3601157389f1df1f','A03_CODIGO_NINEZ_01',now()),
('A03_CODIGO_NINEZ_01:CODIGO_NINEZ:248','mayalex_normativos','10_LEYES_REGLAMENTOS','Una vez dictada la Sentencia en la que se imponga alguna de las sanciones No Privativas de Libertad, el Juez citará al Sancionado y a sus padres o responsables a una audiencia, en la que dará a conocer los alcances de la Sanción impuesta y las consecuencias de su incumplimiento, de la cual dejará constancia por medio de un acta y girará comunicación de la misma a la institución estatal responsable de la Ejecución.','248','Código de la Niñez y de la Adolescencia (Decreto 73-96), texto canónico v2 con las reformas del Decreto 35-2013 (La Gaceta 33,222)','{"texto_origen":"CANONICO_D3_FUENTES_MIXTAS","transcripcion_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","text_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","cotejado_por":"Abg. y Not. Fredy Omar Pinel Flores, propietario_despacho (CLO / Director Maya Lex), firma D3 del 2026-11-18 sobre la v2 de HN:CODIGO_NINEZ (ADJUDICACION_CLO_CODIGO_NINEZ.md §3)","manifiesto_sha256":"bd4d067d1ff2980db99a7527d21f9f381d996bb0a2d63933e30f7bcaecb2d372","pliego":"docs/corpus/staging/2026-11-04-hn-001-tranche-a-drive/canonico-v2/ADJUDICACION_CLO_CODIGO_NINEZ.md","procedencia":"Fuentes mixtas acreditadas por el pliego D1–D8 firmado (ver estado_canonico de cada fila); sin V4/V5 hasta el SQL de visibilidad","norm_id":"HN:CODIGO_NINEZ","instrumento_id":"CODIGO_NINEZ","ingest_batch":"A03_CODIGO_NINEZ_01","ordinal":261,"article_sha256":"7690c034e96e0d6cd1ec11638747d352ed30dce7778a2ab357be4b5645b76e81","vigencia":"UNKNOWN","revision_pendiente":true,"marcas":[],"estado_canonico":"TEXTO_V8_D3","fuente_canonica":"V8_LA_GACETA_33222"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_NINEZ','248','4f33c4e4c58072e3eea97be0397f7673396776511494c8cbe80f3857980fb407','A03_CODIGO_NINEZ_01',now()),
('A03_CODIGO_NINEZ_01:CODIGO_NINEZ:249','mayalex_normativos','10_LEYES_REGLAMENTOS','La Amonestación se ejecutará en una audiencia en la que estarán presentes: el Sancionado, su defensor y padres o responsables, así como el representante del Ministerio Público.

El Juez se dirigirá al Sancionado en forma clara y directa, indicándole la infracción cometida, previniéndole de que, en caso de continuar con su conducta, podrían aplicársele sanciones más severas e invitándolo a aprovechar las oportunidades que se le conceden con este tipo de sanciones. También deberá recordar a los padres o responsables, sus deberes y responsabilidades en la formación, supervisión y educación del Sancionado.','249','Código de la Niñez y de la Adolescencia (Decreto 73-96), texto canónico v2 con las reformas del Decreto 35-2013 (La Gaceta 33,222)','{"texto_origen":"CANONICO_D3_FUENTES_MIXTAS","transcripcion_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","text_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","cotejado_por":"Abg. y Not. Fredy Omar Pinel Flores, propietario_despacho (CLO / Director Maya Lex), firma D3 del 2026-11-18 sobre la v2 de HN:CODIGO_NINEZ (ADJUDICACION_CLO_CODIGO_NINEZ.md §3)","manifiesto_sha256":"bd4d067d1ff2980db99a7527d21f9f381d996bb0a2d63933e30f7bcaecb2d372","pliego":"docs/corpus/staging/2026-11-04-hn-001-tranche-a-drive/canonico-v2/ADJUDICACION_CLO_CODIGO_NINEZ.md","procedencia":"Fuentes mixtas acreditadas por el pliego D1–D8 firmado (ver estado_canonico de cada fila); sin V4/V5 hasta el SQL de visibilidad","norm_id":"HN:CODIGO_NINEZ","instrumento_id":"CODIGO_NINEZ","ingest_batch":"A03_CODIGO_NINEZ_01","ordinal":262,"article_sha256":"cea7044f8aedebd8e86ce70e131fcb9e62e9d1f4a3da57e3b057af268298f39a","vigencia":"UNKNOWN","revision_pendiente":true,"marcas":[],"estado_canonico":"TEXTO_V8_D3","fuente_canonica":"V8_LA_GACETA_33222"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_NINEZ','249','6397252f9ee40a64374997e517af0351aa000ba9a141078d9c60cb1a29f0036c','A03_CODIGO_NINEZ_01',now()),
('A03_CODIGO_NINEZ_01:CODIGO_NINEZ:250','mayalex_normativos','10_LEYES_REGLAMENTOS','Para la ejecución de la Libertad Asistida, el Instituto Hondureño de la Niñez y la Familia (IHNFA), elaborará el Plan de Atención Individual, el cual contendrá los posibles programas educativos o formativos impuestos, el tipo de orientación requerida y el seguimiento para el cumplimiento de los fines de El Sistema.','250','Código de la Niñez y de la Adolescencia (Decreto 73-96), texto canónico v2 con las reformas del Decreto 35-2013 (La Gaceta 33,222)','{"texto_origen":"CANONICO_D3_FUENTES_MIXTAS","transcripcion_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","text_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","cotejado_por":"Abg. y Not. Fredy Omar Pinel Flores, propietario_despacho (CLO / Director Maya Lex), firma D3 del 2026-11-18 sobre la v2 de HN:CODIGO_NINEZ (ADJUDICACION_CLO_CODIGO_NINEZ.md §3)","manifiesto_sha256":"bd4d067d1ff2980db99a7527d21f9f381d996bb0a2d63933e30f7bcaecb2d372","pliego":"docs/corpus/staging/2026-11-04-hn-001-tranche-a-drive/canonico-v2/ADJUDICACION_CLO_CODIGO_NINEZ.md","procedencia":"Fuentes mixtas acreditadas por el pliego D1–D8 firmado (ver estado_canonico de cada fila); sin V4/V5 hasta el SQL de visibilidad","norm_id":"HN:CODIGO_NINEZ","instrumento_id":"CODIGO_NINEZ","ingest_batch":"A03_CODIGO_NINEZ_01","ordinal":263,"article_sha256":"d2a4f9aae5a323bcac861c10801bb88294aec0a4f36b5a10e1d4142ed2fef328","vigencia":"UNKNOWN","revision_pendiente":true,"marcas":[],"estado_canonico":"TEXTO_V8_D3","fuente_canonica":"V8_LA_GACETA_33222"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_NINEZ','250','638930351f842da1fe92708b9077c058fd069414e92d31a151eba23ab3f94c2d','A03_CODIGO_NINEZ_01',now()),
('A03_CODIGO_NINEZ_01:CODIGO_NINEZ:251','mayalex_normativos','10_LEYES_REGLAMENTOS','Para efectos de la Ejecución de la Prestación de Servicios a la Comunidad, las tareas de interés general que el Sancionado realice serán gratuitas.

Serán cumplidas en establecimientos públicos o privados sin fines de lucro, durante horas que no interrumpan sus estudios y/o el trabajo. Esta Sanción se cumplirá de preferencia en los programas comunitarios del lugar de origen o domicilio del Sancionado, respetando su origen étnico, cultural e ideología.

El Juez citará al Sancionado y a sus padres o responsable legal, para informarle de los términos en que se deberá cumplir el servicio comunitario.','251','Código de la Niñez y de la Adolescencia (Decreto 73-96), texto canónico v2 con las reformas del Decreto 35-2013 (La Gaceta 33,222)','{"texto_origen":"CANONICO_D3_FUENTES_MIXTAS","transcripcion_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","text_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","cotejado_por":"Abg. y Not. Fredy Omar Pinel Flores, propietario_despacho (CLO / Director Maya Lex), firma D3 del 2026-11-18 sobre la v2 de HN:CODIGO_NINEZ (ADJUDICACION_CLO_CODIGO_NINEZ.md §3)","manifiesto_sha256":"bd4d067d1ff2980db99a7527d21f9f381d996bb0a2d63933e30f7bcaecb2d372","pliego":"docs/corpus/staging/2026-11-04-hn-001-tranche-a-drive/canonico-v2/ADJUDICACION_CLO_CODIGO_NINEZ.md","procedencia":"Fuentes mixtas acreditadas por el pliego D1–D8 firmado (ver estado_canonico de cada fila); sin V4/V5 hasta el SQL de visibilidad","norm_id":"HN:CODIGO_NINEZ","instrumento_id":"CODIGO_NINEZ","ingest_batch":"A03_CODIGO_NINEZ_01","ordinal":264,"article_sha256":"b66cacbd3222e77a680aab10f0918c148d8836ce695d4d89c7a1804fc1eb7055","vigencia":"UNKNOWN","revision_pendiente":true,"marcas":[],"estado_canonico":"TEXTO_V8_D3","fuente_canonica":"V8_LA_GACETA_33222"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_NINEZ','251','add11388c37759e451f266aab6e81dadacef0482da853eae440a4f57cc934fc4','A03_CODIGO_NINEZ_01',now()),
('A03_CODIGO_NINEZ_01:CODIGO_NINEZ:252','mayalex_normativos','10_LEYES_REGLAMENTOS','El Instituto Hondureño de la Niñez y la Familia (IHNFA) formulará el Plan de Atención Individual para la Prestación de Servicios a la Comunidad, el cual contendrá al menos los siguientes requisitos específicos:

a) El lugar donde se debe realizar el servicio; b) El tipo de servicio que se debe prestar; c) El tiempo, horario y modalidades de prestación; y, d) La persona encargada del Sancionado, dentro de la entidad donde se va a prestar el servicio.

En todos los casos, el servicio deberá estar acorde con las aptitudes y habilidades del Sancionado, así como dirigirse a fortalecer en él los principios de convivencia social y otros establecidos por El Sistema. Asimismo se garantizará que no implique riesgo ni menoscabo de la dignidad de éste.

Tendrán preferencia los programas comunitarios del lugar de origen o domicilio del Sancionado.','252','Código de la Niñez y de la Adolescencia (Decreto 73-96), texto canónico v2 con las reformas del Decreto 35-2013 (La Gaceta 33,222)','{"texto_origen":"CANONICO_D3_FUENTES_MIXTAS","transcripcion_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","text_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","cotejado_por":"Abg. y Not. Fredy Omar Pinel Flores, propietario_despacho (CLO / Director Maya Lex), firma D3 del 2026-11-18 sobre la v2 de HN:CODIGO_NINEZ (ADJUDICACION_CLO_CODIGO_NINEZ.md §3)","manifiesto_sha256":"bd4d067d1ff2980db99a7527d21f9f381d996bb0a2d63933e30f7bcaecb2d372","pliego":"docs/corpus/staging/2026-11-04-hn-001-tranche-a-drive/canonico-v2/ADJUDICACION_CLO_CODIGO_NINEZ.md","procedencia":"Fuentes mixtas acreditadas por el pliego D1–D8 firmado (ver estado_canonico de cada fila); sin V4/V5 hasta el SQL de visibilidad","norm_id":"HN:CODIGO_NINEZ","instrumento_id":"CODIGO_NINEZ","ingest_batch":"A03_CODIGO_NINEZ_01","ordinal":265,"article_sha256":"f507076c4ccf4596598720b0dced4b05591a3420718347556c6deb7420827c6a","vigencia":"UNKNOWN","revision_pendiente":true,"marcas":[],"estado_canonico":"TEXTO_V8_D3","fuente_canonica":"V8_LA_GACETA_33222"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_NINEZ','252','0567f9e469b3d894e6a32bb5dca76b4eaeddcf53d4a7845603e6cbe6350ff299','A03_CODIGO_NINEZ_01',now()),
('A03_CODIGO_NINEZ_01:CODIGO_NINEZ:253','mayalex_normativos','10_LEYES_REGLAMENTOS','La Ejecución de la Reparación del Daño a la Víctima, aplicará cuando resultare afectado el patrimonio de ésta y se llegare a un adecuado acuerdo para reparar de inmediato el daño causado. En este caso, el Juez podrá ordenar:

a) La devolución de la cosa afectada; b) La reparación de la cosa afectada; o, c) El pago de una justa indemnización.

Para la sustitución de la reparación del daño a la víctima por una suma de dinero, se procurará en todo caso que este provenga del esfuerzo propio del Sancionado, así como que no provoque un traslado de su responsabilidad personal hacia sus padres o representantes.

En caso que proceda la sustitución y no esté determinada en la sentencia, el Juez valorará los daños causados a la víctima, con el fin de fijar el monto a pagar.

Cuando la reparación no sea inmediata, la sentencia deberá contener al menos:

a) La forma en la cual se reparará el daño, la que estará relacionada con el perjuicio causado por la infracción; b) El lugar donde se debe de cumplir la reparación o resarcimiento del daño; c) El plazo en el que se debe reparar el daño; y, d) Los días y horas dedicados a tal efecto, los cuales no podrán afectar sus estudios u ocupaciones laborales.','253','Código de la Niñez y de la Adolescencia (Decreto 73-96), texto canónico v2 con las reformas del Decreto 35-2013 (La Gaceta 33,222)','{"texto_origen":"CANONICO_D3_FUENTES_MIXTAS","transcripcion_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","text_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","cotejado_por":"Abg. y Not. Fredy Omar Pinel Flores, propietario_despacho (CLO / Director Maya Lex), firma D3 del 2026-11-18 sobre la v2 de HN:CODIGO_NINEZ (ADJUDICACION_CLO_CODIGO_NINEZ.md §3)","manifiesto_sha256":"bd4d067d1ff2980db99a7527d21f9f381d996bb0a2d63933e30f7bcaecb2d372","pliego":"docs/corpus/staging/2026-11-04-hn-001-tranche-a-drive/canonico-v2/ADJUDICACION_CLO_CODIGO_NINEZ.md","procedencia":"Fuentes mixtas acreditadas por el pliego D1–D8 firmado (ver estado_canonico de cada fila); sin V4/V5 hasta el SQL de visibilidad","norm_id":"HN:CODIGO_NINEZ","instrumento_id":"CODIGO_NINEZ","ingest_batch":"A03_CODIGO_NINEZ_01","ordinal":266,"article_sha256":"15a6a529e749e2a0f3650a864f206dbb24fffd2ef687975ce8780d1f4c08d198","vigencia":"UNKNOWN","revision_pendiente":true,"marcas":[],"estado_canonico":"TEXTO_V8_D3","fuente_canonica":"V8_LA_GACETA_33222"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_NINEZ','253','ab442c71b20eb4e8f6a91bd2b633bf0d54a4b96660f11f1c360d1e089c21e8d3','A03_CODIGO_NINEZ_01',now()),
('A03_CODIGO_NINEZ_01:CODIGO_NINEZ:254','mayalex_normativos','10_LEYES_REGLAMENTOS','La Ejecución de las sanciones no privativas de libertad de Ordenes de Orientación y Supervisión, consistirá en la incorporación del Sancionado y su familia al proceso reeducativo.

El Instituto Hondureño de la Niñez y la Familia (IHNFA) informarán periódicamente al Juez de Ejecución, sobre el cumplimiento y evaluación de esta Sanción.

En caso de incumplimiento injustificado, el Juez de Ejecución citará a audiencia en un plazo no mayor de quince (15) días a partir de la notificación del mismo, para resolver lo procedente.','254','Código de la Niñez y de la Adolescencia (Decreto 73-96), texto canónico v2 con las reformas del Decreto 35-2013 (La Gaceta 33,222)','{"texto_origen":"CANONICO_D3_FUENTES_MIXTAS","transcripcion_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","text_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","cotejado_por":"Abg. y Not. Fredy Omar Pinel Flores, propietario_despacho (CLO / Director Maya Lex), firma D3 del 2026-11-18 sobre la v2 de HN:CODIGO_NINEZ (ADJUDICACION_CLO_CODIGO_NINEZ.md §3)","manifiesto_sha256":"bd4d067d1ff2980db99a7527d21f9f381d996bb0a2d63933e30f7bcaecb2d372","pliego":"docs/corpus/staging/2026-11-04-hn-001-tranche-a-drive/canonico-v2/ADJUDICACION_CLO_CODIGO_NINEZ.md","procedencia":"Fuentes mixtas acreditadas por el pliego D1–D8 firmado (ver estado_canonico de cada fila); sin V4/V5 hasta el SQL de visibilidad","norm_id":"HN:CODIGO_NINEZ","instrumento_id":"CODIGO_NINEZ","ingest_batch":"A03_CODIGO_NINEZ_01","ordinal":267,"article_sha256":"d90bc9b88397561b5a80f12f8a85c8a5f8e869f6edfe09a073e901da99c2215d","vigencia":"UNKNOWN","revision_pendiente":true,"marcas":[],"estado_canonico":"TEXTO_V8_D3","fuente_canonica":"V8_LA_GACETA_33222"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_NINEZ','254','44cc37c35c876fdc78ae395542ca3609913f4cb32d68d81563a3e268e750f73e','A03_CODIGO_NINEZ_01',now()),
('A03_CODIGO_NINEZ_01:CODIGO_NINEZ:255','mayalex_normativos','10_LEYES_REGLAMENTOS','Firme la Sentencia que disponga la Semi-libertad, el Instituto Hondureño de la Niñez y la Familia (IHNFA), tendrá un plazo no mayor de quince (15) días hábiles, para formular y presentar al Juez, el respectivo Plan de Atención Individual.','255','Código de la Niñez y de la Adolescencia (Decreto 73-96), texto canónico v2 con las reformas del Decreto 35-2013 (La Gaceta 33,222)','{"texto_origen":"CANONICO_D3_FUENTES_MIXTAS","transcripcion_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","text_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","cotejado_por":"Abg. y Not. Fredy Omar Pinel Flores, propietario_despacho (CLO / Director Maya Lex), firma D3 del 2026-11-18 sobre la v2 de HN:CODIGO_NINEZ (ADJUDICACION_CLO_CODIGO_NINEZ.md §3)","manifiesto_sha256":"bd4d067d1ff2980db99a7527d21f9f381d996bb0a2d63933e30f7bcaecb2d372","pliego":"docs/corpus/staging/2026-11-04-hn-001-tranche-a-drive/canonico-v2/ADJUDICACION_CLO_CODIGO_NINEZ.md","procedencia":"Fuentes mixtas acreditadas por el pliego D1–D8 firmado (ver estado_canonico de cada fila); sin V4/V5 hasta el SQL de visibilidad","norm_id":"HN:CODIGO_NINEZ","instrumento_id":"CODIGO_NINEZ","ingest_batch":"A03_CODIGO_NINEZ_01","ordinal":268,"article_sha256":"77799641b0dbb0cc5ea63165c9c0731739f526577ffd84399c363bfcc0e3b8ec","vigencia":"UNKNOWN","revision_pendiente":true,"marcas":[],"estado_canonico":"TEXTO_V8_D3","fuente_canonica":"V8_LA_GACETA_33222"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_NINEZ','255','fd37021a356f328b839d65e16ad3bfd0bde9e572240d105b065d07cf165e0132','A03_CODIGO_NINEZ_01',now()),
('A03_CODIGO_NINEZ_01:CODIGO_NINEZ:256','mayalex_normativos','10_LEYES_REGLAMENTOS','La Privación de Libertad se ejecutará en centros estatales de internamiento especiales para Niños (as), que serán diferentes a los destinados para la población penitenciaria adulta. En ellos no se admitirá a nadie sin orden previa de autoridad judicial competente. La población privada de libertad, estará separada por su sexo y en razón de si su detención es Medida Cautelar o Sanción. Asimismo de manera progresiva por grupos etarios.

Cuando cumplan los dieciocho (18) años de edad, durante la Ejecución, éstos serán separados de las personas menores de esa edad, no obstante no se podrá ubicar con adultos.

La portación y uso de armas letales está terminantemente prohibida al interior de los centros.','256','Código de la Niñez y de la Adolescencia (Decreto 73-96), texto canónico v2 con las reformas del Decreto 35-2013 (La Gaceta 33,222)','{"texto_origen":"CANONICO_D3_FUENTES_MIXTAS","transcripcion_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","text_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","cotejado_por":"Abg. y Not. Fredy Omar Pinel Flores, propietario_despacho (CLO / Director Maya Lex), firma D3 del 2026-11-18 sobre la v2 de HN:CODIGO_NINEZ (ADJUDICACION_CLO_CODIGO_NINEZ.md §3)","manifiesto_sha256":"bd4d067d1ff2980db99a7527d21f9f381d996bb0a2d63933e30f7bcaecb2d372","pliego":"docs/corpus/staging/2026-11-04-hn-001-tranche-a-drive/canonico-v2/ADJUDICACION_CLO_CODIGO_NINEZ.md","procedencia":"Fuentes mixtas acreditadas por el pliego D1–D8 firmado (ver estado_canonico de cada fila); sin V4/V5 hasta el SQL de visibilidad","norm_id":"HN:CODIGO_NINEZ","instrumento_id":"CODIGO_NINEZ","ingest_batch":"A03_CODIGO_NINEZ_01","ordinal":269,"article_sha256":"1c8f9dfdca919498a0431d3fb9aabf59107cd53f5bdd193a17543e12a8bfba26","vigencia":"UNKNOWN","revision_pendiente":true,"marcas":[],"estado_canonico":"TEXTO_V8_D3","fuente_canonica":"V8_LA_GACETA_33222"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_NINEZ','256','571b60b11c2f4d8d6c66cd60b251f7875f4a02a172881c6e2e906f35616f8bb5','A03_CODIGO_NINEZ_01',now()),
('A03_CODIGO_NINEZ_01:CODIGO_NINEZ:257','mayalex_normativos','10_LEYES_REGLAMENTOS','El Plan de Atención Individual correspondiente deberá enviarse al Juez de Ejecución respectivo, en un plazo no mayor a quince (15) días del ingreso del Sancionado al centro. El Instituto Hondureño de la Niñez y la Familia (IHNFA) le informará trimestralmente sobre la situación del mismo y su desarrollo, con recomendaciones para el cumplimiento de los objetivos de este Título.

La inobservancia de lo dispuesto en el párrafo precedente, por parte de los empleados y funcionarios competentes, debe ser comunicada por el Juez al superior administrativo correspondiente, sin perjuicio de las sanciones administrativas y penales que pudieren corresponder.','257','Código de la Niñez y de la Adolescencia (Decreto 73-96), texto canónico v2 con las reformas del Decreto 35-2013 (La Gaceta 33,222)','{"texto_origen":"CANONICO_D3_FUENTES_MIXTAS","transcripcion_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","text_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","cotejado_por":"Abg. y Not. Fredy Omar Pinel Flores, propietario_despacho (CLO / Director Maya Lex), firma D3 del 2026-11-18 sobre la v2 de HN:CODIGO_NINEZ (ADJUDICACION_CLO_CODIGO_NINEZ.md §3)","manifiesto_sha256":"bd4d067d1ff2980db99a7527d21f9f381d996bb0a2d63933e30f7bcaecb2d372","pliego":"docs/corpus/staging/2026-11-04-hn-001-tranche-a-drive/canonico-v2/ADJUDICACION_CLO_CODIGO_NINEZ.md","procedencia":"Fuentes mixtas acreditadas por el pliego D1–D8 firmado (ver estado_canonico de cada fila); sin V4/V5 hasta el SQL de visibilidad","norm_id":"HN:CODIGO_NINEZ","instrumento_id":"CODIGO_NINEZ","ingest_batch":"A03_CODIGO_NINEZ_01","ordinal":270,"article_sha256":"869a84e7071b56e6bbabb7c1e4dfbb6619f1b08ef33e2f739c8fb9adb3330bd2","vigencia":"UNKNOWN","revision_pendiente":true,"marcas":[],"estado_canonico":"TEXTO_V8_D3","fuente_canonica":"V8_LA_GACETA_33222"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_NINEZ','257','59a5e993dc9bb95a0afbc56448c57013de022a753b8dbfe7d6061861bea524fd','A03_CODIGO_NINEZ_01',now()),
('A03_CODIGO_NINEZ_01:CODIGO_NINEZ:258','mayalex_normativos','10_LEYES_REGLAMENTOS','Los empleados y funcionarios de los centros privativos de libertad, serán reclutados, evaluados y seleccionados por concurso de oposición, los cuales deberán contar con aptitudes e idoneidad, valores y principios para ejercer sus funciones. Así como estar especializados en el trabajo con Niños(as) privados de libertad.','258','Código de la Niñez y de la Adolescencia (Decreto 73-96), texto canónico v2 con las reformas del Decreto 35-2013 (La Gaceta 33,222)','{"texto_origen":"CANONICO_D3_FUENTES_MIXTAS","transcripcion_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","text_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","cotejado_por":"Abg. y Not. Fredy Omar Pinel Flores, propietario_despacho (CLO / Director Maya Lex), firma D3 del 2026-11-18 sobre la v2 de HN:CODIGO_NINEZ (ADJUDICACION_CLO_CODIGO_NINEZ.md §3)","manifiesto_sha256":"bd4d067d1ff2980db99a7527d21f9f381d996bb0a2d63933e30f7bcaecb2d372","pliego":"docs/corpus/staging/2026-11-04-hn-001-tranche-a-drive/canonico-v2/ADJUDICACION_CLO_CODIGO_NINEZ.md","procedencia":"Fuentes mixtas acreditadas por el pliego D1–D8 firmado (ver estado_canonico de cada fila); sin V4/V5 hasta el SQL de visibilidad","norm_id":"HN:CODIGO_NINEZ","instrumento_id":"CODIGO_NINEZ","ingest_batch":"A03_CODIGO_NINEZ_01","ordinal":271,"article_sha256":"c67efb8ded43d0b0393406d9170e881e4ef114cb77a04710a61542d49c2f5159","vigencia":"UNKNOWN","revision_pendiente":true,"marcas":[],"estado_canonico":"TEXTO_V8_D3","fuente_canonica":"V8_LA_GACETA_33222"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_NINEZ','258','88258a40fd9e28fec74fc5408b2dc05af60d2cdc1afae60149e94d92e3dc9dfb','A03_CODIGO_NINEZ_01',now()),
('A03_CODIGO_NINEZ_01:CODIGO_NINEZ:259','mayalex_normativos','10_LEYES_REGLAMENTOS','El funcionamiento de los centros de internamiento o de privación de libertad estará regulado por un Reglamento Interno que dispondrá sobre la organización, deberes y prohibiciones de los servidores, deberes y derechos de los Niños (as) privados de libertad, las medidas de seguridad, la atención terapéutica, la orientación psicosocial, las actividades educativas y recreativas, así como las medidas disciplinarias y los procedimientos para su aplicación, que deberán garantizar el debido proceso.

Su contenido asegurará el cumplimiento de lo dispuesto en este Título.','259','Código de la Niñez y de la Adolescencia (Decreto 73-96), texto canónico v2 con las reformas del Decreto 35-2013 (La Gaceta 33,222)','{"texto_origen":"CANONICO_D3_FUENTES_MIXTAS","transcripcion_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","text_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","cotejado_por":"Abg. y Not. Fredy Omar Pinel Flores, propietario_despacho (CLO / Director Maya Lex), firma D3 del 2026-11-18 sobre la v2 de HN:CODIGO_NINEZ (ADJUDICACION_CLO_CODIGO_NINEZ.md §3)","manifiesto_sha256":"bd4d067d1ff2980db99a7527d21f9f381d996bb0a2d63933e30f7bcaecb2d372","pliego":"docs/corpus/staging/2026-11-04-hn-001-tranche-a-drive/canonico-v2/ADJUDICACION_CLO_CODIGO_NINEZ.md","procedencia":"Fuentes mixtas acreditadas por el pliego D1–D8 firmado (ver estado_canonico de cada fila); sin V4/V5 hasta el SQL de visibilidad","norm_id":"HN:CODIGO_NINEZ","instrumento_id":"CODIGO_NINEZ","ingest_batch":"A03_CODIGO_NINEZ_01","ordinal":272,"article_sha256":"ac1b0a6fc448d002e684ec7079ced6f094a200756d1810575885d429cf7c9536","vigencia":"UNKNOWN","revision_pendiente":true,"marcas":[],"estado_canonico":"TEXTO_V8_D3","fuente_canonica":"V8_LA_GACETA_33222"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_NINEZ','259','f2a158b9f31c266e8010e5fe61b3ea610971574b4c4d9ae4acab1b99757015b2','A03_CODIGO_NINEZ_01',now()),
('A03_CODIGO_NINEZ_01:CODIGO_NINEZ:260','mayalex_normativos','10_LEYES_REGLAMENTOS','En los centros de privación de libertad se llevará un registro integrado y un expediente por cada Niño(a) que ingrese, los que serán reservados.

El registro deberá ser foliado, sellado y autorizado por la institución de la que dependa el centro, donde se consignarán los datos personales, día y hora de ingreso, motivo del internamiento, traslados, salidas, liberación y entrega del Sancionado a sus padres o representantes legales, registro médico, así como cualquier otra información que se considere pertinente.','260','Código de la Niñez y de la Adolescencia (Decreto 73-96), texto canónico v2 con las reformas del Decreto 35-2013 (La Gaceta 33,222)','{"texto_origen":"CANONICO_D3_FUENTES_MIXTAS","transcripcion_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","text_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","cotejado_por":"Abg. y Not. Fredy Omar Pinel Flores, propietario_despacho (CLO / Director Maya Lex), firma D3 del 2026-11-18 sobre la v2 de HN:CODIGO_NINEZ (ADJUDICACION_CLO_CODIGO_NINEZ.md §3)","manifiesto_sha256":"bd4d067d1ff2980db99a7527d21f9f381d996bb0a2d63933e30f7bcaecb2d372","pliego":"docs/corpus/staging/2026-11-04-hn-001-tranche-a-drive/canonico-v2/ADJUDICACION_CLO_CODIGO_NINEZ.md","procedencia":"Fuentes mixtas acreditadas por el pliego D1–D8 firmado (ver estado_canonico de cada fila); sin V4/V5 hasta el SQL de visibilidad","norm_id":"HN:CODIGO_NINEZ","instrumento_id":"CODIGO_NINEZ","ingest_batch":"A03_CODIGO_NINEZ_01","ordinal":273,"article_sha256":"3a583329dc7f3383569975d0f8412cfa565f30f26aceb40da4af3810ecc127ab","vigencia":"UNKNOWN","revision_pendiente":true,"marcas":[],"estado_canonico":"TEXTO_V8_D3","fuente_canonica":"V8_LA_GACETA_33222"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_NINEZ','260','eb55476fb87e172cf9e8afed56ff7d5a99309004e35e9b6d02b20b320009c5fb','A03_CODIGO_NINEZ_01',now()),
('A03_CODIGO_NINEZ_01:CODIGO_NINEZ:261','mayalex_normativos','10_LEYES_REGLAMENTOS','En los centros de privación de libertad de El Sistema, se mantendrá documentación relacionada con la Convención Sobre los Derechos del Niño, como ser ejemplares de la misma y de este Código, así como catálogos de derechos, cuyo contenido será puesto en conocimiento de los Niños(as) y del personal a cuyo cargo esté su funcionamiento y cuidado.','261','Código de la Niñez y de la Adolescencia (Decreto 73-96), texto canónico v2 con las reformas del Decreto 35-2013 (La Gaceta 33,222)','{"texto_origen":"CANONICO_D3_FUENTES_MIXTAS","transcripcion_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","text_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","cotejado_por":"Abg. y Not. Fredy Omar Pinel Flores, propietario_despacho (CLO / Director Maya Lex), firma D3 del 2026-11-18 sobre la v2 de HN:CODIGO_NINEZ (ADJUDICACION_CLO_CODIGO_NINEZ.md §3)","manifiesto_sha256":"bd4d067d1ff2980db99a7527d21f9f381d996bb0a2d63933e30f7bcaecb2d372","pliego":"docs/corpus/staging/2026-11-04-hn-001-tranche-a-drive/canonico-v2/ADJUDICACION_CLO_CODIGO_NINEZ.md","procedencia":"Fuentes mixtas acreditadas por el pliego D1–D8 firmado (ver estado_canonico de cada fila); sin V4/V5 hasta el SQL de visibilidad","norm_id":"HN:CODIGO_NINEZ","instrumento_id":"CODIGO_NINEZ","ingest_batch":"A03_CODIGO_NINEZ_01","ordinal":274,"article_sha256":"152df7d6247ca770e9a8f37197408cf0200924b40890646af4f0670ce2eee2c0","vigencia":"UNKNOWN","revision_pendiente":true,"marcas":[],"estado_canonico":"TEXTO_V8_D3","fuente_canonica":"V8_LA_GACETA_33222"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_NINEZ','261','ebe15f53c7314661154ed02df3e980276101d537b71b76742d39848786165a08','A03_CODIGO_NINEZ_01',now()),
('A03_CODIGO_NINEZ_01:CODIGO_NINEZ:262','mayalex_normativos','10_LEYES_REGLAMENTOS','No serán aplicables la Conmuta y la Caución, en el caso de las Sanciones establecidas en este Título.','262','Código de la Niñez y de la Adolescencia (Decreto 73-96), texto canónico v2 con las reformas del Decreto 35-2013 (La Gaceta 33,222)','{"texto_origen":"CANONICO_D3_FUENTES_MIXTAS","transcripcion_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","text_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","cotejado_por":"Abg. y Not. Fredy Omar Pinel Flores, propietario_despacho (CLO / Director Maya Lex), firma D3 del 2026-11-18 sobre la v2 de HN:CODIGO_NINEZ (ADJUDICACION_CLO_CODIGO_NINEZ.md §3)","manifiesto_sha256":"bd4d067d1ff2980db99a7527d21f9f381d996bb0a2d63933e30f7bcaecb2d372","pliego":"docs/corpus/staging/2026-11-04-hn-001-tranche-a-drive/canonico-v2/ADJUDICACION_CLO_CODIGO_NINEZ.md","procedencia":"Fuentes mixtas acreditadas por el pliego D1–D8 firmado (ver estado_canonico de cada fila); sin V4/V5 hasta el SQL de visibilidad","norm_id":"HN:CODIGO_NINEZ","instrumento_id":"CODIGO_NINEZ","ingest_batch":"A03_CODIGO_NINEZ_01","ordinal":275,"article_sha256":"0c38b5ad8f05561c4bd9d27b3288137e9bc371843774dae3defdc8dfa43ff5dd","vigencia":"UNKNOWN","revision_pendiente":true,"marcas":[],"estado_canonico":"TEXTO_V8_D3","fuente_canonica":"V8_LA_GACETA_33222"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_NINEZ','262','425d84e7e246450d82a9d438fd5655e884d34ea63d7764f1cf7bc32fe381af1f','A03_CODIGO_NINEZ_01',now()),
('A03_CODIGO_NINEZ_01:CODIGO_NINEZ:263','mayalex_normativos','10_LEYES_REGLAMENTOS','A los fines de la aplicación de este Título se entenderá por delito grave, los delitos cuya sanción mínima sea de hasta ocho (8) años.','263','Código de la Niñez y de la Adolescencia (Decreto 73-96), texto canónico v2 con las reformas del Decreto 35-2013 (La Gaceta 33,222)','{"texto_origen":"CANONICO_D3_FUENTES_MIXTAS","transcripcion_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","text_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","cotejado_por":"Abg. y Not. Fredy Omar Pinel Flores, propietario_despacho (CLO / Director Maya Lex), firma D3 del 2026-11-18 sobre la v2 de HN:CODIGO_NINEZ (ADJUDICACION_CLO_CODIGO_NINEZ.md §3)","manifiesto_sha256":"bd4d067d1ff2980db99a7527d21f9f381d996bb0a2d63933e30f7bcaecb2d372","pliego":"docs/corpus/staging/2026-11-04-hn-001-tranche-a-drive/canonico-v2/ADJUDICACION_CLO_CODIGO_NINEZ.md","procedencia":"Fuentes mixtas acreditadas por el pliego D1–D8 firmado (ver estado_canonico de cada fila); sin V4/V5 hasta el SQL de visibilidad","norm_id":"HN:CODIGO_NINEZ","instrumento_id":"CODIGO_NINEZ","ingest_batch":"A03_CODIGO_NINEZ_01","ordinal":276,"article_sha256":"671c0515effd16489525763f25602c47d00ae0fda5bc4ea7c53c26bfc02ef1fa","vigencia":"UNKNOWN","revision_pendiente":true,"marcas":[],"estado_canonico":"TEXTO_V8_D3","fuente_canonica":"V8_LA_GACETA_33222"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_NINEZ','263','221172b325138c336f8d50ecb0a930eac27a7523e78cd83adfcbe18073135ad3','A03_CODIGO_NINEZ_01',now()),
('A03_CODIGO_NINEZ_01:CODIGO_NINEZ:264','mayalex_normativos','10_LEYES_REGLAMENTOS','La Corte Suprema de Justicia distribuirá las funciones de los Jueces de Garantías, de Juicio y de Ejecución, de conformidad a lo establecido en este Código, debiéndoles dotar de los recursos presupuestarios, materiales, personal y logística necesarios.

No obstante, su creación será progresiva, de conformidad a los programas, planes y presupuestos de que disponga.

En tanto no se creen, distribuirá las responsabilidades de éstos, de manera que funcionen de conformidad con los Principios Rectores y la debida separación de funciones entre la instrucción, el Juzgamiento y Ejecución.','264','Código de la Niñez y de la Adolescencia (Decreto 73-96), texto canónico v2 con las reformas del Decreto 35-2013 (La Gaceta 33,222)','{"texto_origen":"CANONICO_D3_FUENTES_MIXTAS","transcripcion_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","text_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","cotejado_por":"Abg. y Not. Fredy Omar Pinel Flores, propietario_despacho (CLO / Director Maya Lex), firma D3 del 2026-11-18 sobre la v2 de HN:CODIGO_NINEZ (ADJUDICACION_CLO_CODIGO_NINEZ.md §3)","manifiesto_sha256":"bd4d067d1ff2980db99a7527d21f9f381d996bb0a2d63933e30f7bcaecb2d372","pliego":"docs/corpus/staging/2026-11-04-hn-001-tranche-a-drive/canonico-v2/ADJUDICACION_CLO_CODIGO_NINEZ.md","procedencia":"Fuentes mixtas acreditadas por el pliego D1–D8 firmado (ver estado_canonico de cada fila); sin V4/V5 hasta el SQL de visibilidad","norm_id":"HN:CODIGO_NINEZ","instrumento_id":"CODIGO_NINEZ","ingest_batch":"A03_CODIGO_NINEZ_01","ordinal":277,"article_sha256":"8730abded29baf4298b7dbe6d942382b4e722045bf06e0dbc0deb1568ba8a4a5","vigencia":"UNKNOWN","revision_pendiente":true,"marcas":[],"estado_canonico":"TEXTO_V8_D3","fuente_canonica":"V8_LA_GACETA_33222"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_NINEZ','264','3f7ef7708384ee20007ac5b7140d8bed398449299a4c96b7c062033a52167180','A03_CODIGO_NINEZ_01',now()),
('A03_CODIGO_NINEZ_01:CODIGO_NINEZ:265','mayalex_normativos','10_LEYES_REGLAMENTOS','Con el propósito de hacer efectiva la aplicación del principio de justicia restaurativa para la Niñez Infractora de la Ley, el Estado creará o generará progresivamente los espacios y programas de justicia restaurativa que atenderán los casos referidos por las instancias de investigación o judiciales. En tanto propiciará la instrucción en esta materia de los funcionarios públicos vinculados a la administración de la justicia de la niñez infractora de la Ley, las Organizaciones No Gubernamentales y otros actores con interés legítimo en la aplicación de ese principio.','265','Código de la Niñez y de la Adolescencia (Decreto 73-96), texto canónico v2 con las reformas del Decreto 35-2013 (La Gaceta 33,222)','{"texto_origen":"CANONICO_D3_FUENTES_MIXTAS","transcripcion_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","text_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","cotejado_por":"Abg. y Not. Fredy Omar Pinel Flores, propietario_despacho (CLO / Director Maya Lex), firma D3 del 2026-11-18 sobre la v2 de HN:CODIGO_NINEZ (ADJUDICACION_CLO_CODIGO_NINEZ.md §3)","manifiesto_sha256":"bd4d067d1ff2980db99a7527d21f9f381d996bb0a2d63933e30f7bcaecb2d372","pliego":"docs/corpus/staging/2026-11-04-hn-001-tranche-a-drive/canonico-v2/ADJUDICACION_CLO_CODIGO_NINEZ.md","procedencia":"Fuentes mixtas acreditadas por el pliego D1–D8 firmado (ver estado_canonico de cada fila); sin V4/V5 hasta el SQL de visibilidad","norm_id":"HN:CODIGO_NINEZ","instrumento_id":"CODIGO_NINEZ","ingest_batch":"A03_CODIGO_NINEZ_01","ordinal":278,"article_sha256":"918f81a76c7ad19d1cecc13a84d6cf4b7348af119a864fe1d47732286fbef14f","vigencia":"UNKNOWN","revision_pendiente":true,"marcas":[],"estado_canonico":"TEXTO_V8_D3","fuente_canonica":"V8_LA_GACETA_33222"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_NINEZ','265','faa84b97693c44db97dc504ff1b9cfa41de06fbd241c245446836a646b51c6ff','A03_CODIGO_NINEZ_01',now()),
('A03_CODIGO_NINEZ_01:CODIGO_NINEZ:266','mayalex_normativos','10_LEYES_REGLAMENTOS','Las acciones que tengan como finalidad restablecer a un niño en el goce de sus derechos serán ejercitadas ante el Juez de la Niñez competente.

Las acciones en esta materia serán públicas.

En los correspondientes juicios se procederá breve y sumariamente.','266','Código de la Niñez y de la Adolescencia (Decreto 73-96), texto canónico v2 con las reformas del Decreto 35-2013 (La Gaceta 33,222)','{"texto_origen":"CANONICO_D3_FUENTES_MIXTAS","transcripcion_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","text_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","cotejado_por":"Abg. y Not. Fredy Omar Pinel Flores, propietario_despacho (CLO / Director Maya Lex), firma D3 del 2026-11-18 sobre la v2 de HN:CODIGO_NINEZ (ADJUDICACION_CLO_CODIGO_NINEZ.md §3)","manifiesto_sha256":"bd4d067d1ff2980db99a7527d21f9f381d996bb0a2d63933e30f7bcaecb2d372","pliego":"docs/corpus/staging/2026-11-04-hn-001-tranche-a-drive/canonico-v2/ADJUDICACION_CLO_CODIGO_NINEZ.md","procedencia":"Fuentes mixtas acreditadas por el pliego D1–D8 firmado (ver estado_canonico de cada fila); sin V4/V5 hasta el SQL de visibilidad","norm_id":"HN:CODIGO_NINEZ","instrumento_id":"CODIGO_NINEZ","ingest_batch":"A03_CODIGO_NINEZ_01","ordinal":279,"article_sha256":"a0aa4745c523ca0bfc37b36b2055dc180eaecd03cccfa09017885faef9b43846","vigencia":"UNKNOWN","revision_pendiente":true,"marcas":[],"estado_canonico":"TEXTO_A03_DICTAMINADO_CLO","fuente_canonica":"A03_CONSOLIDADO_DICTAMINADO"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_NINEZ','266','ea3f778929246de6c8528f2e2fb1d8db7d459a13bf84519d9a789fb12f9a2c09','A03_CODIGO_NINEZ_01',now()),
('A03_CODIGO_NINEZ_01:CODIGO_NINEZ:267','mayalex_normativos','10_LEYES_REGLAMENTOS','En el juicio que tenga por objeto una obligación de hacer o no hacer respecto a los derechos sociales y difusos de un niño, el juez ordenará su cumplimiento o dictará providencias que le aseguren su resultado en un plazo razonablemente breve.','267','Código de la Niñez y de la Adolescencia (Decreto 73-96), texto canónico v2 con las reformas del Decreto 35-2013 (La Gaceta 33,222)','{"texto_origen":"CANONICO_D3_FUENTES_MIXTAS","transcripcion_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","text_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","cotejado_por":"Abg. y Not. Fredy Omar Pinel Flores, propietario_despacho (CLO / Director Maya Lex), firma D3 del 2026-11-18 sobre la v2 de HN:CODIGO_NINEZ (ADJUDICACION_CLO_CODIGO_NINEZ.md §3)","manifiesto_sha256":"bd4d067d1ff2980db99a7527d21f9f381d996bb0a2d63933e30f7bcaecb2d372","pliego":"docs/corpus/staging/2026-11-04-hn-001-tranche-a-drive/canonico-v2/ADJUDICACION_CLO_CODIGO_NINEZ.md","procedencia":"Fuentes mixtas acreditadas por el pliego D1–D8 firmado (ver estado_canonico de cada fila); sin V4/V5 hasta el SQL de visibilidad","norm_id":"HN:CODIGO_NINEZ","instrumento_id":"CODIGO_NINEZ","ingest_batch":"A03_CODIGO_NINEZ_01","ordinal":280,"article_sha256":"2c3205529c846c8a667acf58f760ad9342a362e9c0b179895d2ea89ece824015","vigencia":"UNKNOWN","revision_pendiente":true,"marcas":[],"estado_canonico":"TEXTO_A03_DICTAMINADO_CLO","fuente_canonica":"A03_CONSOLIDADO_DICTAMINADO"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_NINEZ','267','86dbd1717a9af98a975d0e90c532d9c631477f38b3b4bc6bf5cd42ca2e18363d','A03_CODIGO_NINEZ_01',now()),
('A03_CODIGO_NINEZ_01:CODIGO_NINEZ:268','mayalex_normativos','10_LEYES_REGLAMENTOS','Una vez ejercitada una acción de restitución de derechos ésta no podrá ser retirada ni desistida.','268','Código de la Niñez y de la Adolescencia (Decreto 73-96), texto canónico v2 con las reformas del Decreto 35-2013 (La Gaceta 33,222)','{"texto_origen":"CANONICO_D3_FUENTES_MIXTAS","transcripcion_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","text_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","cotejado_por":"Abg. y Not. Fredy Omar Pinel Flores, propietario_despacho (CLO / Director Maya Lex), firma D3 del 2026-11-18 sobre la v2 de HN:CODIGO_NINEZ (ADJUDICACION_CLO_CODIGO_NINEZ.md §3)","manifiesto_sha256":"bd4d067d1ff2980db99a7527d21f9f381d996bb0a2d63933e30f7bcaecb2d372","pliego":"docs/corpus/staging/2026-11-04-hn-001-tranche-a-drive/canonico-v2/ADJUDICACION_CLO_CODIGO_NINEZ.md","procedencia":"Fuentes mixtas acreditadas por el pliego D1–D8 firmado (ver estado_canonico de cada fila); sin V4/V5 hasta el SQL de visibilidad","norm_id":"HN:CODIGO_NINEZ","instrumento_id":"CODIGO_NINEZ","ingest_batch":"A03_CODIGO_NINEZ_01","ordinal":281,"article_sha256":"3aa797cb1221a24ee5dc32220b37225fdc0dd8282f5f3ae5c7a22b38b1aff466","vigencia":"UNKNOWN","revision_pendiente":true,"marcas":[],"estado_canonico":"TEXTO_A03_DICTAMINADO_CLO","fuente_canonica":"A03_CONSOLIDADO_DICTAMINADO"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_NINEZ','268','a73138aec9a724e3d1ebb73eb5817b392415ca3a965049abfd4623b42d4c592f','A03_CODIGO_NINEZ_01',now()),
('A03_CODIGO_NINEZ_01:CODIGO_NINEZ:269','mayalex_normativos','10_LEYES_REGLAMENTOS','El Instituto Hondureño de la Niñez y la Familia será el órgano encargado de coordinar a los sectores públicos y privados para el estudio, promoción, ejecución y fiscalización de las políticas generales de prevención y protección integral a la niñez.','269','Código de la Niñez y de la Adolescencia (Decreto 73-96), texto canónico v2 con las reformas del Decreto 35-2013 (La Gaceta 33,222)','{"texto_origen":"CANONICO_D3_FUENTES_MIXTAS","transcripcion_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","text_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","cotejado_por":"Abg. y Not. Fredy Omar Pinel Flores, propietario_despacho (CLO / Director Maya Lex), firma D3 del 2026-11-18 sobre la v2 de HN:CODIGO_NINEZ (ADJUDICACION_CLO_CODIGO_NINEZ.md §3)","manifiesto_sha256":"bd4d067d1ff2980db99a7527d21f9f381d996bb0a2d63933e30f7bcaecb2d372","pliego":"docs/corpus/staging/2026-11-04-hn-001-tranche-a-drive/canonico-v2/ADJUDICACION_CLO_CODIGO_NINEZ.md","procedencia":"Fuentes mixtas acreditadas por el pliego D1–D8 firmado (ver estado_canonico de cada fila); sin V4/V5 hasta el SQL de visibilidad","norm_id":"HN:CODIGO_NINEZ","instrumento_id":"CODIGO_NINEZ","ingest_batch":"A03_CODIGO_NINEZ_01","ordinal":282,"article_sha256":"6d8005aa6ec644b7d04d9a15e848bec697b87c583d7e57c4803029db4d8c34ea","vigencia":"UNKNOWN","revision_pendiente":true,"marcas":[],"estado_canonico":"TEXTO_A03_DICTAMINADO_CLO","fuente_canonica":"A03_CONSOLIDADO_DICTAMINADO"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_NINEZ','269','a11ea12bd703248a0bfd7548c5e1e0f91174e26dc949f64cb439b1873a982dad','A03_CODIGO_NINEZ_01',now()),
('A03_CODIGO_NINEZ_01:CODIGO_NINEZ:270','mayalex_normativos','10_LEYES_REGLAMENTOS','El Instituto Hondureño de la Niñez y la Familia creará y fomentará servicios:

a) Socio-educativos para niños infractores de la ley penal con personal capacitado en el área social, pedagógica, psicológica y legal;

b) Para niños amenazados o privados de sus derechos que estén en proceso de encontrar un hogar; y, c) Sociales, psicológicos, psiquiátricos y otros especiales que se consideren necesarios para apoyar el sano desarrollo de la niñez.','270','Código de la Niñez y de la Adolescencia (Decreto 73-96), texto canónico v2 con las reformas del Decreto 35-2013 (La Gaceta 33,222)','{"texto_origen":"CANONICO_D3_FUENTES_MIXTAS","transcripcion_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","text_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","cotejado_por":"Abg. y Not. Fredy Omar Pinel Flores, propietario_despacho (CLO / Director Maya Lex), firma D3 del 2026-11-18 sobre la v2 de HN:CODIGO_NINEZ (ADJUDICACION_CLO_CODIGO_NINEZ.md §3)","manifiesto_sha256":"bd4d067d1ff2980db99a7527d21f9f381d996bb0a2d63933e30f7bcaecb2d372","pliego":"docs/corpus/staging/2026-11-04-hn-001-tranche-a-drive/canonico-v2/ADJUDICACION_CLO_CODIGO_NINEZ.md","procedencia":"Fuentes mixtas acreditadas por el pliego D1–D8 firmado (ver estado_canonico de cada fila); sin V4/V5 hasta el SQL de visibilidad","norm_id":"HN:CODIGO_NINEZ","instrumento_id":"CODIGO_NINEZ","ingest_batch":"A03_CODIGO_NINEZ_01","ordinal":283,"article_sha256":"46c3ff8b64ead2da2c84ed3e7631ab0f1d40e315d87f359693e3b5b4a974e004","vigencia":"UNKNOWN","revision_pendiente":true,"marcas":[],"estado_canonico":"TEXTO_A03_DICTAMINADO_CLO","fuente_canonica":"A03_CONSOLIDADO_DICTAMINADO"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_NINEZ','270','b8fee3cfbd6522df2b8c58743dddd6d2bd4d8bda3d48d54c4c9ab6b435505517','A03_CODIGO_NINEZ_01',now()),
('A03_CODIGO_NINEZ_01:CODIGO_NINEZ:271','mayalex_normativos','10_LEYES_REGLAMENTOS','Las consejerías de familia u otras entidades análogas que cree el Estado y los centros de bienestar social y de seguridad pública serán organismos ejecutivos de las cuestiones de su competencia.','271','Código de la Niñez y de la Adolescencia (Decreto 73-96), texto canónico v2 con las reformas del Decreto 35-2013 (La Gaceta 33,222)','{"texto_origen":"CANONICO_D3_FUENTES_MIXTAS","transcripcion_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","text_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","cotejado_por":"Abg. y Not. Fredy Omar Pinel Flores, propietario_despacho (CLO / Director Maya Lex), firma D3 del 2026-11-18 sobre la v2 de HN:CODIGO_NINEZ (ADJUDICACION_CLO_CODIGO_NINEZ.md §3)","manifiesto_sha256":"bd4d067d1ff2980db99a7527d21f9f381d996bb0a2d63933e30f7bcaecb2d372","pliego":"docs/corpus/staging/2026-11-04-hn-001-tranche-a-drive/canonico-v2/ADJUDICACION_CLO_CODIGO_NINEZ.md","procedencia":"Fuentes mixtas acreditadas por el pliego D1–D8 firmado (ver estado_canonico de cada fila); sin V4/V5 hasta el SQL de visibilidad","norm_id":"HN:CODIGO_NINEZ","instrumento_id":"CODIGO_NINEZ","ingest_batch":"A03_CODIGO_NINEZ_01","ordinal":284,"article_sha256":"a82e1947bc4478f33a746eb04fb9b43afbda0cfe80914a1cbea3b21dc094ff4a","vigencia":"UNKNOWN","revision_pendiente":true,"marcas":[],"estado_canonico":"TEXTO_A03_DICTAMINADO_CLO","fuente_canonica":"A03_CONSOLIDADO_DICTAMINADO"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_NINEZ','271','3ed4b71ea46f4914165727064ca39a63e188a0e800b21620a5c1f7e2e36aceb7','A03_CODIGO_NINEZ_01',now()),
('A03_CODIGO_NINEZ_01:CODIGO_NINEZ:272','mayalex_normativos','10_LEYES_REGLAMENTOS','Las entidades privadas autorizadas por el Estado para prestarle servicios a la niñez podrán, previo acuerdo con los organismos públicos, ejecutar políticas nacionales vinculadas con los niños en cuestiones médicas, psicológicas, psiquiátricas, sociales, legales y demás análogas. Podrán, asimismo, administrar fondos públicos.','272','Código de la Niñez y de la Adolescencia (Decreto 73-96), texto canónico v2 con las reformas del Decreto 35-2013 (La Gaceta 33,222)','{"texto_origen":"CANONICO_D3_FUENTES_MIXTAS","transcripcion_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","text_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","cotejado_por":"Abg. y Not. Fredy Omar Pinel Flores, propietario_despacho (CLO / Director Maya Lex), firma D3 del 2026-11-18 sobre la v2 de HN:CODIGO_NINEZ (ADJUDICACION_CLO_CODIGO_NINEZ.md §3)","manifiesto_sha256":"bd4d067d1ff2980db99a7527d21f9f381d996bb0a2d63933e30f7bcaecb2d372","pliego":"docs/corpus/staging/2026-11-04-hn-001-tranche-a-drive/canonico-v2/ADJUDICACION_CLO_CODIGO_NINEZ.md","procedencia":"Fuentes mixtas acreditadas por el pliego D1–D8 firmado (ver estado_canonico de cada fila); sin V4/V5 hasta el SQL de visibilidad","norm_id":"HN:CODIGO_NINEZ","instrumento_id":"CODIGO_NINEZ","ingest_batch":"A03_CODIGO_NINEZ_01","ordinal":285,"article_sha256":"682f9d456723b74b8b71a104259072470f8401f50d404bc37e4d65b4473e3053","vigencia":"UNKNOWN","revision_pendiente":true,"marcas":[],"estado_canonico":"TEXTO_A03_DICTAMINADO_CLO","fuente_canonica":"A03_CONSOLIDADO_DICTAMINADO"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_NINEZ','272','cdfd2a4bd97d2e67293ca60efd3ff076d4b2ae3f5afed687f7d1e1abd471e5bf','A03_CODIGO_NINEZ_01',now()),
('A03_CODIGO_NINEZ_01:CODIGO_NINEZ:273','mayalex_normativos','10_LEYES_REGLAMENTOS','Los establecimientos de prevención y protección a la niñez, públicos y privados, estarán sujetos al control y vigilancia de la Junta Nacional de Bienestar Social. A ella informarán de sus actividades y programas con la periodicidad y en la forma que la misma determine.

Estarán, además, salvo causa justificada, obligados a admitir los casos que les sean remitidos por los juzgados competentes.','273','Código de la Niñez y de la Adolescencia (Decreto 73-96), texto canónico v2 con las reformas del Decreto 35-2013 (La Gaceta 33,222)','{"texto_origen":"CANONICO_D3_FUENTES_MIXTAS","transcripcion_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","text_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","cotejado_por":"Abg. y Not. Fredy Omar Pinel Flores, propietario_despacho (CLO / Director Maya Lex), firma D3 del 2026-11-18 sobre la v2 de HN:CODIGO_NINEZ (ADJUDICACION_CLO_CODIGO_NINEZ.md §3)","manifiesto_sha256":"bd4d067d1ff2980db99a7527d21f9f381d996bb0a2d63933e30f7bcaecb2d372","pliego":"docs/corpus/staging/2026-11-04-hn-001-tranche-a-drive/canonico-v2/ADJUDICACION_CLO_CODIGO_NINEZ.md","procedencia":"Fuentes mixtas acreditadas por el pliego D1–D8 firmado (ver estado_canonico de cada fila); sin V4/V5 hasta el SQL de visibilidad","norm_id":"HN:CODIGO_NINEZ","instrumento_id":"CODIGO_NINEZ","ingest_batch":"A03_CODIGO_NINEZ_01","ordinal":286,"article_sha256":"b28810c8047867f56a833045057fd8cba3b40ba8f8c2fec3b31a562697742650","vigencia":"UNKNOWN","revision_pendiente":true,"marcas":[],"estado_canonico":"TEXTO_A03_DICTAMINADO_CLO","fuente_canonica":"A03_CONSOLIDADO_DICTAMINADO"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_NINEZ','273','7ad2ee487ee7eb45bd4947a8d7aeacff07cdfb9d15798e1f91cd6e9b490438e1','A03_CODIGO_NINEZ_01',now()),
('A03_CODIGO_NINEZ_01:CODIGO_NINEZ:274','mayalex_normativos','10_LEYES_REGLAMENTOS','El Instituto Hondureño de la Niñez y la Familia creará consejos, procuradurías de niños u otros organismos de carácter local para que colaboren con ella en su labor de protección y promoción de los derechos de los niños y en la detección de amenazas o violaciones de tales derechos.','274','Código de la Niñez y de la Adolescencia (Decreto 73-96), texto canónico v2 con las reformas del Decreto 35-2013 (La Gaceta 33,222)','{"texto_origen":"CANONICO_D3_FUENTES_MIXTAS","transcripcion_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","text_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","cotejado_por":"Abg. y Not. Fredy Omar Pinel Flores, propietario_despacho (CLO / Director Maya Lex), firma D3 del 2026-11-18 sobre la v2 de HN:CODIGO_NINEZ (ADJUDICACION_CLO_CODIGO_NINEZ.md §3)","manifiesto_sha256":"bd4d067d1ff2980db99a7527d21f9f381d996bb0a2d63933e30f7bcaecb2d372","pliego":"docs/corpus/staging/2026-11-04-hn-001-tranche-a-drive/canonico-v2/ADJUDICACION_CLO_CODIGO_NINEZ.md","procedencia":"Fuentes mixtas acreditadas por el pliego D1–D8 firmado (ver estado_canonico de cada fila); sin V4/V5 hasta el SQL de visibilidad","norm_id":"HN:CODIGO_NINEZ","instrumento_id":"CODIGO_NINEZ","ingest_batch":"A03_CODIGO_NINEZ_01","ordinal":287,"article_sha256":"8e5b1617450c490edc966a52ca8d75b5de4be7376dbfd8966a3f5526b719cb2c","vigencia":"UNKNOWN","revision_pendiente":true,"marcas":[],"estado_canonico":"TEXTO_A03_DICTAMINADO_CLO","fuente_canonica":"A03_CONSOLIDADO_DICTAMINADO"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_NINEZ','274','a3acce95ac0e3a8e970888e68e1b8a00ba58620fb5481e4b50a7dd3054618c65','A03_CODIGO_NINEZ_01',now()),
('A03_CODIGO_NINEZ_01:CODIGO_NINEZ:275','mayalex_normativos','10_LEYES_REGLAMENTOS','Las entidades a que se refiere el Artículo anterior podrán intervenir cuando:

a) Un niño sea sujeto activo o pasivo de una infracción, para notificar de inmediato a las autoridades competentes y al Ministerio Público;

b) Se vuelva necesaria la protección o restitución de los derechos sociales y difusos de los niños;

c) La conducta de un niño implique grave perjuicio para él mismo; y, ch) Deba darse seguimiento a los casos por ellos conocidos y a los resueltos por los juzgados competentes que les haya sido remitidos.','275','Código de la Niñez y de la Adolescencia (Decreto 73-96), texto canónico v2 con las reformas del Decreto 35-2013 (La Gaceta 33,222)','{"texto_origen":"CANONICO_D3_FUENTES_MIXTAS","transcripcion_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","text_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","cotejado_por":"Abg. y Not. Fredy Omar Pinel Flores, propietario_despacho (CLO / Director Maya Lex), firma D3 del 2026-11-18 sobre la v2 de HN:CODIGO_NINEZ (ADJUDICACION_CLO_CODIGO_NINEZ.md §3)","manifiesto_sha256":"bd4d067d1ff2980db99a7527d21f9f381d996bb0a2d63933e30f7bcaecb2d372","pliego":"docs/corpus/staging/2026-11-04-hn-001-tranche-a-drive/canonico-v2/ADJUDICACION_CLO_CODIGO_NINEZ.md","procedencia":"Fuentes mixtas acreditadas por el pliego D1–D8 firmado (ver estado_canonico de cada fila); sin V4/V5 hasta el SQL de visibilidad","norm_id":"HN:CODIGO_NINEZ","instrumento_id":"CODIGO_NINEZ","ingest_batch":"A03_CODIGO_NINEZ_01","ordinal":288,"article_sha256":"bc040da18d36a2047564fe515811094d573de57599e4f2625b2ed02a7e0f3fc3","vigencia":"UNKNOWN","revision_pendiente":true,"marcas":[],"estado_canonico":"TEXTO_A03_DICTAMINADO_CLO","fuente_canonica":"A03_CONSOLIDADO_DICTAMINADO"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_NINEZ','275','bb27d82b9926e3d8f91aaac201758dbe549740b122fb28d6d0d138235a510822','A03_CODIGO_NINEZ_01',now()),
('A03_CODIGO_NINEZ_01:CODIGO_NINEZ:276','mayalex_normativos','10_LEYES_REGLAMENTOS','La forma de integración de los consejos u organismos locales a que se refieren los Artículos precedentes y los requisitos que deben reunirse para formar parte de los mismos, serán reglamentariamente determinados por la Secretaría de Estado en los Despachos de Gobernación y Justicia a propuesta del Instituto Hondureño de la Niñez y la Familia.','276','Código de la Niñez y de la Adolescencia (Decreto 73-96), texto canónico v2 con las reformas del Decreto 35-2013 (La Gaceta 33,222)','{"texto_origen":"CANONICO_D3_FUENTES_MIXTAS","transcripcion_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","text_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","cotejado_por":"Abg. y Not. Fredy Omar Pinel Flores, propietario_despacho (CLO / Director Maya Lex), firma D3 del 2026-11-18 sobre la v2 de HN:CODIGO_NINEZ (ADJUDICACION_CLO_CODIGO_NINEZ.md §3)","manifiesto_sha256":"bd4d067d1ff2980db99a7527d21f9f381d996bb0a2d63933e30f7bcaecb2d372","pliego":"docs/corpus/staging/2026-11-04-hn-001-tranche-a-drive/canonico-v2/ADJUDICACION_CLO_CODIGO_NINEZ.md","procedencia":"Fuentes mixtas acreditadas por el pliego D1–D8 firmado (ver estado_canonico de cada fila); sin V4/V5 hasta el SQL de visibilidad","norm_id":"HN:CODIGO_NINEZ","instrumento_id":"CODIGO_NINEZ","ingest_batch":"A03_CODIGO_NINEZ_01","ordinal":289,"article_sha256":"b854f4bd122affdc715bfd460177f719a7c19c017428dc02b1571657b7429ff5","vigencia":"UNKNOWN","revision_pendiente":true,"marcas":[],"estado_canonico":"TEXTO_A03_DICTAMINADO_CLO","fuente_canonica":"A03_CONSOLIDADO_DICTAMINADO"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_NINEZ','276','c9b0c2d4781b55eb57b270dad81a0ac6b438b0cf189ab6a6a72e6c010c4124bf','A03_CODIGO_NINEZ_01',now()),
('A03_CODIGO_NINEZ_01:CODIGO_NINEZ:277','mayalex_normativos','10_LEYES_REGLAMENTOS','Los Juzgados de Letras de la Niñez serán los organismos encargados de conocer de todos los asuntos relacionados con niños infractores, así como de los casos en que sea necesario restituirle a un niño sus derechos conculcados.

Tales Juzgados sustituirán a los Juzgados de Letras de Menores a la fecha existentes.','277','Código de la Niñez y de la Adolescencia (Decreto 73-96), texto canónico v2 con las reformas del Decreto 35-2013 (La Gaceta 33,222)','{"texto_origen":"CANONICO_D3_FUENTES_MIXTAS","transcripcion_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","text_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","cotejado_por":"Abg. y Not. Fredy Omar Pinel Flores, propietario_despacho (CLO / Director Maya Lex), firma D3 del 2026-11-18 sobre la v2 de HN:CODIGO_NINEZ (ADJUDICACION_CLO_CODIGO_NINEZ.md §3)","manifiesto_sha256":"bd4d067d1ff2980db99a7527d21f9f381d996bb0a2d63933e30f7bcaecb2d372","pliego":"docs/corpus/staging/2026-11-04-hn-001-tranche-a-drive/canonico-v2/ADJUDICACION_CLO_CODIGO_NINEZ.md","procedencia":"Fuentes mixtas acreditadas por el pliego D1–D8 firmado (ver estado_canonico de cada fila); sin V4/V5 hasta el SQL de visibilidad","norm_id":"HN:CODIGO_NINEZ","instrumento_id":"CODIGO_NINEZ","ingest_batch":"A03_CODIGO_NINEZ_01","ordinal":290,"article_sha256":"e46fb9f3be2f937ff24ebeb4cc34ff8c34dfe012a23ee984e86bc3c6207fef83","vigencia":"UNKNOWN","revision_pendiente":true,"marcas":[],"estado_canonico":"TEXTO_A03_DICTAMINADO_CLO","fuente_canonica":"A03_CONSOLIDADO_DICTAMINADO"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_NINEZ','277','6dcc5df5337950f944a3bc02b0da37672bb86ddbb81b09cf0ec0e5dbf436fca4','A03_CODIGO_NINEZ_01',now()),
('A03_CODIGO_NINEZ_01:CODIGO_NINEZ:278','mayalex_normativos','10_LEYES_REGLAMENTOS','La Corte Suprema de Justicia determinará la estructura y personal necesarios para el funcionamiento de los Juzgados de Letras de la Niñez.','278','Código de la Niñez y de la Adolescencia (Decreto 73-96), texto canónico v2 con las reformas del Decreto 35-2013 (La Gaceta 33,222)','{"texto_origen":"CANONICO_D3_FUENTES_MIXTAS","transcripcion_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","text_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","cotejado_por":"Abg. y Not. Fredy Omar Pinel Flores, propietario_despacho (CLO / Director Maya Lex), firma D3 del 2026-11-18 sobre la v2 de HN:CODIGO_NINEZ (ADJUDICACION_CLO_CODIGO_NINEZ.md §3)","manifiesto_sha256":"bd4d067d1ff2980db99a7527d21f9f381d996bb0a2d63933e30f7bcaecb2d372","pliego":"docs/corpus/staging/2026-11-04-hn-001-tranche-a-drive/canonico-v2/ADJUDICACION_CLO_CODIGO_NINEZ.md","procedencia":"Fuentes mixtas acreditadas por el pliego D1–D8 firmado (ver estado_canonico de cada fila); sin V4/V5 hasta el SQL de visibilidad","norm_id":"HN:CODIGO_NINEZ","instrumento_id":"CODIGO_NINEZ","ingest_batch":"A03_CODIGO_NINEZ_01","ordinal":291,"article_sha256":"6bd0956a040639f5da0855c85b426acec34dd80e8a90e9d83e5f3d7acaf580b1","vigencia":"UNKNOWN","revision_pendiente":true,"marcas":[],"estado_canonico":"TEXTO_A03_DICTAMINADO_CLO","fuente_canonica":"A03_CONSOLIDADO_DICTAMINADO"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_NINEZ','278','141f47177a19ce679a0eddf0946c3eca913341ccbaf1f60daa23b1f53ea11807','A03_CODIGO_NINEZ_01',now()),
('A03_CODIGO_NINEZ_01:CODIGO_NINEZ:279','mayalex_normativos','10_LEYES_REGLAMENTOS','Para ser Juez de la Niñez se requiere ser hondureño, mayor de veinticinco años, del estado seglar, de reconocida honorabilidad y ostentar el título de Abogado o Licenciado en Ciencias Jurídicas y Sociales, estar debidamente colegiado y contar con suficiente experiencia.','279','Código de la Niñez y de la Adolescencia (Decreto 73-96), texto canónico v2 con las reformas del Decreto 35-2013 (La Gaceta 33,222)','{"texto_origen":"CANONICO_D3_FUENTES_MIXTAS","transcripcion_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","text_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","cotejado_por":"Abg. y Not. Fredy Omar Pinel Flores, propietario_despacho (CLO / Director Maya Lex), firma D3 del 2026-11-18 sobre la v2 de HN:CODIGO_NINEZ (ADJUDICACION_CLO_CODIGO_NINEZ.md §3)","manifiesto_sha256":"bd4d067d1ff2980db99a7527d21f9f381d996bb0a2d63933e30f7bcaecb2d372","pliego":"docs/corpus/staging/2026-11-04-hn-001-tranche-a-drive/canonico-v2/ADJUDICACION_CLO_CODIGO_NINEZ.md","procedencia":"Fuentes mixtas acreditadas por el pliego D1–D8 firmado (ver estado_canonico de cada fila); sin V4/V5 hasta el SQL de visibilidad","norm_id":"HN:CODIGO_NINEZ","instrumento_id":"CODIGO_NINEZ","ingest_batch":"A03_CODIGO_NINEZ_01","ordinal":292,"article_sha256":"5f67cef677564723be4912ac37b1a0ce24578af61c83d0620ecba49739a034b6","vigencia":"UNKNOWN","revision_pendiente":true,"marcas":[],"estado_canonico":"TEXTO_A03_DICTAMINADO_CLO","fuente_canonica":"A03_CONSOLIDADO_DICTAMINADO"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_NINEZ','279','4749e732dae54cb8c363b63e92507c5f8783085f50f8b953503da704ac91d8a1','A03_CODIGO_NINEZ_01',now()),
('A03_CODIGO_NINEZ_01:CODIGO_NINEZ:280','mayalex_normativos','10_LEYES_REGLAMENTOS','A partir de la fecha de entrada en vigencia del presente Código los Juzgados de Letras de Menores que existen en el país se denominarán Juzgados de Letras de la Niñez y cumplirán sus cometidos de acuerdo con sus disposiciones.','280','Código de la Niñez y de la Adolescencia (Decreto 73-96), texto canónico v2 con las reformas del Decreto 35-2013 (La Gaceta 33,222)','{"texto_origen":"CANONICO_D3_FUENTES_MIXTAS","transcripcion_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","text_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","cotejado_por":"Abg. y Not. Fredy Omar Pinel Flores, propietario_despacho (CLO / Director Maya Lex), firma D3 del 2026-11-18 sobre la v2 de HN:CODIGO_NINEZ (ADJUDICACION_CLO_CODIGO_NINEZ.md §3)","manifiesto_sha256":"bd4d067d1ff2980db99a7527d21f9f381d996bb0a2d63933e30f7bcaecb2d372","pliego":"docs/corpus/staging/2026-11-04-hn-001-tranche-a-drive/canonico-v2/ADJUDICACION_CLO_CODIGO_NINEZ.md","procedencia":"Fuentes mixtas acreditadas por el pliego D1–D8 firmado (ver estado_canonico de cada fila); sin V4/V5 hasta el SQL de visibilidad","norm_id":"HN:CODIGO_NINEZ","instrumento_id":"CODIGO_NINEZ","ingest_batch":"A03_CODIGO_NINEZ_01","ordinal":293,"article_sha256":"4758fcbac890b759e4c55a58622223e0cf05c0d58560b5fd1b975335c43ea2f7","vigencia":"UNKNOWN","revision_pendiente":true,"marcas":[],"estado_canonico":"TEXTO_A03_DICTAMINADO_CLO","fuente_canonica":"A03_CONSOLIDADO_DICTAMINADO"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_NINEZ','280','6af1842ef4627dd15b5f52df0ac0a73e4cad64a205536574995c51415984db64','A03_CODIGO_NINEZ_01',now()),
('A03_CODIGO_NINEZ_01:CODIGO_NINEZ:280-A','mayalex_normativos','10_LEYES_REGLAMENTOS','Toda referencia de cualquier ley o de este Código, a la Junta Nacional de Bienestar Social se entiende que corresponde plenamente al Instituto Hondureño de la Niñez y la Familia (IHNFA).','280-A','Código de la Niñez y de la Adolescencia (Decreto 73-96), texto canónico v2 con las reformas del Decreto 35-2013 (La Gaceta 33,222)','{"texto_origen":"CANONICO_D3_FUENTES_MIXTAS","transcripcion_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","text_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","cotejado_por":"Abg. y Not. Fredy Omar Pinel Flores, propietario_despacho (CLO / Director Maya Lex), firma D3 del 2026-11-18 sobre la v2 de HN:CODIGO_NINEZ (ADJUDICACION_CLO_CODIGO_NINEZ.md §3)","manifiesto_sha256":"bd4d067d1ff2980db99a7527d21f9f381d996bb0a2d63933e30f7bcaecb2d372","pliego":"docs/corpus/staging/2026-11-04-hn-001-tranche-a-drive/canonico-v2/ADJUDICACION_CLO_CODIGO_NINEZ.md","procedencia":"Fuentes mixtas acreditadas por el pliego D1–D8 firmado (ver estado_canonico de cada fila); sin V4/V5 hasta el SQL de visibilidad","norm_id":"HN:CODIGO_NINEZ","instrumento_id":"CODIGO_NINEZ","ingest_batch":"A03_CODIGO_NINEZ_01","ordinal":294,"article_sha256":"ecad27ec91f3a487e588081932330cf538efe106510b7c2bf2daf485ec3ef2f8","vigencia":"UNKNOWN","revision_pendiente":true,"marcas":[],"estado_canonico":"TEXTO_V8_D3_ADICIONADO","fuente_canonica":"V8_LA_GACETA_33222"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_NINEZ','280-A','ebc1b4adc490decdbea666c6d8ac6eac7b69ce203ba09779f4682e7798c8bcb5','A03_CODIGO_NINEZ_01',now()),
('A03_CODIGO_NINEZ_01:CODIGO_NINEZ:281','mayalex_normativos','10_LEYES_REGLAMENTOS','Las multas a que este Código se refiere serán pagadas en la Tesorería General de la República o en las instituciones del sistema financiero que la Secretaría de Estado en los Despachos de Hacienda y Crédito Público haya autorizado para efectuar recaudaciones por cuenta del Estado.

La interposición de recursos contra las multas impuestas no suspenderá la obligación de pagarlas inmediatamente. En caso de contravención, las que se encuentren pendientes devengarán el interés activo más alto que se halle vigente en el sistema bancario nacional.','281','Código de la Niñez y de la Adolescencia (Decreto 73-96), texto canónico v2 con las reformas del Decreto 35-2013 (La Gaceta 33,222)','{"texto_origen":"CANONICO_D3_FUENTES_MIXTAS","transcripcion_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","text_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","cotejado_por":"Abg. y Not. Fredy Omar Pinel Flores, propietario_despacho (CLO / Director Maya Lex), firma D3 del 2026-11-18 sobre la v2 de HN:CODIGO_NINEZ (ADJUDICACION_CLO_CODIGO_NINEZ.md §3)","manifiesto_sha256":"bd4d067d1ff2980db99a7527d21f9f381d996bb0a2d63933e30f7bcaecb2d372","pliego":"docs/corpus/staging/2026-11-04-hn-001-tranche-a-drive/canonico-v2/ADJUDICACION_CLO_CODIGO_NINEZ.md","procedencia":"Fuentes mixtas acreditadas por el pliego D1–D8 firmado (ver estado_canonico de cada fila); sin V4/V5 hasta el SQL de visibilidad","norm_id":"HN:CODIGO_NINEZ","instrumento_id":"CODIGO_NINEZ","ingest_batch":"A03_CODIGO_NINEZ_01","ordinal":295,"article_sha256":"d791050b77f958e5b9583664aa67adc52107a402f59a7c7f9c792ce0fe8007cc","vigencia":"UNKNOWN","revision_pendiente":true,"marcas":[],"estado_canonico":"TEXTO_A03_DICTAMINADO_CLO","fuente_canonica":"A03_CONSOLIDADO_DICTAMINADO"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_NINEZ','281','f42d30a3dae861c7adf3db9a6c20744ac7c8a996785475267dbc795e39f09cc8','A03_CODIGO_NINEZ_01',now()),
('A03_CODIGO_NINEZ_01:CODIGO_NINEZ:282','mayalex_normativos','10_LEYES_REGLAMENTOS','Los casos de sustracción internacional de niños y niñas serán sustanciados conforme a este Código, hasta que se emita la Ley especial sobre la materia.','282','Código de la Niñez y de la Adolescencia (Decreto 73-96), texto canónico v2 con las reformas del Decreto 35-2013 (La Gaceta 33,222)','{"texto_origen":"CANONICO_D3_FUENTES_MIXTAS","transcripcion_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","text_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","cotejado_por":"Abg. y Not. Fredy Omar Pinel Flores, propietario_despacho (CLO / Director Maya Lex), firma D3 del 2026-11-18 sobre la v2 de HN:CODIGO_NINEZ (ADJUDICACION_CLO_CODIGO_NINEZ.md §3)","manifiesto_sha256":"bd4d067d1ff2980db99a7527d21f9f381d996bb0a2d63933e30f7bcaecb2d372","pliego":"docs/corpus/staging/2026-11-04-hn-001-tranche-a-drive/canonico-v2/ADJUDICACION_CLO_CODIGO_NINEZ.md","procedencia":"Fuentes mixtas acreditadas por el pliego D1–D8 firmado (ver estado_canonico de cada fila); sin V4/V5 hasta el SQL de visibilidad","norm_id":"HN:CODIGO_NINEZ","instrumento_id":"CODIGO_NINEZ","ingest_batch":"A03_CODIGO_NINEZ_01","ordinal":296,"article_sha256":"f77b706fae854c1486bfecd632bec526acddde97ecc88ff8edfc9313572db5ab","vigencia":"UNKNOWN","revision_pendiente":true,"marcas":[],"estado_canonico":"TEXTO_V8_D3","fuente_canonica":"V8_LA_GACETA_33222"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_NINEZ','282','0272ed31a27e386b9ff310d696e668bc96650e7e3c44d488c602a1666b5ef2b9','A03_CODIGO_NINEZ_01',now()),
('A03_CODIGO_NINEZ_01:CODIGO_NINEZ:283','mayalex_normativos','10_LEYES_REGLAMENTOS','Los asuntos relacionados con infracciones a la ley penal que se encuentren en trámite a la fecha de entrada en vigencia del presente Código, se tramitarán y resolverán de acuerdo con lo prescrito por la Ley de Jurisdicción de Menores. Las medidas a aplicar, sin embargo, serán las previstas en este Código.','283','Código de la Niñez y de la Adolescencia (Decreto 73-96), texto canónico v2 con las reformas del Decreto 35-2013 (La Gaceta 33,222)','{"texto_origen":"CANONICO_D3_FUENTES_MIXTAS","transcripcion_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","text_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","cotejado_por":"Abg. y Not. Fredy Omar Pinel Flores, propietario_despacho (CLO / Director Maya Lex), firma D3 del 2026-11-18 sobre la v2 de HN:CODIGO_NINEZ (ADJUDICACION_CLO_CODIGO_NINEZ.md §3)","manifiesto_sha256":"bd4d067d1ff2980db99a7527d21f9f381d996bb0a2d63933e30f7bcaecb2d372","pliego":"docs/corpus/staging/2026-11-04-hn-001-tranche-a-drive/canonico-v2/ADJUDICACION_CLO_CODIGO_NINEZ.md","procedencia":"Fuentes mixtas acreditadas por el pliego D1–D8 firmado (ver estado_canonico de cada fila); sin V4/V5 hasta el SQL de visibilidad","norm_id":"HN:CODIGO_NINEZ","instrumento_id":"CODIGO_NINEZ","ingest_batch":"A03_CODIGO_NINEZ_01","ordinal":297,"article_sha256":"9999b5b9085f500527c7c887c4a2c7408b0fcecdb720b3e520354c448db51462","vigencia":"UNKNOWN","revision_pendiente":true,"marcas":[],"estado_canonico":"TEXTO_A03_DICTAMINADO_CLO","fuente_canonica":"A03_CONSOLIDADO_DICTAMINADO"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_NINEZ','283','ac41ae459faf5c45734a4449bfbb043a1f171681cbf1deec5162f1230122fb89','A03_CODIGO_NINEZ_01',now()),
('A03_CODIGO_NINEZ_01:CODIGO_NINEZ:284','mayalex_normativos','10_LEYES_REGLAMENTOS','Salvo para los efectos previstos en el Artículo anterior, el presente Código deroga la Ley de Jurisdicción de Menores contenida en el Decreto número 92 del 24 de noviembre de 1969. Deroga, asimismo, los Artículos 42 y 112 de la Ley de Policía, contenida en el Decreto número 7 del 8 de febrero de 1906 emitido por delegación de la Asamblea Nacional Constituyente por medio del Decreto número 76 del 19 de enero de 1906; 67 y 68 de la Ley del Servicio Militar contenida en el Decreto número 98-85 del 11 de julio de 1985; 129, 137, 138, 145, 146, 147, 148, 149, 150, 151, 152, 153, 154, 155, 156, 160, 164, 169, 170, 171, 172 y 206 del Código de Familia; 31, 32 párrafo tercero, 33, 128, 129, 131, 133, 173, 174, 188 y 190 del Código del Trabajo y las demás disposiciones legales que se le opongan.','284','Código de la Niñez y de la Adolescencia (Decreto 73-96), texto canónico v2 con las reformas del Decreto 35-2013 (La Gaceta 33,222)','{"texto_origen":"CANONICO_D3_FUENTES_MIXTAS","transcripcion_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","text_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","cotejado_por":"Abg. y Not. Fredy Omar Pinel Flores, propietario_despacho (CLO / Director Maya Lex), firma D3 del 2026-11-18 sobre la v2 de HN:CODIGO_NINEZ (ADJUDICACION_CLO_CODIGO_NINEZ.md §3)","manifiesto_sha256":"bd4d067d1ff2980db99a7527d21f9f381d996bb0a2d63933e30f7bcaecb2d372","pliego":"docs/corpus/staging/2026-11-04-hn-001-tranche-a-drive/canonico-v2/ADJUDICACION_CLO_CODIGO_NINEZ.md","procedencia":"Fuentes mixtas acreditadas por el pliego D1–D8 firmado (ver estado_canonico de cada fila); sin V4/V5 hasta el SQL de visibilidad","norm_id":"HN:CODIGO_NINEZ","instrumento_id":"CODIGO_NINEZ","ingest_batch":"A03_CODIGO_NINEZ_01","ordinal":298,"article_sha256":"55910fdd1885a05a4cd82ba1c17e12670456fe0121d559271219f5b535a8a112","vigencia":"UNKNOWN","revision_pendiente":true,"marcas":[],"estado_canonico":"TEXTO_A03_DICTAMINADO_CLO","fuente_canonica":"A03_CONSOLIDADO_DICTAMINADO"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_NINEZ','284','c97828b6b168c5e4686436d287a31c23577b8fb24a1a44509b58011e6bab5185','A03_CODIGO_NINEZ_01',now()),
('A03_CODIGO_NINEZ_01:CODIGO_NINEZ:285','mayalex_normativos','10_LEYES_REGLAMENTOS','Reformase el Artículo 4 de la Ley del Fondo Hondureño de Inversión Social, contenida en el Decreto número 12-90 del 22 de febrero de 1990, que en lo sucesivo se leerá así:

"Artículo 4. El Fondo, para los efectos del Artículo anterior, podrá: a)...; b)...; c)...; ch)...; d)...; e) Promover y financiar programas y proyectos de generación de empleo temporal y estacional para grupos urbanos y rurales afectados por situaciones de emergencia o por su difícil inserción en el mercado de trabajo o para mejorar las condiciones de vida y de trabajo de los niños que, conforme el Código de la Niñez y de la Adolescencia, pueden realizar labores remuneradas; f)...; g)...; y, h)...".','285','Código de la Niñez y de la Adolescencia (Decreto 73-96), texto canónico v2 con las reformas del Decreto 35-2013 (La Gaceta 33,222)','{"texto_origen":"CANONICO_D3_FUENTES_MIXTAS","transcripcion_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","text_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","cotejado_por":"Abg. y Not. Fredy Omar Pinel Flores, propietario_despacho (CLO / Director Maya Lex), firma D3 del 2026-11-18 sobre la v2 de HN:CODIGO_NINEZ (ADJUDICACION_CLO_CODIGO_NINEZ.md §3)","manifiesto_sha256":"bd4d067d1ff2980db99a7527d21f9f381d996bb0a2d63933e30f7bcaecb2d372","pliego":"docs/corpus/staging/2026-11-04-hn-001-tranche-a-drive/canonico-v2/ADJUDICACION_CLO_CODIGO_NINEZ.md","procedencia":"Fuentes mixtas acreditadas por el pliego D1–D8 firmado (ver estado_canonico de cada fila); sin V4/V5 hasta el SQL de visibilidad","norm_id":"HN:CODIGO_NINEZ","instrumento_id":"CODIGO_NINEZ","ingest_batch":"A03_CODIGO_NINEZ_01","ordinal":299,"article_sha256":"2cee3b44965ac45ef99c473278d9c93d756a2aac2c1fb6d35e3a4f083f493f9f","vigencia":"UNKNOWN","revision_pendiente":true,"marcas":[],"estado_canonico":"TEXTO_A03_DICTAMINADO_CLO","fuente_canonica":"A03_CONSOLIDADO_DICTAMINADO"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_NINEZ','285','717c605a72d32a2ce79e2b675c12b078221fdf2e09eb3421fe9280ea90b1cfc5','A03_CODIGO_NINEZ_01',now()),
('A03_CODIGO_NINEZ_01:CODIGO_NINEZ:286','mayalex_normativos','10_LEYES_REGLAMENTOS','Reformase el numeral 3 del Artículo 180 del Código de la Familia, que en lo sucesivo se leerá así:

“Artículo 180. La inscripción de la adopción, además de las indicaciones comunes a toda inscripción, deberá contener: 1)...; 2)...; y, 3) Referencia a la resolución en que se autoriza la adopción".','286','Código de la Niñez y de la Adolescencia (Decreto 73-96), texto canónico v2 con las reformas del Decreto 35-2013 (La Gaceta 33,222)','{"texto_origen":"CANONICO_D3_FUENTES_MIXTAS","transcripcion_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","text_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","cotejado_por":"Abg. y Not. Fredy Omar Pinel Flores, propietario_despacho (CLO / Director Maya Lex), firma D3 del 2026-11-18 sobre la v2 de HN:CODIGO_NINEZ (ADJUDICACION_CLO_CODIGO_NINEZ.md §3)","manifiesto_sha256":"bd4d067d1ff2980db99a7527d21f9f381d996bb0a2d63933e30f7bcaecb2d372","pliego":"docs/corpus/staging/2026-11-04-hn-001-tranche-a-drive/canonico-v2/ADJUDICACION_CLO_CODIGO_NINEZ.md","procedencia":"Fuentes mixtas acreditadas por el pliego D1–D8 firmado (ver estado_canonico de cada fila); sin V4/V5 hasta el SQL de visibilidad","norm_id":"HN:CODIGO_NINEZ","instrumento_id":"CODIGO_NINEZ","ingest_batch":"A03_CODIGO_NINEZ_01","ordinal":300,"article_sha256":"a1d6efa9c4fe5b1eb020d31b63bb6db5204324141283fef70cd99c957f621371","vigencia":"UNKNOWN","revision_pendiente":true,"marcas":[],"estado_canonico":"TEXTO_A03_DICTAMINADO_CLO","fuente_canonica":"A03_CONSOLIDADO_DICTAMINADO"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_NINEZ','286','82bbf79338b4df3c129d07e25938eecbea9874e56371afa95aacd38f799f90f0','A03_CODIGO_NINEZ_01',now())
